    snapshots: [],     // Ảnh chụp nhanh lịch sử [{ time, type, diaryCount, relationCount, archiveUpdated, archiveEntryCount, chapterTitle }]
    focusRoles: [],    // Nhân vật trọng điểm (chỉ định thủ công): [{ name, note }], hướng dẫn AI xoay quanh những nhân vật này khi viết nhật ký/tóm tắt
    archiveVectors: [], // Thư viện vector hồ sơ cốt truyện [{ id, text, category, vector }]
