// ============================================================
// Nhật ký nhân vật Plugin v2.0.0 — Lớp gọi API
// Đường dẫn: SillyTavern/extensions/character-diary/api.js
// ============================================================
'use strict';

/**
 * Cổng vào hợp nhất: Định tuyến đến API implementation tương ứng dựa trên settings.source
 * @param {Array<{role:string,content:string}>} messages
 * @param {object} s - settings
 * @returns {Promise<string>} Văn bản do AI trả về
 */
/**
 * Gọi API LLM, trả về { text, elapsed, tokenUsage }
 * @returns {Promise<{text:string, elapsed:number, tokenUsage:object|null}>}
 */
async function cdApiComplete(messages, s) {
  const start = Date.now();
  let text;
  // Ưu tiên theo nguồn mà người dùng đã cấu hình rõ ràng, nếu không thì suy luận theo các endpoint đã cấu hình; nếu đều không có thì dùng Tavern
  let effSrc = s.source === 'tavern' ? 'tavern' : s.source;
  if (!(effSrc === 'openai' || effSrc === 'claude' || effSrc === 'gemini') ||
      (effSrc !== 'tavern' && !s.endpoints?.[effSrc]?.url)) {
    effSrc = (s.endpoints?.openai?.url ? 'openai' :
              s.endpoints?.claude?.url ? 'claude' :
              s.endpoints?.gemini?.url ? 'gemini' : 'tavern');
  }
  switch (effSrc) {
    case 'tavern': text = await callTavern(messages, s); break;
    case 'openai': text = await callOpenAI(messages, s.endpoints.openai, s); break;
    case 'claude': text = await callClaude(messages, s.endpoints.claude, s); break;
    case 'gemini': text = await callGemini(messages, s.endpoints.gemini, s); break;
    default: throw new Error('Nguồn API không xác định: ' + effSrc);
  }
  const elapsed = Date.now() - start;
  // Đọc token usage có thể được ghi lại trong callXxx
  const tokenUsage = _cdLastTokenUsage;
  _cdLastTokenUsage = null; // Đặt lại sau khi dùng xong
  return { text, elapsed, tokenUsage };
}

/** Đi theo kết nối hiện tại của Tavern */
async function callTavern(messages, _s) {
  const ctx = SillyTavern.getContext();
  const ordered = messages.map(m => ({ role: m.role, content: m.content }));
  
  // Cách 1: generateRaw
  if (typeof generateRaw === 'function') {
    try {
      const result = await generateRaw({ ordered_prompts: ordered, should_stream: false });
      if (result) return result;
    } catch (e) { cdWarn('generateRaw thất bại', e); }
  }
  
  // Cách 2: generateQuietPrompt
  if (ctx && typeof ctx.generateQuietPrompt === 'function') {
    try {
      const quietPrompt = ordered.map(m => m.content).join('\n\n');
      const result = await ctx.generateQuietPrompt({ quietPrompt });
      if (result) return result;
    } catch (e) { cdWarn('generateQuietPrompt thất bại', e); }
  }

  // Cách 2.5: sendGenerationRequest (Cách tạo tĩnh tiêu chuẩn mới của ST, bản Tauri dùng tốt)
  if (ctx && typeof ctx.sendGenerationRequest === 'function') {
    try {
      const quiet_prompt = ordered.map(m => m.content).join('\n\n');
      const result = await ctx.sendGenerationRequest({ quiet_prompt, execute_senders: false });
      if (result) return result;
    } catch (e) { cdWarn('sendGenerationRequest thất bại', e); }
  }

  // Cách 3: generate (fallback)
  if (typeof generate === 'function') {
    return await generate({
      user_input: ordered.map(m => m.content).join('\n\n'),
      should_stream: false,
      overrides: {
        char_description: '', char_personality: '', scenario: '',
        world_info_before: '', world_info_after: '', dialogue_examples: '',
        chat_history: { with_depth_entries: false, prompts: [] },
      },
    });
  }
  
  throw new Error('Không có cách tạo LLM khả dụng');
}

async function callOpenAI(messages, ep, s) {
  const base = String(ep.url || '').replace(/\/+$/, '');
  if (!base) throw new Error('OpenAI chưa cấu hình địa chỉ API');
  // ★ Tương thích Gateway·Chuyển tiếp kết nối trực tiếp qua Backend: Khi bật "Chuyển tiếp kết nối trực tiếp qua Backend", ưu tiên mượn kênh Backend của Tavern
  //   (generateRaw / sendGenerationRequest) để chuyển tiếp, bỏ qua việc trình duyệt chặn CORS/Preflight (một số gateway bắt buộc lỗi fetch trên front-end).
  //   Mô hình lấy theo gateway người dùng điền; nếu kết nối hiện tại của Tavern đã cấu hình là nguồn tương thích này thì ngữ nghĩa tương đương, không nhầm lẫn với mô hình chính.
  if (s.backendProxy) {
    try {
      const bp = await callTavern(messages, s);
      if (bp) return bp;
    } catch (e1) {
      cdWarn('Thử dùng proxy Backend (kênh Tavern) thất bại, quay về kết nối trực tiếp: ' + (e1 && e1.message));
    }
  }
  // ★ Hạ cấp thông minh (Phương án A, v2.6.3): Các gateway như opencode.ai v.v. phía server không trả về header CORS,
  //   Trình duyệt/Tauri WebView kết nối trực tiếp qua fetch ở front-end sẽ ném ra "Failed to fetch" (TypeError: Failed to fetch).
  //   Lúc này tự động hạ cấp xuống kênh của Tavern (generateRaw / generateQuietPrompt) —— Tavern đi qua proxy của server,
  //   không bị giới hạn CORS; hơn nữa kết nối chính của Tavern thường là cùng một gateway, ngữ nghĩa tương đương.
  try {
    const res = await fetch(`${base}/chat/completions`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${ep.key}` },
      body: JSON.stringify({ model: ep.model, messages: messages.map(function (_mm0) {
        var _rp0 = _cdParseMsgContent(_mm0.content);
        if (_rp0.images.length) {
          var _carr0 = [];
          if (_rp0.text) _carr0.push({ type: 'text', text: _rp0.text });
          _rp0.images.forEach(function (_d0) { _carr0.push({ type: 'image_url', image_url: { url: _d0 } }); });
          return { role: _mm0.role, content: _carr0 };
        }
        return { role: _mm0.role, content: _mm0.content };
      }), temperature: s.temperature, max_tokens: 8192, stream: false }),
    });
    if (!res.ok) {
      // 4xx/5xx là lỗi API hoặc key, không hạ cấp (tránh che đậy lỗi thực sự)
      throw new Error(`OpenAI ${res.status}: ${await textOr(res)}`);
    }
    const j = await res.json();
    // Ghi lại token usage vào biến toàn cục để cdApiComplete trả về
    if (j.usage) {
      // Thống kê token chung
      const usage = { prompt: j.usage.prompt_tokens || 0, completion: j.usage.completion_tokens || 0, total: j.usage.total_tokens || 0 };
      // Thống kê bộ nhớ cache DeepSeek (prompt_tokens_details / prompt_cache_*)
      usage.cacheHit = j.usage.prompt_cache_hit_tokens || j.usage.prompt_tokens_details?.cached_tokens || 0;
      usage.cacheMiss = j.usage.prompt_cache_miss_tokens || j.usage.prompt_tokens_details?.uncached_tokens || 0;
      _cdLastTokenUsage = usage;
    }
    // ★ Tương thích mô hình suy luận: Một số mô hình (reasoning/DeepSeek-R1 v.v.) đặt phần thân văn bản vào reasoning_content và để content rỗng, cần dự phòng
    var _msg0 = j.choices && j.choices[0] ? (j.choices[0].message || {}) : {};
    var _txt0 = _msg0.content || _msg0.reasoning_content || _msg0.delta || '';
    if (!_txt0 && j.choices && j.choices[0] && typeof j.choices[0].text !== 'undefined') _txt0 = j.choices[0].text;
    if (!_txt0 && Array.isArray(j.choices)) {
      var _all = j.choices.map(function(c){ var m=c&&c.message||{}; return m.content||m.reasoning_content||''; }).filter(Boolean).join('');
      if (_all) _txt0 = _all;
    }
    return String(_txt0 || '');
  } catch (e) {
    // Chỉ hạ cấp đối với "Lỗi mạng/CORS" (Failed to fetch, TypeError, Level 2 CORS);
    // Đối với các lỗi nghiệp vụ 4xx/5xx rõ ràng thì không hạ cấp
    const msg = String(e && e.message || e);
    const isNetFail = /failed to fetch|networkerror|typeerror|load failed|not allowed to request|cors|connection/i.test(msg);
    if (isNetFail) {
      cdWarn('Kết nối trực tiếp OpenAI thất bại (thường do CORS), hạ cấp xuống kênh Tavern: ' + msg);
      if (typeof cdAddLog === 'function') cdAddLog('warn', '[API] Kết nối trực tiếp OpenAI thất bại, tự động hạ cấp xuống kênh Tavern', { err: msg });
      // Thông báo rõ ràng cho ML: Thử đi qua kết nối Tavern (generateRaw / generateQuietPrompt)
      try {
        const text = await callTavern(messages, s);
        if (text) return text;
      } catch (e2) {
        cdWarn('Hạ cấp xuống kênh Tavern cũng thất bại: ' + (e2 && e2.message));
      }
    }
    throw e; // Các lỗi khác ném ra nguyên vẹn
  }
}

/**
 * Sắp xếp lại Rerank (Tương thích OpenAI /rerank, đường lùi /v1/rerank)
 * @param {string} query Văn bản truy vấn
 * @param {Array} documents Mảng văn bản cần sắp xếp lại
 * @param {object} cfg { base, key, model }
 * @returns {Promise<{index:number, score:number}[]>} Kết quả sắp xếp theo điểm giảm dần
 */
async function cdRerank(query, documents, cfg) {
  if (!query || !Array.isArray(documents) || !documents.length) return [];
  const rawBase = String(cfg.base || '').replace(/\/+$/, '');
  const key = cfg.key || '';
  const model = cfg.model || '';
  if (!rawBase || !model) throw new Error('Rerank chưa cấu hình base/model');
  const mappedDocs = documents.map(d => typeof d === 'string' ? d : (d.text || d.content || JSON.stringify(d)));
  const body = { model, query, documents: mappedDocs };
  const headers = { 'Content-Type': 'application/json' };
  if (key) headers.Authorization = `Bearer ${key}`;
  // base có thể có /v1 hoặc không, tạo tổ hợp endpoint ứng viên: base/v1 có mang theo hậu tố /rerank /v1/rerank không
  const bases = [rawBase];
  // Nếu base kết thúc bằng /v1, thử loại bỏ /v1; nếu không có, thử thêm /v1
  const hasV1 = /\/v1$/.test(rawBase);
  const altBase = hasV1 ? rawBase.replace(/\/v1$/, '') : rawBase + '/v1';
  if (altBase !== rawBase) bases.push(altBase);
  const suffixes = ['/rerank', '/v1/rerank'];
  let lastErr = null;
  for (const b of bases) {
    for (const suffix of suffixes) {
      if (!cfg.__noDupCheck && /rerank$/.test(b) && suffix.startsWith('/')) continue; // Chống b đã chứa rerank
      try {
        const res = await fetch(`${b}${suffix}`, { method: 'POST', headers, body: JSON.stringify(body) });
        if (!res.ok) { lastErr = new Error(`${b}${suffix} ${res.status}: ${await textOr(res)}`); continue; }
        const j = await res.json();
        const results = Array.isArray(j.results) ? j.results
          : (Array.isArray(j.data) ? j.data : null);
        if (!results) { lastErr = new Error(`${b}${suffix} Trả về định dạng không chứa results`); continue; }
        return results
          .filter(r => r && typeof r.index === 'number')
          .map(r => ({ index: r.index, score: r.relevance_score ?? r.score ?? 0 }))
          .sort((a, b) => b.score - a.score);
      } catch (e) {
        lastErr = e;
      }
    }
  }
  throw lastErr || new Error('Gọi Rerank thất bại');
}

/**
 * Thực hiện rerank sắp xếp lại đối với kết quả vector đã triệu hồi (thất bại tự động hạ cấp trả về kết quả gốc)
 * @param {string} query Văn bản truy vấn
 * @param {Array} results Kết quả triệu hồi [{ text, ... }]
 * @param {object} s Cài đặt (đọc rerankEnabled/rerankTarget/rerankApi)
 * @param {string} target Luồng hiện tại 'story' | 'diary'
 * @returns {Promise<Array>} Kết quả sau khi sắp xếp lại (cùng cấu trúc với tham số đầu vào)
 */
async function cdRerankResults(query, results, s, target) {
  try {
    if (!s?.rerankEnabled) return results;
    if (!results || !results.length) return results;
    // target khớp: 'both' ăn tất, hoặc bằng với target hiện tại
    const want = s.rerankTarget || 'both';
    if (want !== 'both' && want !== target) return results;
    const docs = results.map(r => (r && r.text) || '').filter(Boolean);
    if (!docs.length) return results;
    const cfg = s.rerankApi || {};
    const idxArr = await cdRerank(query, docs, cfg);
    // Sắp xếp lại theo thứ tự rerank
    const ranked = idxArr.map(ri => results[ri.index]).filter(Boolean);
    if (ranked.length) return ranked;
  } catch (e) {
    cdAddLog('warn', '[rerank] Sắp xếp lại thất bại, hạ cấp sử dụng kết quả gốc: ' + e.message);
  }
  return results;
}

/* Phân tích tin nhắn đa phương thức: Tách thẻ [IMG]data:image/...[/IMG] trong content của tin nhắn thành mảng văn bản + hình ảnh */
function _cdParseMsgContent(content){
  var text=String(content||'');
  var images=[];
  var re=/\[IMG\](data:image\/[^\[\]]+)\[\/IMG\]/gi;
  var m;
  while((m=re.exec(text))){ images.push(m[1]); }
  text=text.replace(/\[IMG\](data:image\/[^\[\]]+)\[\/IMG\]/gi,'');
  text=text.replace(/\n{3,}/g,'\n\n').trim();
  return { text:text, images:images };
}

async function callClaude(messages, ep, s) {
  const base = ep.url.replace(/\/+$/, '');
  const system = messages.filter(m => m.role === 'system').map(m => m.content).join('\n\n');
  const msgs = messages.filter(m => m.role !== 'system').map(m => {
    var _rp = _cdParseMsgContent(m.content);
    if (_rp.images.length) {
      var _carr = [];
      if (_rp.text) _carr.push({ type: 'text', text: _rp.text });
      _rp.images.forEach(function (d) {
        var _mm = /^data:(image\/(?:png|jpeg|gif|webp));base64,(.*)$/.exec(d);
        if (_mm) _carr.push({ type: 'image', source: { type: 'base64', media_type: _mm[1], data: _mm[2] } });
      });
      return { role: m.role === 'assistant' ? 'assistant' : 'user', content: _carr };
    }
    return { role: m.role === 'assistant' ? 'assistant' : 'user', content: m.content };
  });
  const res = await fetch(`${base}/messages`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'x-api-key': ep.key, 'anthropic-version': '2023-06-01' },
    body: JSON.stringify({ model: ep.model, system, messages: msgs, max_tokens: 8192, temperature: s.temperature }),
  });
  if (!res.ok) throw new Error(`Claude ${res.status}: ${await textOr(res)}`);
  const j = await res.json();
  if (j.usage) {
    _cdLastTokenUsage = { prompt: j.usage.input_tokens, completion: j.usage.output_tokens, total: j.usage.input_tokens + j.usage.output_tokens };
  }
  return (j.content || []).map(p => p.text || '').join('');
}

async function callGemini(messages, ep, s) {
  const base = ep.url.replace(/\/+$/, '');
  const system = messages.filter(m => m.role === 'system').map(m => m.content).join('\n\n');
  const contents = messages.filter(m => m.role !== 'system').map(m => {
    var _rp = _cdParseMsgContent(m.content);
    var _parts = [];
    if (_rp.text) _parts.push({ text: _rp.text });
    _rp.images.forEach(function (d) {
      var _mm = /^data:(image\/[a-zA-Z0-9.+-]+);base64,(.*)$/.exec(d);
      if (_mm) _parts.push({ inline_data: { mime_type: _mm[1], data: _mm[2] } });
    });
    return { role: m.role === 'assistant' ? 'model' : 'user', parts: _parts };
  });
  const body = {
    contents,
    generationConfig: { temperature: s.temperature, maxOutputTokens: 8192 },
    safetySettings: [
      { category: 'HARM_CATEGORY_HARASSMENT',        threshold: 'BLOCK_NONE' },
      { category: 'HARM_CATEGORY_HATE_SPEECH',       threshold: 'BLOCK_NONE' },
      { category: 'HARM_CATEGORY_SEXUALLY_EXPLICIT', threshold: 'BLOCK_NONE' },
      { category: 'HARM_CATEGORY_DANGEROUS_CONTENT',  threshold: 'BLOCK_NONE' },
    ],
  };
  if (system) body.systemInstruction = { parts: [{ text: system }] };
  const url = `${base}/models/${encodeURIComponent(ep.model)}:generateContent?key=${encodeURIComponent(ep.key)}`;
  const res = await fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
  if (!res.ok) throw new Error(`Gemini ${res.status}: ${await textOr(res)}`);
  const j = await res.json();
  var _gparts = (j.candidates && j.candidates[0] && j.candidates[0].content && j.candidates[0].content.parts) || [];
  var _gTxt = _gparts.map(p => p.text || '').join('');
  if (!_gTxt && j.candidates && j.candidates[0]) {
    // Mô hình suy luận có thể đặt nội dung vào thoughts/reasoning, hoặc trong parts thiếu text
    var _gC = j.candidates[0];
    if (_gC.thoughts && Array.isArray(_gC.thoughts)) _gTxt = _gC.thoughts.map(function(t){ return t&&t.content||''; }).filter(Boolean).join('');
    if (!_gTxt && _gC.content && Array.isArray(_gC.content.parts)) {
      _gTxt = _gC.content.parts.map(function(p){ if(!p) return ''; return p.text||p.inline_data||''; }).filter(function(x){return typeof x==='string' && x;}).join('');
    }
  }
  return String(_gTxt || '');
}

/** Lấy danh sách mô hình (Sử dụng khi không phải là giao diện Tavern) */
async function cdFetchModels(source, ep) {
  // ★ Tương thích nhiều tổ hợp endpoint có/không có /v1 trong URL (một số gateway /models chỉ phơi bày dưới /v1)
  const rawBase = String(ep.url || '').replace(/\/+$/, '');
  const bases = [rawBase];
  try {
    const hasV1 = /\/v1$/.test(rawBase);
    const altBase = hasV1 ? rawBase.replace(/\/v1$/, '') : rawBase + '/v1';
    if (altBase && altBase !== rawBase) bases.push(altBase);
  } catch (e) {}
  const tryFetch = async (url, o) => {
    const r = await fetch(url, o);
    return await r.json();
  };
  const lastErr = [];
  for (const base of bases) {
    if (!base) continue;
    try {
      if (source === 'openai') {
        const j = await tryFetch(`${base}/models`, { headers: { Authorization: `Bearer ${ep.key}` } });
        const arr = (j.data || []).map(m => m && m.id).filter(Boolean);
        if (arr.length) return arr;
        lastErr.push(`${base}/models: Trả về data rỗng`);
      }
      if (source === 'claude') {
        const j = await tryFetch(`${base}/models`, { headers: { 'x-api-key': ep.key, 'anthropic-version': '2023-06-01' } });
        const arr = (j.data || []).map(m => m && m.id).filter(Boolean);
        if (arr.length) return arr;
        lastErr.push(`${base}/models: Trả về data rỗng`);
      }
      if (source === 'gemini') {
        const j = await tryFetch(`${base}/models?key=${encodeURIComponent(ep.key)}`);
        const arr = (j.models || []).map(m => (m.name || '').replace(/^models\//, '')).filter(Boolean);
        if (arr.length) return arr;
        lastErr.push(`${base}/models: Trả về models rỗng`);
      }
    } catch (e) {
      lastErr.push(`Yêu cầu ${base} thất bại: ${e.message}`);
    }
  }
  // ★ Khi kết nối trực tiếp để lấy thất bại (thường do CORS của front-end chặn), lấy mô hình khả dụng dựa trên danh sách dự phòng tích hợp sẵn khớp với tên miền gateway
  //   Chỉ điền lại các mô hình "đã thử nghiệm thực tế khả dụng dưới gateway đó", tuyệt đối không nhét available_models của mô hình chính Tavern (thường là gpt v.v. không liên quan) vào.
  try {
    const host = (rawBase.toLowerCase());
    let kbModels = [];
    for (const key of Object.keys(CD_GATEWAY_MODELS)) {
      if (host.includes(key)) { kbModels = CD_GATEWAY_MODELS[key].filter(Boolean); break; }
    }
    if (kbModels && kbModels.length) {
      cdWarn('Kết nối trực tiếp lấy mô hình thất bại (thường do CORS), đã khớp với [Danh sách gateway dự phòng tích hợp sẵn] trả về mô hình khả dụng');
      if (typeof cdAddLog === 'function') cdAddLog('warn', '[API] Kết nối trực tiếp lấy mô hình thất bại, sử dụng danh sách gateway dự phòng tích hợp sẵn', { source: source, host: host, count: kbModels.length });
      return kbModels;
    }
  } catch (e) {}
  // ★ Chỉ khi người dùng sử dụng nguồn "Tavern hiện tại (tavern)", mới đọc danh sách mô hình từ cài đặt OpenAI đã tải của Tavern để dự phòng;
  //   Khi đã điền gateway riêng (openai/claude/gemini) thì không đọc danh sách mô hình chính của Tavern nữa, tránh việc trả về các mô hình không liên quan làm kết quả.
  if (source === 'tavern') {
    try {
      const oai = (typeof oai_settings !== 'undefined') ? oai_settings : (SillyTavern && SillyTavern.getContext() && SillyTavern.getContext().extensionSettings ? null : null);
      let fromTavern = [];
      if (oai) {
        const cand = [oai.available_models, oai.models, oai.custom_models, (oai.available_models && oai.available_models[oai.chat_completion_source])];
        for (const c of cand) {
          if (Array.isArray(c) && c.length) {
            fromTavern = c.map(m => (typeof m === 'string' ? m : (m && (m.id || m.name)))).filter(Boolean);
            if (fromTavern.length) break;
          }
        }
      }
      if (fromTavern.length) {
        cdWarn('Kết nối trực tiếp lấy mô hình thất bại (thường do CORS), đã đọc danh sách mô hình từ cài đặt Tavern đã tải');
        if (typeof cdAddLog === 'function') cdAddLog('warn', '[API] Kết nối trực tiếp lấy mô hình thất bại, hạ cấp đọc danh sách mô hình Tavern', { count: fromTavern.length });
        return fromTavern;
      }
    } catch (e) {}
  }
  toastr.warning('[Nhật ký nhân vật] Lấy danh sách mô hình thất bại (Nếu gateway API của bạn không hỗ trợ CORS chéo miền, vui lòng đổi sang nguồn "Tavern hiện tại" ở trên, hoặc điền tên mô hình thủ công): ' + (lastErr.join(' | ') || 'Lỗi không xác định'));
  return [];
}

function textOr(res) { return res.text().then(t => t.slice(0, 200)); }// ============================================================
// Nhật ký nhân vật Plugin v2.0.0 — Prompt & Phân tích JSON
// Đường dẫn: SillyTavern/extensions/character-diary/prompts.js
// ============================================================
'use strict';

/* ============================== Prompt: Nhật ký ============================== */
async function cdBuildDiaryPrompt(windowFloors, data, s) {
  const known = Object.keys(data.diaries).map(name => {
    const al = (data.aliases[name] || []);
    return al.length ? `${name}(Bí danh: ${al.join(', ')})` : name;
  });
  // ★ Nhúng nhiều lịch sử gần đây cho mỗi nhân vật (Mặc định vectorTopK mục), tránh việc chỉ nhúng mục mới nhất cho mỗi nhân vật
  const memLimit = Math.max(1, parseInt(s.vectorTopK, 10) || 5);
  const memory = (s.summarizeInjectDiary ? Object.entries(data.diaries).map(([name, list]) => {
    if (!Array.isArray(list) || !list.length) return '';
    return list.slice(-memLimit).map(function (e) {
      return `[${name}] ${e.date ? 'Ngày thứ ' + e.date : 'Tầng ' + e.turn}: ${(e.entry || '').trim()}`;
    }).join('\n');
  }).filter(Boolean).join('\n') : '');
  // ★ Văn bản tầng đã qua lọc thẻ
  const tags = s.filterTags || [];
  const scene = windowFloors.map(m => `[#${m.message_id} ${m.name}] ${cdFilterTags(m.mes, tags)}`).join('\n\n');

  // ★ Bắt theo nhân vật xuất hiện (Phương án B): Dùng Regex để bắt nhân vật xuất hiện từ cốt truyện, chỉ đẩy nhật ký gần đây của các nhân vật này (Thay thế cho nhúng toàn bộ)
  let diaryMemory = memory;
  if (s.diaryCharFilter) {
    try {
      const capt = cdCaptureCast(scene, data);
      if (capt && capt.length) {
        const limit = Math.max(1, parseInt(s.diaryCharLimit,10)||3);
        const lines = [];
        capt.forEach(function(role){
          const list = (data.diaries && Array.isArray(data.diaries[role])) ? data.diaries[role] : [];
          if (!list.length) return;
          list.slice(-limit).forEach(function(e){
            lines.push(`[${role}] ${e.date ? 'Ngày thứ '+e.date : 'Tầng '+(e.turn!=null?e.turn:'?')}: ${(e.entry||'').trim()}`);
          });
        });
        if (lines.length) diaryMemory = 'Nhật ký gần đây của nhân vật xuất hiện (Trích xuất theo nhân vật xuất hiện):\n' + lines.join('\n');
        else diaryMemory = memory;
      }
    } catch (e) { if (typeof cdWarn==='function') cdWarn('Bắt theo nhân vật xuất hiện thất bại', e); diaryMemory = memory; }
  }
  // ★ Chế độ vector hóa: Truy hồi nhật ký lịch sử liên quan (Ghi đè thả xuống ký ức toàn bộ)
  if (s.diaryMode === 'vector') {
    try {
      if (Array.isArray(data.diaryVectors) && data.diaryVectors.length > 0) {
        const topK = s.vectorTopK || 5;
        const threshold = s.vectorThreshold || 0.6;
        let results = await cdSearchVectors(scene, data.diaryVectors, topK, threshold);
        // ★ Rerank sắp xếp lại (Luồng nhật ký nhân vật)
        results = await cdRerankResults(scene, results, s, 'diary');
        if (results.length) {
          diaryMemory = 'Nhật ký lịch sử liên quan (Truy hồi Vector):\n' + results.map(r => '  - ' + (r.text || '').trim()).join('\n');
        }
      }
    } catch (e) { cdWarn('Truy hồi vector nhật ký thất bại (Hạ cấp thành ký ức toàn bộ):', e); }
  }
  const _dv = (s && s.diaryVersion === 'lite') ? 'lite' : 'full';
  const sys = [
    'Bạn là một người ghi chép "Nhật ký nhân vật". Khi đọc cốt truyện, hãy để mỗi nhân vật có tên và có đất diễn, dùng ngôi thứ nhất viết ra những gì họ thực sự đang nghĩ trong lòng lúc này.',
    (typeof data === 'object' && data !== null && typeof data.lastFloor === 'number' && data.lastFloor === -1)
      ? '- ★★★ Lần này là ghi chép [Đầu tiên] của đoạn cốt truyện này. Phần mở đầu [Lời dạo đầu của tầng 0] bao gồm thiết lập bối cảnh, thời gian địa điểm, nhân vật xuất hiện và trạng thái quan hệ hiện tại của họ với nhau, nên nắm bắt những thiết lập này từ đó, nhưng đừng lặp lại lời dạo đầu, chỉ cần hòa quyện lớp bối cảnh này vào tâm trạng của nhân vật lúc này.'
      : '',
    '[Viết cho ai] Chỉ viết cho các nhân vật có tên và có đất diễn. Người qua đường thuần túy thì bỏ qua; không viết thay người chơi/nhân vật chính.',
    s.mainCardIsGM ? '- Người kể chuyện/Hệ thống/Góc nhìn thượng đế/Người kể chuyện kiểu GM, đừng viết cho họ.' : '',
    '[Đây là lời trong lòng viết cho chính mình xem, không phải báo cáo cốt truyện]',
    '- Hãy viết theo cảm xúc và tính khí của nhân vật này ngay lúc này, đừng giống như học thuộc lòng kể lại hôm nay đã xảy ra chuyện gì. Chỉ viết những chuyện mà người đó tận mắt nhìn thấy, tận tai nghe thấy, đích thân trải nghiệm, và trong lòng thực sự nghĩ như vậy.',
    '- Lệnh cấm toàn tri: Tuyệt đối không được giống như thượng đế nói ra trong lòng nhân vật khác đang nghĩ gì, không được viết những tình tiết mà nhân vật này không biết, không trải qua.',
    '[Trọng tâm] Hãy viết ra sự việc thực sự chạm đến trái tim người đó trong đoạn cốt truyện này - người đó có thể vì chuyện này mà thay đổi cách nhìn về ai đó, ghim trong lòng, rung động, sợ hãi sau đó, biết ơn, tức cười, hoặc tự mỉa mai bản thân một trận thậm tệ; cũng có thể chỉ là một cảm giác thót tim, bản thân cũng không diễn tả rõ được hương vị đó. Hãy đi theo phản ứng mà nhân vật đó nên có: Vui thì vui, chua xót thì chua xót, cam chịu thì cam chịu, bực tức thì bực tức. Trọng tâm là sự việc này mang theo cảm xúc rơi vào trong lòng người đó, khiến người đó có một cái nhìn hoặc thái độ mới đối với ai đó hoặc bản thân.',
    '[Giọng điệu] Giống như lải nhải một mình đêm khuya: Có thể có ẩn ý, nói một nửa rồi nuốt vào, đột nhiên tự trào một chút, hoặc cứng miệng vài câu; Sẽ lặp đi lặp lại, sẽ mâu thuẫn - con người vốn dĩ là như vậy. Đừng dùng giọng điệu văn vẻ, đừng nói giọng quan liêu, đừng câu nào cũng giải thích tại sao.',
    '[Ký ức] Nhớ đến chuyện cũ thì nhắc một câu để hô ứng, không nhớ ra thì không nhắc, không gượng ép.',
    '[Ngôn ngữ] Đi theo ngôn ngữ chính của đoạn cốt truyện.',
    '[Tình tiết nhạy cảm] Tình dục/bạo lực v.v. chỉ cần lướt qua bằng một câu (như "đã phát sinh quan hệ với anh ấy", "bị anh ta áp chế"), nghiêm cấm miêu tả chi tiết hành động, cơ quan, chất dịch v.v. Nhật ký ghi lại cảm nhận và phán đoán, không phải khôi phục quá trình.',
    (_dv === 'lite'
      ? '[Đợt này là bản tinh giản] Phần thân văn bản dưới 100 chữ, chỉ viết ba điều cốt lõi: ① Lúc này trong lòng nghĩ gì (Thỏa mãn/Uất ức/Đã buông bỏ chưa) ② Chuyện quan trọng nhất hôm nay (Lướt qua bằng một câu, mang theo thái độ của người đó - Phàn nàn/Biết ơn/Thù dai/Rung động đều được) ③ Một điểm ký ức trong chuyện này mà người đó muốn giữ lại. Câu nào ra câu nấy, không nhồi nhét từ ngữ, không dài dòng.'
      : '[Đợt này là bản đầy đủ] Phần thân văn bản 300~520 chữ. Trải dài theo cảm xúc: Có thể có hoạt động tâm lý, có giọng điệu, viết sự việc chạm đến người đó sao cho có sức nặng. Thà thiếu còn hơn ẩu, đừng trống rỗng câu chữ cho đủ số.'),
    '[Cấu trúc] Chỉ xuất ra JSON, các trường như cũ, không được cắt giảm:',
    '{"npcs":[{"name":"Tên chính","aliases":["Bí danh"],"is_minor":false,"date":"Thời gian cốt truyện hoặc Tầng N","turn":Số tầng,"entry":"Phần thân văn bản lời trong lòng ngôi thứ nhất", "mood":"Tâm trạng (Chỉ dùng một trong các từ sau: Vui vẻ, Buồn bã, Tức giận, Căng thẳng, Bình tĩnh, Bối rối, Ngạc nhiên, Nhớ nhung)","attitude_to_user":"Thái độ với người dùng","secret":"Tiếng lòng chưa nói ra (Có thể trùng lặp với entry nhưng riêng tư hơn và ngắn hơn)","key_events":["Sự kiện chính"],"relationship_with_others":{"Nhân vật nào đó":"Mô tả quan hệ"}}]}',
    'Giải thích các trường:',
    '- entry: Chính là phần thân văn bản lời trong lòng của nhân vật này lúc này (Viết theo số chữ bản tinh giản/đầy đủ ở trên).',
    '- mood: Tâm trạng hiện tại; attitude_to_user: Thái độ với người dùng; secret: Tiếng lòng chưa nói ra.',
    '- key_events: Sự kiện mà người đó đích thân trải qua và có sức nặng đối với cá nhân người đó.',
    '- relationship_with_others: Ấn tượng của người đó về mối quan hệ của mình với người khác (Chủ quan, viết theo trải nghiệm của người đó, không phải kết luận từ góc nhìn thượng đế).',
    '- Tái sử dụng tên chính trong danh sách nhân vật đã biết; nếu nhận diện được bí danh thì gộp vào tên chính và bổ sung vào aliases.',
    '- Dùng is_minor để đánh dấu tầm quan trọng của nhân vật: Nhân vật chính/Vai phụ quan trọng/NPC có tên có đất diễn đánh dấu false; Người qua đường thuần túy chỉ xuất hiện một hai câu trong đoạn cốt truyện đánh dấu true.',
  ].filter(Boolean).join('\n');
  // ★ Liên kết Worldbook: Ở đầu thân hàm, gọi API bất đồng bộ để lấy thiết lập Worldbook của nhân vật xuất hiện (loadWorldInfo là API bất đồng bộ)
  let _worldbookTxtDiary = '';
  if (s && s.summarizeInjectDiary && s.worldbookLink !== false) {
    try {
      const _wr = cdSceneWorldbookRoles(windowFloors, data);
      if (_wr.length) _worldbookTxtDiary = await cdGetWorldbookForRoles(_wr);
    } catch (e) { if (typeof cdWarn === 'function') cdWarn('Liên kết Worldbook (Nhật ký) đọc thất bại:', e); }
  }
  const usr = [
    known.length ? `Danh sách nhân vật đã biết: ${known.join('; ')}` : 'Danh sách nhân vật đã biết: (Chưa có)',
    diaryMemory ? `Ký ức đã có của các nhân vật (Lịch sử gần đây):\n${diaryMemory}` : 'Ký ức đã có của các nhân vật: (Chưa có)',
    `Đoạn cốt truyện lần này:\n${scene}`,
    // ★ Nhân vật trọng điểm: Nhân vật do người dùng chỉ định thủ công bắt buộc phải được viết chi tiết, tránh bị bỏ sót/thoát ly thiết lập
    (Array.isArray(data.focusRoles) && data.focusRoles.length)
      ? `[Nhân vật trọng điểm (Bắt buộc phải viết nhật ký chi tiết cho họ)]\n${data.focusRoles.map(f => '  - ' + (f.name || '') + (f.note ? `: ${f.note}` : '')).join('\n')}\nYêu cầu: Ngay cả khi những nhân vật này xuất hiện ít trong đoạn cốt truyện này, cũng phải dựa vào ký ức và thiết lập đã có, bổ sung nhật ký hoàn chỉnh, phù hợp với thiết lập nhân vật cho họ.`
      : '',
    // ★ Liên kết Worldbook: Nhúng thiết lập Worldbook của nhân vật xuất hiện lần này (Để viết bám sát thiết lập nhân vật hơn)
    _worldbookTxtDiary ? '[Tham khảo thiết lập Worldbook (Nhân vật xuất hiện lần này)]\n' + _worldbookTxtDiary : '',
    'Vui lòng xuất ra JSON.',
  ].filter(Boolean).join('\n\n');
  return [
    { role: 'system', content: JAILBREAK + '\n\n' + sys },
    { role: 'user', content: usr },
    { role: 'assistant', content: '{"npcs":[' },
  ];
}

/** ★ Prompt kết hợp: Một lần gọi hoàn thành Nhật ký + Quan hệ + Hồ sơ cốt truyện */
function cdBuildCombinedPrompt(windowFloors, data, s) {
  const known = Object.keys(data.diaries).map(name => {
    const al = (data.aliases[name] || []);
    return al.length ? `${name}(Bí danh: ${al.join(', ')})` : name;
  });
  // ★ Nhúng nhiều lịch sử gần đây cho mỗi nhân vật (Mặc định vectorTopK mục), tránh việc chỉ nhúng mục mới nhất cho mỗi nhân vật
  const memLimit = Math.max(1, parseInt(s.vectorTopK, 10) || 5);
  const memory = Object.entries(data.diaries).map(([name, list]) => {
    if (!Array.isArray(list) || !list.length) return '';
    return list.slice(-memLimit).map(function (e) {
      return `[${name}] ${e.date ? 'Ngày thứ ' + e.date : 'Tầng ' + e.turn}: ${(e.entry || '').trim()}`;
    }).join('\n');
  }).filter(Boolean).join('\n');
  const scene = windowFloors.map(m => `[#${m.message_id} ${m.name}] ${m.mes}`).join('\n\n');
  const existing = data.archive || emptyData().archive;
  
  const sys = [
    'Bạn là trợ lý AI ba trong một "Người ghi chép nhật ký nhân vật" + "Người phân tích quan hệ nhân vật" + "Người chỉnh lý hồ sơ cốt truyện".',
    'Đọc đoạn cốt truyện được cung cấp, đồng thời hoàn thành ba nhiệm vụ sau.',
    '',
    '=== Nhiệm vụ 1: Nhật ký nhân vật ===',
    'Đối với mỗi nhân vật có tên và có đất diễn xuất hiện, dùng góc nhìn chủ quan ngôi thứ nhất của nhân vật đó viết một bài **nhật ký nội tâm riêng tư mang đậm cảm giác của người sống**.',
    'Yêu cầu:',
    '- Chỉ viết cho các nhân vật có tên, có đất diễn thực tế. Người qua đường thuần túy, quần chúng vô danh thì bỏ qua.',
    '- Không viết nhật ký cho nhân vật của người dùng/người chơi.',
    s.mainCardIsGM ? '- Nếu một nhân vật là người dẫn truyện/hệ thống/góc nhìn thượng đế/người kể chuyện kiểu GM, không viết cho họ.' : '',
    '- Ngôi thứ nhất, mang theo cảm xúc, sự ích kỷ, hiểu biết chủ quan của nhân vật đó (có thể sai lệch so với sự thật).',
    '- ★★★ entry là "Nhật ký riêng tư viết cho chính mình xem", không phải kể lại cốt truyện, không phải báo cáo. Phải giống như tình hình nội tâm thực tế mà người thật tiện tay viết xuống lúc đêm khuya, chứ không phải một bản tóm tắt đều đều.',
    '- ★★★ Nội tâm bộc trực + Tương phản trẻ con (Hương vị người sống): Cho phép nhân vật chuyển đổi tự nhiên giữa "Bình tĩnh tính toán/Lão luyện" và "Dỗi hờn/Trẻ con/Giận dỗi"; Không dùng giọng điệu văn học để tô vẽ, không giải thích "Tại sao" ở mỗi câu.',
    '- ★★★ Cung cấp "Kho tài liệu nội tâm", tầng nào có đất diễn thì viết tầng đó, không cần gượng ép: ① Sự kiện bề ngoài (Bộ khung) ② Tôi quan tâm điều gì (Động cơ ngầm) ③ Cuốn sổ nợ đối với người đó (Nợ cũ/Sự hụt hẫng) ④ Kế hoạch không nói cho ai biết (Tâm cơ mưu tính) ⑤ Bản thân cũng không thừa nhận (Tự dối lòng, dùng "Tôi mới không/Bỏ đi/Thực ra" để dẫn dắt).',
    '- ★★★ Vòng lặp ký ức: Nếu ký ức đã có nhắc đến ai đó/chuyện gì/cảm xúc lần trước, cố gắng hô ứng trong lần này, tạo thành một vở kịch nội tâm liên tục qua nhiều bài viết.',
    '- ★★★ Cho phép khoảng trắng và câu nói dở ("..."/Viết được một nửa thì dừng), còn có cảm giác nội tâm hơn là viết đầy.',
    '- Khi liên quan đến các tình tiết nhạy cảm chỉ cần tóm tắt ngắn gọn, nghiêm cấm miêu tả từng chữ.',
    '- Tái sử dụng tên chính trong "Danh sách nhân vật đã biết"; nếu nhận diện được bí danh/đại từ, hãy gộp vào tên chính đã có, và bổ sung bí danh vào aliases.',
    '- Ngôn ngữ: Đi theo ngôn ngữ chính của đoạn cốt truyện.',
    '- Dùng is_minor để đánh dấu tầm quan trọng của nhân vật.',
    '',
    '=== Nhiệm vụ 2: Quan hệ nhân vật ===',
    'Trích xuất "Quan hệ chủ quan đơn hướng" giữa các nhân vật.',
    'Yêu cầu:',
    '- Chủ quan đơn hướng: Quan hệ từ from nhìn to. A nhìn B và B nhìn A có thể khác nhau, vui lòng ghi riêng từng cái.',
    '- Chỉ phân tích quan hệ giữa các nhân vật có tên và có đất diễn, bỏ qua người qua đường thuần túy.',
    '- Không bao gồm nhân vật của người dùng/người chơi.',
    '- type: Dùng từ ngắn gọn khái quát tính chất quan hệ (như "Bạn thân", "Yêu thầm", "Thù địch", "Chủ tớ", "Cảnh giác", "Dựa dẫm").',
    '- attitude: Chỉ có thể là một trong "positive" (Thân thiện), "negative" (Bài xích), "neutral" (Trung lập).',
    '- note: Giải thích bằng một câu (Dưới 20 chữ).',
    known.length ? `Nhân vật đã biết: ${known.join(', ')}` : '',
    '',
    '=== Nhiệm vụ 3: Hồ sơ cốt truyện ===',
    'Chỉnh lý cốt truyện thành hồ sơ cốt truyện có thể viết tiếp lâu dài.',
    'Yêu cầu:',
    '- Mỗi mô tả sự kiện bắt buộc phải bắt đầu bằng [Đánh dấu thời gian], như [Ngày thứ 3 Chạng vạng], [Tầng 15].',
    '- Chỉ viết những sự thật đã xảy ra, không viết suy đoán, đánh giá, tạo không khí hay phân tích tâm lý.',
    '- Các đoạn tán gẫu không có tác dụng thúc đẩy cốt truyện có thể được nén lại.',
    '- Khi trong sự kiện xuất hiện vật phẩm, bằng chứng, số tiền, thuốc men, thương tích, thay đổi quan hệ v.v. phải viết rõ nội dung cụ thể.',
    '',
    existing.mainline ? `Tuyến chính đã có: ${existing.mainline}` : '',
    existing.sideline ? `Tuyến phụ đã có: ${existing.sideline}` : '',
    existing.states ? `Thay đổi trạng thái quan trọng đã có: ${existing.states}` : '',
    existing.unresolved ? `Các vấn đề chưa giải quyết đã có: ${existing.unresolved}` : '',
    '',
    'Định dạng đầu ra: Nghiêm ngặt xuất ra ba đoạn nội dung theo thứ tự dưới đây, dùng "===SEPARATOR===" để phân cách.',
    '',
    'Phần 1: JSON Nhật ký',
    '{"npcs":[{"name":"Tên chính","aliases":["Bí danh"],"is_minor":false,"date":"Thời gian cốt truyện hoặc Tầng N","turn":Số tầng,"entry":"Phần thân văn bản ngôi thứ nhất","mood":"Tâm trạng (Chỉ dùng một trong các từ sau: Vui vẻ, Buồn bã, Tức giận, Căng thẳng, Bình tĩnh, Bối rối, Ngạc nhiên, Nhớ nhung)","attitude_to_user":"Thái độ với người dùng","secret":"Tiếng lòng chưa nói ra","key_events":["Sự kiện chính"],"relationship_with_others":{"Nhân vật nào đó":"Mô tả quan hệ"}}]}',
    '',
    '===SEPARATOR===',
    '',
    'Phần 2: JSON Quan hệ',
    '{"relations":[{"from":"A","to":"B","type":"Tính chất quan hệ","attitude":"positive","note":"Mô tả ngắn gọn"}]}',
    'Nếu không có bất kỳ quan hệ nào, xuất ra {"relations":[]}',
    '',
    '===SEPARATOR===',
    '',
    'Phần 3: Hồ sơ cốt truyện',
    'Tuyến chính:',
    'Tuyến phụ:',
    'Thay đổi trạng thái quan trọng:',
    'Các vấn đề chưa giải quyết:',
    'Nếu không có thay đổi, trường tương ứng xuất ra "Không có".',
    '',
    '===SEPARATOR===',
  ].filter(Boolean).join('\n');
  
  const usr = [
    known.length ? `Danh sách nhân vật đã biết: ${known.join('; ')}` : 'Danh sách nhân vật đã biết: (Chưa có)',
    memory ? `Ký ức đã có của các nhân vật (Lịch sử gần đây):\n${memory}` : 'Ký ức đã có của các nhân vật: (Chưa có)',
    `Đoạn cốt truyện lần này:\n${scene}`,
  ].join('\n\n');
  
  return [
    { role: 'system', content: JAILBREAK + '\n\n' + sys },
    { role: 'user', content: usr },
    { role: 'assistant', content: '{"npcs":[' },
  ];
}

/* ============================== Prompt: Hồ sơ cốt truyện (Kèm đánh dấu thời gian) ============================== */
