async function cdBuildArchivePrompt(windowFloors, data, _s, archiveFull) {
  // ★ archiveFull=true biểu thị chế độ tái tạo toàn bộ (viết bù thủ công một khoảng lớn), dùng prompt tóm tắt hoàn chỉnh, nếu không thì dùng prompt tăng dần
  const _archSys = archiveFull ? ARCHIVE_SYSTEM_FULL : ARCHIVE_SYSTEM;
  const existing = data.archive || emptyData().archive;
  // ★ Mục theo dõi cốt truyện tùy chỉnh của người dùng
  const customFields = Array.isArray(_s?.customFields) ? _s.customFields.filter(f => f && f.key && f.label) : [];
  const customFormatBlock = customFields.length
    ? customFields.map(f =>
        `${f.label}：\n（${f.desc || 'Ghi lại thay đổi của mục theo dõi này'}。Mỗi sự kiện bắt đầu bằng [Đánh dấu thời gian]; không có thay đổi thì xuất ra "Không có"）`
      ).join('\n')
    : '';
  const customOutputNames = customFields.map(f => f.label).join('、');
  // Dữ liệu tùy chỉnh đã có (dùng cho mở rộng tăng dần ở chế độ thông thường)
  const existingCustomTxt = customFields.map(f => {
    const arr = (existing.custom && Array.isArray(existing.custom[f.key])) ? existing.custom[f.key] : [];
    if (!arr.length) return '';
    return `${f.label} đã biết：\n` + arr.map(it => it.time ? `【${it.time}】${it.desc}` : it.desc).join('\n');
  }).filter(Boolean).join('\n');
  // ★ Văn bản tầng đã qua lọc thẻ
  const tags = _s?.filterTags || [];
  const scene = windowFloors.map(m => `[#${m.message_id} ${m.name}] ${cdFilterTags(m.mes, tags)}`).join('\n\n');

  // ★★★ Log chẩn đoán: Xác nhận số tầng và nội dung của hồ sơ cốt truyện truyền vào có hoàn chỉnh không ★★★
  try {
    const _fl = (windowFloors || []).map(function (m) {
      const _t = String((m && m.mes) || '');
      return { id: m && m.message_id, name: (m && m.name) || '', len: _t.length, pre: _t.slice(0, 30) };
    });
    cdAddLog('info', '[Hồ sơ·Chẩn đoán] Tầng truyền vào', {
      Số_tầng: (windowFloors || []).length,
      Chi_tiết: _fl,
      Tổng_ký_tự_scene: (scene || '').length,
      Độ_dài_tuyến_chính_đã_có: (existing.mainline || '').length,
      Độ_dài_tuyến_phụ_đã_có: (existing.sideline || '').length,
      Độ_dài_trạng_thái_đã_có: (existing.states || '').length,
      Độ_dài_chưa_giải_quyết_đã_có: (existing.unresolved || '').length,
    });
  } catch (_e) { cdAddLog && cdAddLog('warn', '[Hồ sơ·Chẩn đoán] Log bất thường ' + (_e && _e.message)); }

  // ★ Chế độ vector hóa: Truy hồi các mục liên quan từ các sự kiện lịch sử, thay thế cho việc nhúng toàn bộ
  if (_s?.archiveMode === 'vector') {
    const vectors = data.archiveVectors;
    if (Array.isArray(vectors) && vectors.length > 0) {
      const topK = _s.vectorTopK || 5;
      const threshold = _s.vectorThreshold || 0.6;
      // Dùng văn bản tầng hiện tại để làm truy hồi
      const sceneText = windowFloors.map(m => `${m.name}: ${cdFilterTags(m.mes, tags)}`).join('\n');
      let results = await cdSearchVectors(sceneText, vectors, topK, threshold);
      // ★ Rerank sắp xếp lại (Luồng hồ sơ cốt truyện)
      results = await cdRerankResults(sceneText, results, _s, 'story');
      const retrievedText = results.length > 0
        ? results.map(r => r.text).join('\n')
        : '（Chưa truy hồi được sự kiện lịch sử liên quan）';
      const sys = [
        _archSys,
        '',
        (typeof data === 'object' && data !== null && typeof data.lastFloor === 'number' && data.lastFloor === -1)
          ? '【Yêu cầu đặc biệt cho lần ghi đầu tiên】Lần nhập này có chứa 【Lời dạo đầu tầng 0】 ở phần mở đầu。Vui lòng lấy bối cảnh/thời gian/địa điểm/nhân vật xuất hiện và trạng thái quan hệ hiện tại của họ với nhau trong đó làm "Điểm khởi đầu tuyến chính/Trạng thái quan trọng" để ưu tiên viết vào hồ sơ，đừng vì nó là miêu tả tĩnh、không phải sự kiện mà bỏ sót。'
          : '',
        '',
        customFormatBlock ? 'Mục theo dõi tùy chỉnh (Xuất ra thêm sau bốn trường cốt lõi, thuộc về trường phụ thuộc, không được thay thế bốn trường cốt lõi)：\n' + customFormatBlock : '',
        '',
        '**Các sự kiện liên quan được truy hồi từ hồ sơ lịch sử (để tham khảo)**：',
        retrievedText,
      ].filter(Boolean).join('\n');
      const usr = [
        (archiveFull ? `Dưới đây là toàn bộ các tầng của cốt truyện (vui lòng tóm tắt hoàn chỉnh toàn bộ cốt truyện)：\n${scene}` : `Các tầng mới thêm lần này：\n${scene}`),
        '',
        `Vui lòng ${archiveFull ? 'xuất ra một cách hoàn chỉnh đoạn cốt truyện này từ đầu đến hiện tại về' : 'phân tích trong các tầng mới thêm về'} tiến triển cốt truyện，xuất ra：Tuyến chính、Tuyến phụ、Thay đổi trạng thái quan trọng、Các vấn đề chưa giải quyết${customOutputNames ? '、' + customOutputNames : ''}。`,
        archiveFull ? 'Đây là việc tái tạo toàn bộ，vui lòng ghi đè xuất ra tuyến chính và trạng thái hoàn chỉnh hiện tại，đừng giả định là trước đó đã ghi nhận mà bỏ qua cốt truyện giai đoạn đầu。' : 'Có thể trích dẫn nội dung trong "Các sự kiện liên quan được truy hồi" ở trên，nhưng đừng xuất ra lặp lại，chỉ cập nhật tăng dần。',
      ].join('\n');
      return [
        { role: 'system', content: sys },
        { role: 'user', content: usr },
        { role: 'assistant', content: 'Tuyến chính：' },
      ];
    }
    // Thư viện vector trống, hạ cấp xuống chế độ thông thường
    cdLog('cdBuildArchivePrompt: Thư viện vector trống, hạ cấp xuống chế độ thông thường');
  }
  
  // Chế độ thông thường (logic cũ)
  const sys = [
    _archSys,
    '',
    (typeof data === 'object' && data !== null && typeof data.lastFloor === 'number' && data.lastFloor === -1)
      ? '【Yêu cầu đặc biệt cho lần ghi đầu tiên】Lần nhập này có chứa 【Lời dạo đầu tầng 0】 ở phần mở đầu。Vui lòng lấy bối cảnh/thời gian/địa điểm/nhân vật xuất hiện và trạng thái quan hệ hiện tại của họ với nhau trong đó làm "Điểm khởi đầu tuyến chính/Trạng thái quan trọng" để ưu tiên viết vào hồ sơ，đừng vì nó là miêu tả tĩnh、không phải sự kiện mà bỏ sót。'
      : '',
    archiveFull ? '**（Chế độ tái tạo toàn bộ）Vui lòng dựa vào toàn bộ các tầng bên dưới để xuất ra hoàn chỉnh hồ sơ cốt truyện hiện tại，ghi đè lên giá trị cũ，đừng bỏ sót cốt truyện giai đoạn đầu**：' : '**Tiến triển cốt truyện đã có (Vui lòng mở rộng tăng dần, đừng lặp lại)**：',
    ...(_s.summarizeInjectArchive ? [
      existing.mainline ? `Tuyến chính đã biết：${existing.mainline}` : 'Tuyến chính đã biết：（Chưa có，đây là lần đầu）',
      existing.sideline ? `Tuyến phụ đã biết：${existing.sideline}` : '',
      existing.states ? `Trạng thái quan trọng đã biết：${existing.states}` : '',
      existing.unresolved ? `Các vấn đề chưa giải quyết đã biết：${existing.unresolved}` : '',
      existingCustomTxt ? `\n${existingCustomTxt}` : '',
    ] : []),
    customFormatBlock ? '\nMục theo dõi tùy chỉnh (Cũng xuất ra nghiêm ngặt theo định dạng, sau khi xuất ra hoàn chỉnh tất cả, hãy xuất ra riêng rẽ dưới dạng trường phụ thuộc bổ sung, đừng bỏ qua hoặc thay thế bốn trường cốt lõi)：\n' + customFormatBlock : '',
  ].filter(Boolean).join('\n');
  // ★ Liên kết Worldbook: Gọi API bất đồng bộ để lấy thiết lập Worldbook của nhân vật xuất hiện (loadWorldInfo là API bất đồng bộ)
  let _worldbookTxtArchive = '';
  if (_s && _s.summarizeInjectArchive && _s.worldbookLink !== false) {
    try {
      const _wr2 = cdSceneWorldbookRoles(windowFloors, data);
      if (_wr2.length) _worldbookTxtArchive = await cdGetWorldbookForRoles(_wr2);
    } catch (e) { if (typeof cdWarn === 'function') cdWarn('Liên kết Worldbook (Hồ sơ) đọc thất bại:', e); }
  }
  const usr = [
    (archiveFull ? `Dưới đây là toàn bộ các tầng của cốt truyện (vui lòng tóm tắt hoàn chỉnh toàn bộ cốt truyện)：\n${scene}` : `Các tầng mới thêm lần này：\n${scene}`),
    '',
    (archiveFull
      ? `Vui lòng xuất ra hoàn chỉnh đoạn cốt truyện này từ lúc bắt đầu đến hiện tại：Tuyến chính、Tuyến phụ、Thay đổi trạng thái quan trọng、Các vấn đề chưa giải quyết${customOutputNames ? '、' + customOutputNames : ''}。`
      : [
          'Vui lòng xuất ra hồ sơ cốt truyện (Chế độ tăng dần thông thường)，và tuân thủ nghiêm ngặt các quy tắc sắt sau：',
          '1. Bắt buộc phải xuất ra hoàn chỉnh bốn trường cốt lõi【Tuyến chính】【Tuyến phụ】【Thay đổi trạng thái quan trọng】【Các vấn đề chưa giải quyết】，thứ tự cố định là Tuyến chính→Tuyến phụ→Thay đổi trạng thái quan trọng→Các vấn đề chưa giải quyết；Dù lần này không có nội dung tương ứng，cũng phải xuất ra một dòng「Không có」dưới trường tương ứng，tuyệt đối không cho phép thiếu sót hoặc bỏ qua bốn trường cốt lõi này。',
          '2. Bốn trường cốt lõi này là chủ thể của đầu ra lần này，bắt buộc phải đặt ở phía trước nhất。',
          '3. Sau bốn trường cốt lõi，mới xuất ra thêm các mục theo dõi tùy chỉnh：' + (customOutputNames ? customOutputNames : 'Không có') + '（Dưới dạng khối bổ sung，không được thay thế hoặc chiếm vị trí của bốn trường cốt lõi）。',
          '4. Bất kể các tầng lần này đơn giản đến đâu hay chỉ chứa lời dạo đầu/miêu tả tĩnh，cũng phải chải chuốt các nhân vật、quan hệ、bối cảnh、thiết lập trong đó thành nội dung khởi đầu của tuyến chính/trạng thái quan trọng để ghi vào trường cốt lõi tương ứng，đảm bảo các nội dung liên quan đến lời dạo đầu được thu thập trọn vẹn。'
        ].join('\n')
    ),
    // ★ Nhân vật trọng điểm: Hướng dẫn hồ sơ cốt truyện ghi chép xoay quanh những nhân vật này, ngăn họ thoát ly thiết lập
    (Array.isArray(data.focusRoles) && data.focusRoles.length)
      ? `【Nhân vật trọng điểm (Trong hồ sơ phải trọng điểm ghi chép lại thay đổi trạng thái/động thái/quan hệ của họ)】\n${data.focusRoles.map(f => '  - ' + (f.name || '') + (f.note ? `：${f.note}` : '')).join('\n')}`
      : '',
    // ★ Liên kết Worldbook: Nhúng thiết lập Worldbook của nhân vật xuất hiện lần này
    _worldbookTxtArchive ? '【Tham khảo thiết lập Worldbook (Nhân vật xuất hiện lần này)】\n' + _worldbookTxtArchive : '',
  ].filter(Boolean).join('\n');
  return [
    { role: 'system', content: sys },
    { role: 'user', content: usr },
    { role: 'assistant', content: 'Tuyến chính：' },
  ];
}

/** ★ Prompt kết hợp: Một lần gọi API hoàn thành "Nhật ký nhân vật + Hồ sơ cốt truyện", nối động (Tích cái nào nối cái đó) */
async function cdBuildDiaryArchiveCombined(windowFloors, data, s, archiveFull) {
  const hasDiary = s.enableDiary !== false;
  const hasArch  = s.enableArchive !== false;
  const diaryMsgs = hasDiary ? await cdBuildDiaryPrompt(windowFloors, data, s) : null;
  const archMsgs  = hasArch  ? await cdBuildArchivePrompt(windowFloors, data, s, archiveFull) : null;
  const sysParts = [];
  // ★ [2026-09-19] Chế độ kết hợp bổ sung vượt rào (Lỗi cũ: Khi hướng tới người lớn, AI thu hẹp việc lưu trữ -> Đoạn hồ sơ thường chỉ đưa ra tiêu đề chương hồi).
  try { const _jb = (typeof JAILBREAK !== "undefined" && JAILBREAK) ? (Array.isArray(JAILBREAK) ? JAILBREAK.join("\n") : String(JAILBREAK)) : ""; if (_jb) sysParts.push(_jb); } catch(_e){}
  sysParts.push('Bạn là một AI chỉnh lý ký ức đa chức năng。Vui lòng dựa vào cùng một đoạn cốt truyện được cung cấp bên dưới，hoàn thành các nhiệm vụ được giao cho bạn dưới đây，và phân đoạn xuất ra nghiêm ngặt theo yêu cầu。');
  if (diaryMsgs) {
    sysParts.push('【Nhiệm vụ 1: Nhật ký nhân vật】Vui lòng tuân thủ trọn vẹn toàn bộ yêu cầu của Nhiệm vụ 1 dưới đây，xuất ra mảng đối tượng JSON của nhật ký nhân vật（giữ nguyên ngôi thứ nhất、số chữ、các tầng nội tâm và mọi ràng buộc khác）。Nếu còn bao gồm Nhiệm vụ 2，thì sau khi bạn xuất ra JSON hoàn chỉnh của Nhiệm vụ 1 và đóng lại，hãy xuống dòng mới và chỉ viết một dòng dấu phân cách <<<CD_NEXT>>>，rồi tiếp tục xuất ra Nhiệm vụ 2。\n\n' + (diaryMsgs[0] ? diaryMsgs[0].content : ''));
  }
  if (archMsgs) {
    sysParts.push('【Nhiệm vụ 2: Hồ sơ cốt truyện】Vui lòng tuân thủ trọn vẹn toàn bộ yêu cầu của Nhiệm vụ 2 dưới đây，xuất ra bốn đoạn văn bản thuần túy Tuyến chính/Tuyến phụ/Thay đổi trạng thái quan trọng/Các vấn đề chưa giải quyết của hồ sơ cốt truyện。★ Quy tắc sắt：Dù cốt truyện có ngắn gọn đến đâu cũng phải giữ lại thẻ trường của mỗi đoạn và xuất ra nội dung（Không có nội dung thì viết "Không có"），tuyệt đối cấm việc chỉ xuất ra "Tiêu đề chương hồi/Tổng quan cốt truyện" mà không viết Tuyến chính Tuyến phụ Trạng thái Chưa giải quyết。Lưu ý：Tại ranh giới của mỗi lần phân đoạn，chỉ viết một dòng dấu phân cách <<<CD_NEXT>>>。Nếu chỉ có một nhiệm vụ này，thì xuất ra nội dung trực tiếp、đừng vẽ thêm bất kỳ dấu phân cách nào。\n\n' + (archMsgs[0] ? archMsgs[0].content : ''));
  }
  sysParts.push('Quy tắc dấu phân cách：Giữa mỗi đoạn nội dung chỉ dùng chính xác một dấu「<<<CD_NEXT>>>」đứng riêng thành một dòng để phân cách，ngoài ra đừng để ký hiệu này xuất hiện thêm。Viết trước thì đặt trước，viết sau thì đặt sau。');
  const sys = sysParts.join('\n\n');
  const usr = archMsgs ? archMsgs[1].content : (diaryMsgs ? diaryMsgs[1].content : '');
  const asst = diaryMsgs ? '{"npcs":[' : (archMsgs ? 'Tuyến chính：' : '');
  // ★ [Hồ sơ·Chẩn đoán] In ra đoạn prompt thực tế gửi cho AI, xác nhận xem có chứa bộ tứ Tuyến chính/Tuyến phụ không
  try {
    const _sysHasMain = String(sys).indexOf('Tuyến chính') >= 0;
    const _sysHasSide = String(sys).indexOf('Tuyến phụ') >= 0;
    const _sysHasState = String(sys).indexOf('Thay đổi trạng thái quan trọng') >= 0;
    const _sysHasUnres = String(sys).indexOf('Các vấn đề chưa giải quyết') >= 0;
    const _usrHead = String(usr || '').slice(0, 300);
    cdAddLog('info', '[Hồ sơ·Chẩn đoán Prompt] Cấu trúc prompt hồ sơ gửi cho AI', {
      sys_chứa_Tuyến_chính: _sysHasMain,
      sys_chứa_Tuyến_phụ: _sysHasSide,
      sys_chứa_Thay_đổi_trạng_thái_quan_trọng: _sysHasState,
      sys_chứa_Các_vấn_đề_chưa_giải_quyết: _sysHasUnres,
      Số_ký_tự_sys: String(sys||'').length,
      Số_ký_tự_usr: String(usr||'').length,
      '300_chữ_đầu_của_usr': _usrHead,
      assistant_điền_sẵn: asst,
      Cấu_hình_customFields: (Array.isArray((typeof cdGetSettings==='function')?cdGetSettings().customFields:undefined))?cdGetSettings().customFields:[]
    });
  } catch (_ed) { if (typeof cdWarn === 'function') cdWarn('[Hồ sơ·Chẩn đoán Prompt] Bất thường', _ed); }
  return [
    { role: 'system', content: sys },
    { role: 'user', content: usr },
    { role: 'assistant', content: asst },
  ];
}
/** Tách kết quả trả về kết hợp: Phân cách theo <<<CD_NEXT>>> để hút ra "Văn bản nhật ký" và "Văn bản hồ sơ"; hasDiary/hasArch dùng để phân bổ dự phòng khi không có dấu phân cách */
function cdSplitDiaryArchive(text, hasDiary, hasArch) {
  const t = String(text || '');
  const A = '<<<CD_NEXT>>>';
  // ★ Ranh giới dùng dấu phân cách đầu tiên (indexOf): Khi mở cùng lúc Nhật ký + Hồ sơ, trước dấu phân cách đầu tiên = Nhật ký, sau = Toàn bộ hồ sơ.
  //   Trước đây dùng lastIndexOf (Dấu cuối cùng) sẽ vô tình nuốt trọn đoạn nội dung hồ sơ trước dấu phân cách và coi đó là nhật ký —— Đây chính là thủ phạm khiến hồ sơ bị cắt rỗng/chỉ còn lại tiêu đề chương hồi.
  const iA = t.indexOf(A);
  if (hasDiary !== false && hasArch !== false && iA >= 0) {
    const before = t.slice(0, iA).trim();
    const after  = t.slice(iA + A.length).trim();
    return { diaryText: before, archiveText: after };
  }
  // Chỉ mở Hồ sơ: Tất cả quy về Hồ sơ (Nới lỏng, dù thừa dấu phân cách cũng không sao)
  if (hasDiary === false && hasArch !== false) {
    return { diaryText: '', archiveText: t.trim() };
  }
  // Chỉ mở Nhật ký: Tất cả quy về Nhật ký
  if (hasArch === false && hasDiary !== false) {
    return { diaryText: t.trim(), archiveText: '' };
  }
  // Mở cả hai nhưng không có dấu phân cách: Phân biệt theo Thẻ/Nội dung chính của hồ sơ
  const arcLabels = ['Tuyến chính：','Tuyến phụ：','Thay đổi trạng thái quan trọng：','Các vấn đề chưa giải quyết：','Tiêu đề chương hồi：','Tổng quan cốt truyện：','Danh sách vật phẩm：','Mỏ neo thời gian hiện tại：','Ghi chép nhiệm vụ：'];
  let eIdx = -1;
  for (const lb of arcLabels) { const p = t.indexOf(lb); if (p >= 0 && (eIdx < 0 || p < eIdx)) eIdx = p; }
  if (eIdx >= 0) {
    return { diaryText: t.slice(0, eIdx).trim(), archiveText: t.slice(eIdx).trim() };
  }
  const hasTimestampBody = /\n【[^】]+】|^【[^】]+】/.test(t) && /[·,，:：]|\d{4}năm|\d{1,2}tháng|\d{1,2}ngày|\d{1,2}[::]\d{2}/.test(t);
  if (hasTimestampBody) {
    const jsonStart = t.indexOf('\n{"npcs"');
    if (jsonStart >= 0) return { diaryText: t.slice(0, jsonStart).trim(), archiveText: t.slice(jsonStart).trim() };
    return { diaryText: '', archiveText: t.trim() };
  }
  return { diaryText: t.trim(), archiveText: '' };
}

/** Xóa các thẻ phân cách còn sót lại trong đầu ra kết hợp (<<<CD_NEXT>>> và các biến thể như CD NEXT), tránh để chúng làm ô nhiễm hồ sơ cốt truyện/giao diện trạng thái */
function cdStripArchiveSeq(s){
  if(!s) return '';
  return String(s).replace(/<{2,3}\s*CD[_ \t-]*NEXT\s*>{2,3}/gi, '')
    .split('\n').map(function(x){return String(x||'').trim();}).filter(Boolean).join('\n');
}
/** Phân tích văn bản trường vật phẩm thành mảng có thứ tự [{ time, desc }], giữ nguyên thứ tự ghi thêm của nguyên tác */
function parseItemsText(text) {
  const out = [];
  if (!text) return out;
  let curTime = '';
  for (const line of String(text).split('\n')) {
    const trimmed = line.trim();
    if (!trimmed) continue;
    const m = trimmed.match(/^【([^】]+)】\s*(.*)/);
    if (m) {
      curTime = m[1];
      out.push({ time: curTime, desc: m[2] });
    } else if (curTime && trimmed.length > 1 && out.length) {
      out[out.length - 1].desc += ' ' + trimmed;
    }
  }
  return out;
}

/** Phân tích các trường của hồ sơ cốt truyện (Tuyến chính/Tuyến phụ/Thay đổi trạng thái quan trọng/Các vấn đề chưa giải quyết + Mục theo dõi tùy chỉnh của người dùng) */
function parseArchiveJson(text, customDefs) {
  let raw = String(text || '').trim();
  try{ raw = (typeof cdStripArchiveSeq==='function') ? cdStripArchiveSeq(raw) : raw; }catch(_e){}
  let _locRaw = '';
  const _locM = String(raw).match(/<<<LOCATIONS>>>([\s\S]*?)<<<LOCATIONS_END>>>/);
  if (_locM) {
    _locRaw = _locM[1];
    raw = String(raw).replace(/<<<LOCATIONS>>>[\s\S]*?<<<LOCATIONS_END>>>/, '');
  }
  const defs = Array.isArray(customDefs) ? customDefs : [];
  // Toàn bộ thẻ trường: 4 thẻ tích hợp + label của mỗi mục tùy chỉnh
  const builtin = ['Tuyến chính', 'Tuyến phụ', 'Thay đổi trạng thái quan trọng', 'Các vấn đề chưa giải quyết', 'Tổng quan cốt truyện', 'Tiêu đề chương hồi', 'Danh sách vật phẩm', 'Mỏ neo thời gian hiện tại', 'Ghi chép nhiệm vụ'];
  const customLabels = defs.map(d => d && d.label ? d.label : '').filter(Boolean);
  // Sắp xếp giảm dần theo độ dài, tránh việc "Trạng thái nhân vật chính" bị "Trạng thái" cắt ngang trước
  const allLabels = builtin.concat(customLabels).sort((a, b) => b.length - a.length);
  const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const labelAlt = allLabels.map(esc).join('|');
  const labelRe = new RegExp('^(' + labelAlt + ')[：:]');
  // Cắt theo từng dòng (Ổn định, tránh việc Regex không tham lam nuốt thẻ xuyên biên giới)
  const parts = {};
  // assistant được điền sẵn là "Tuyến chính:", do đó phần viết tiếp ở đầu phản hồi của AI mặc định được đưa vào Tuyến chính, cho đến khi gặp thẻ tiếp theo
  let curLabel = 'Tuyến chính';
  parts['Tuyến chính'] = '';
  const splitLines = String(raw).split('\n');
  for (const line of splitLines) {
    const trimmed = line.trim();
    if (!trimmed) continue;
    const hm = trimmed.match(labelRe);
    if (hm) {
      curLabel = hm[1].trim();
      parts[curLabel] = '';
      continue;
    }
    if (curLabel !== null) {
      parts[curLabel] = (parts[curLabel] ? parts[curLabel] + '\n' : '') + trimmed;
    }
  }
  // Các trường tích hợp
  const mainline   = parts['Tuyến chính'] || '';
  const sideline   = parts['Tuyến phụ'] || '';
  const states     = parts['Thay đổi trạng thái quan trọng'] || '';
  const unresolved = parts['Các vấn đề chưa giải quyết'] || '';
  const locations   = String(_locRaw || '').split('\n').map(function(s){return String(s).replace(/【[^】]*】/g,'').trim();}).filter(function(s){return s && s !== 'Không có' && s !== 'Không có.' && !/^[(（]/.test(s);});
  // Các trường tùy chỉnh (Cũng phân tích thành mảng theo đánh dấu thời gian)
  const custom = {};
  for (const d of defs) {
    if (!d || !d.key || !d.label) continue;
    const body = parts[d.label];
    custom[d.key] = body ? parseItemsText(body) : [];
  }
  const title = (parts['Tiêu đề chương hồi'] || '').split('\n').filter(Boolean)[0] || '';
  const lead  = (parts['Tổng quan cốt truyện'] || '').split('\n').filter(Boolean).join('\n').trim();
  // ====== Danh sách vật phẩm + Mỏ neo thời gian hiện tại (Mới thêm lần này) ======
  const _itemsLog = [];    // Nhật ký biến động [{time, desc}]
  const _itemsHold = [];   // Nắm giữ hiện tại [{line}]
  var _mg = parts['Danh sách vật phẩm'] || '';
  var _mgSec = '';
  var _mglines = String(_mg).split('\n');
  for (var _mi = 0; _mi < _mglines.length; _mi++) {
    var _ml = String(_mglines[_mi] || '').trim();
    if (!_ml) continue;
    if (/^Nắm giữ hiện tại/.test(_ml) || /^Tên vật phẩm\|/.test(_ml)) { _mgSec = 'hold'; continue; }
    if (/^Nhật ký biến động/.test(_ml)) { _mgSec = 'log'; continue; }
    if (_mgSec === 'log') { _itemsLog.push({ time: '', desc: _ml }); }
    else if (_mgSec === 'hold') { if (_ml && _ml !== 'Không có') _itemsHold.push({ line: _ml }); }
  }
  for (var _li = 0; _li < _itemsLog.length; _li++) {
    var _tm = String(_itemsLog[_li].desc).match(/^【([^】]+)】\s*(.*)/);
    if (_tm) { _itemsLog[_li].time = _tm[1]; _itemsLog[_li].desc = _tm[2]; }
  }
  var timeAnchor = (parts['Mỏ neo thời gian hiện tại'] || '').split('\n').map(function(_x){return _x.trim();}).filter(Boolean).join(' ').trim();
  // ===== Ghi chép nhiệm vụ (Kiểu ghi đè, mỗi nhiệm vụ một dòng: Tên nhiệm vụ|Người giao|Tiến độ|Bước tiếp theo|Giới hạn thời gian|Thời gian thúc đẩy gần nhất) =====
  const _tasks = [];
  var _tk = parts['Ghi chép nhiệm vụ'] || '';
  var _tklines = String(_tk).split('\n');
  for (var _ti = 0; _ti < _tklines.length; _ti++) {
    var _tl = String(_tklines[_ti] || '').trim();
    if (!_tl || _tl === 'Không có') continue;
    if (/^Ghi chép nhiệm vụ|^（|^Tên nhiệm vụ/.test(_tl)) continue;
    if (/^Địa điểm[：:]/.test(_tl)) continue;   // Địa điểm đã được hiển thị ở bản đồ/nhân vật chính/thẻ môi trường, loại bỏ khỏi nhiệm vụ để tránh lặp lại
    _tasks.push({ line: _tl });
  }
  return { mainline, sideline, states, unresolved, locations, items: _itemsLog, itemsHold: _itemsHold, timeAnchor, tasks: _tasks, custom, title, lead };
}

function cdBuildRelationPrompt(windowFloors, data, _s) {
  const known = Object.keys(data.diaries);
  // ★ Văn bản tầng đã qua lọc thẻ
  const tags = _s?.filterTags || [];
  const scene = windowFloors.map(m => `[#${m.message_id} ${m.name}] ${cdFilterTags(m.mes, tags)}`).join('\n\n');
  const sys = [
    'Bạn là một nhà phân tích quan hệ nhân vật. Hãy đọc đoạn cốt truyện được cung cấp, trích xuất "Quan hệ chủ quan một chiều" giữa các nhân vật.',
    'Yêu cầu:',
    '- Chủ quan một chiều: Quan hệ từ from đối với to (from nhìn nhận to như thế nào). A nhìn B và B nhìn A có thể khác nhau, vui lòng ghi riêng mỗi chiều một mục.',
    '- Chỉ phân tích quan hệ giữa các nhân vật có tên và có đất diễn, bỏ qua người qua đường thuần túy.',
    '- Không bao gồm người dùng/nhân vật người chơi.',
    '- type: Dùng từ ngắn gọn khái quát tính chất quan hệ (ví dụ "Bạn thân", "Yêu thầm", "Thù địch", "Chủ tớ", "Cảnh giác", "Dựa dẫm").',
    '- attitude: Khuynh hướng tình cảm, chỉ có thể là một trong "positive" (Thân thiện/Gần gũi), "negative" (Thù địch/Bài xích), "neutral" (Trung lập).',
    '- note: Giải thích bằng một câu (Dưới 20 chữ).',
    known.length ? `Nhân vật đã biết: ${known.join('、')}` : '',
    'Nghiêm ngặt chỉ xuất ra JSON, định dạng:',
    '{"relations":[{"from":"A","to":"B","type":"Tính chất quan hệ","attitude":"positive","note":"Giải thích ngắn gọn"}]}',
  ].filter(Boolean).join('\n');
  const usr = `Đoạn cốt truyện lần này:\n${scene}\n\nVui lòng xuất ra JSON quan hệ.`;
  return [
    { role: 'system', content: JAILBREAK + '\n\n' + sys },
    { role: 'user', content: usr },
    { role: 'assistant', content: '{"relations":[' },
  ];
}

/* ============================== Lọc nội dung ============================== */

/** Dựa trên cặp thẻ do người dùng tùy chỉnh, lọc bỏ những nội dung không cần gửi cho AI */
function cdFilterTags(text, tags) {
  if (!text || !Array.isArray(tags) || !tags.length) return text;
  let result = String(text);
  for (const pair of tags) {
    const start = String(pair?.start || '').trim();
    const end = String(pair?.end || '').trim();
    if (!start || !end) continue;
    let si = result.indexOf(start);
    while (si !== -1) {
      const ei = result.indexOf(end, si + start.length);
      if (ei === -1) {
        result = result.slice(0, si);
        break;
      }
      result = result.slice(0, si) + result.slice(ei + end.length);
      si = result.indexOf(start);
    }
  }
  return result.trim();
}

/** Thống kê tổng số lượng các mục có mang [Đánh dấu thời gian] trong hồ sơ cốt truyện */
function cdCountArchiveEntries(archive) {
  if (!archive) return 0;
  const itemsText = (Array.isArray(archive.items) && archive.items.length) ? archive.items.map(it => it.time ? `【${it.time}】${it.desc}` : it.desc).join('\n') : '';
  const allText = [archive.mainline, archive.sideline, archive.states, archive.unresolved, itemsText].filter(Boolean).join('\n');
  let count = (allText.match(/【[^】]+】/g) || []).length;
  // Mục theo dõi tùy chỉnh (Đánh dấu thời gian của mỗi mục cũng được tính là một)
  if (archive.custom && typeof archive.custom === 'object') {
    for (const key of Object.keys(archive.custom)) {
      const arr = Array.isArray(archive.custom[key]) ? archive.custom[key] : [];
      for (const it of arr) {
        if (it && (it.time || it.desc)) count += 1;
      }
    }
  }
  return count;
}

/* ============================== Nén tự động ============================== */

/** Thống kê tổng số chữ của hồ sơ cốt truyện (Bốn trường văn bản + desc của mục theo dõi tùy chỉnh), dùng cho chế độ size */
function cdArchiveSize(archive) {
  if (!archive) return 0;
  let size = 0;
  const texts = [archive.mainline, archive.sideline, archive.states, archive.unresolved].filter(Boolean);
  for (const t of texts) size += String(t).length;
  if (archive.custom && typeof archive.custom === 'object') {
    for (const key of Object.keys(archive.custom)) {
      const arr = Array.isArray(archive.custom[key]) ? archive.custom[key] : [];
      for (const it of arr) {
        if (it && it.desc) size += String(it.desc).length;
      }
    }
  }
  return size;
}

/**
 * Đánh giá xem có nên nén tự động hay không
 * mode 'count': Kích hoạt khi số mục đạt threshold và số mục mới thêm so với lần nén trước đạt threshold/2
 * mode 'size' : Kích hoạt khi tổng số chữ mới thêm đạt autoCompressSize (Sau khi nén sẽ reset lastCompressSize)
 */
function cdAutoCompressShouldTrigger(data, s) {
  if (!data || !data.archive) return false;
  const mode = s.autoCompressMode || 'count';
  if (mode === 'size') {
    const size = cdArchiveSize(data.archive);
    const sizeTh = Math.max(200, s.autoCompressSize || 2000);
    const lastSize = data._lastCompressSize || 0;
    const inc = size - lastSize;
    if (inc >= sizeTh) {
      cdAddLog('info', `Kích hoạt nén tự động [Số chữ]: Hiện tại ${size} chữ, Lần trước ${lastSize} chữ, Mới thêm ${inc} chữ, Ngưỡng ${sizeTh}`);
      return true;
    }
    return false;
  }
  // Chế độ count (Mặc định)
  const entryCount = cdCountArchiveEntries(data.archive);
  const threshold = Math.max(5, s.autoCompressThreshold || 30);
  const lastCount = data._lastCompressEntryCount || 0;
  if (entryCount >= threshold && (entryCount - lastCount) >= Math.floor(threshold / 2)) {
    cdAddLog('info', `Kích hoạt nén tự động [Số mục]: Hiện tại ${entryCount} sự kiện, Ngưỡng ${threshold}`);
    return true;
  }
  return false;
}

/** Từ văn bản kết quả nén, phân tích theo phân đoạn tiêu đề và điền ngược lại vào bốn trường của archive */
function cdParseCompressedBlocks(text, labels) {
  const out = {};
  const heads = Object.keys(labels);
  // Ưu tiên khớp với tiêu đề dài nhất, tránh việc "Tuyến chính" bị nuốt nhầm bởi chữ trong "Thay đổi trạng thái quan trọng"
  const sorted = heads.slice().sort((a, b) => labels[b].length - labels[a].length);
  const clean = String(text || '').trim();
  // Tìm tất cả các vị trí xuất hiện của tiêu đề
  const positions = [];
  const reGlobal = /【([^】]*)】/g;
  let m;
  while ((m = reGlobal.exec(clean)) !== null) {
    const label = m[1].trim();
    const key = heads.find(k => labels[k] === label);
    if (key !== undefined) {
      positions.push({ key, label, idx: m.index });
    }
  }
  if (!positions.length) {
    // Không có cấu trúc tiêu đề: Tất cả quy về Tuyến chính làm dự phòng
    out.mainline = clean;
    return out;
  }
  for (let i = 0; i < positions.length; i++) {
    const cur = positions[i];
    const start = cur.idx;
    const end = (i + 1 < positions.length) ? positions[i + 1].idx : clean.length;
    let seg = clean.slice(start, end);
    // Chỉ xóa dòng tiêu đề ở đầu đoạn này ([Tiêu đề]), không chạm vào các ký hiệu khác trong nội dung đoạn
    seg = seg.replace(/^\s*【[^】]*】\s*/, '');
    seg = seg.trim();
    out[cur.key] = seg;
  }
  // Dự phòng cho trường hợp chỉ có tiêu đề mà không có nội dung: Nếu một trường phân tích ra trống nhưng văn bản thực sự có xuất hiện tiêu đề đó, cố gắng gán toàn bộ phần còn lại sau tiêu đề cho nó
  const last = positions[positions.length - 1];
  const tail = clean.slice(last.idx).replace(/^\s*【[^】]*】\s*/, '').trim();
  if (tail && !out[last.key]) out[last.key] = tail;
  return out;
}

/**
 * Nén và dung hợp hồ sơ cốt truyện (Gọi API một lần, nén bốn trường văn bản + gập mục theo dõi tùy chỉnh)
 * @param {object} data      Toàn bộ đối tượng data (Sẽ bị sửa đổi tại chỗ)
 * @param {object} s         Cài đặt
 * @param {boolean} isAuto   Có phải được gọi do kích hoạt tự động không (true=Ghi lại đường cơ sở sau khi kích hoạt; Thủ công false=Không ghi đường cơ sở)
 */
async function cdCompressArchive(data, s, isAuto) {
  if (!data || !data.archive) return;
  const archive = data.archive;
  const fields = ['mainline', 'sideline', 'states', 'unresolved'];
  const labels = { mainline: 'Tuyến chính', sideline: 'Tuyến phụ', states: 'Thay đổi trạng thái quan trọng', unresolved: 'Các vấn đề chưa giải quyết' };

  // Lắp ráp các khối nội dung cần nén
  const blocks = [];
  for (const f of fields) {
    const c = archive[f];
    if (c && String(c).trim()) blocks.push(`【${labels[f]}】\n${String(c).trim()}`);
  }

  // Văn bản mục theo dõi tùy chỉnh cũng được gộp vào (Làm khối thứ năm, giao cho AI cùng cô đọng lại)
  const customTexts = [];
  const customFields = Array.isArray(s.customFields) ? s.customFields.filter(x => x && x.key && x.label) : [];
  if (archive.custom && typeof archive.custom === 'object') {
    for (const key of Object.keys(archive.custom)) {
      const def = customFields.find(x => x.key === key);
      const lbl = (def && def.label) || key;
      const arr = Array.isArray(archive.custom[key]) ? archive.custom[key] : [];
      if (arr.length) {
        const joined = arr.map(it => (it.time ? `${it.time}：` : '') + (it.desc || '')).join('；');
        if (joined) customTexts.push(`【${lbl}】\n${joined}`);
      }
    }
  }
  if (customTexts.length) blocks.push(...customTexts);

  const joinText = blocks.join('\n\n');
  if (!joinText) { cdLog('cdCompressArchive: Không có nội dung để nén'); return; }

  const COMPRESS_PROMPT = `Bạn là một người chỉnh lý hồ sơ cốt truyện. Hãy nén và dung hợp bản tóm tắt cốt truyện được chia đoạn theo [Tiêu đề] dưới đây thành một bản hồ sơ cốt truyện "Gọn gàng hơn, nhưng không làm mất đi bất kỳ sự kiện nào đã xảy ra".

[Quy tắc sắt số 1: Giảm béo chứ không cắt cụt, không phải chọn ý chính]
- Việc "Nén" này là dùng các câu ngắn hơn để thuật lại từng đoạn văn, mục tiêu là giữ lại một hồ sơ [Thông tin hoàn chỉnh, Đầy đủ sự kiện], chứ không phải chỉ chọn ra vài sự kiện quan trọng.
- Trong Tuyến chính, Tuyến phụ, tất cả "Những việc đã xảy ra", dù nhỏ bé hay có vẻ phụ yếu đến đâu, cũng không được xóa bất kỳ việc nào —— Mỗi sự kiện đều phải được giữ lại bằng cách tinh gọn hơn (có thể gộp các việc nhỏ cùng loại thành một câu, nhưng không được coi như chưa từng xảy ra).
- Nghiêm cấm nén các sự thật cụ thể thành khái quát trừu tượng (những câu mơ hồ như "Gặp một số rắc rối", "Đã xảy ra khá nhiều chuyện", không được phép xuất hiện).
- Độ dài sau khi nén nên bằng khoảng 1/2~2/3 nguyên tác: Làm cho câu chặt chẽ hơn, đoạn văn đặc hơn, nhưng tuyệt đối không nén đến mức chỉ còn lại vài dòng Tuyến chính. Thà dài hơn một chút cũng không được để mất những việc đã trải qua.

[Quy tắc sắt về Thời gian và Địa điểm]
- Bắt buộc phải giữ nguyên [Đánh dấu thời gian]: Mỗi sự kiện đều phải mang theo chú thích [Thời gian] gốc của nó, không được xóa hoặc gộp đánh dấu thời gian; Không được viết lại các mục có mang [Thời gian] thành chuỗi tường thuật không có đánh dấu thời gian.
- Trình tự trước sau của sự kiện, chuỗi nhân quả xuyên thời gian không được lộn xộn, không được nhảy đoạn.
- Nếu nguyên tác có chứa trường [Địa điểm] hoặc đoạn đánh dấu <<<LOCATIONS>>>…<<<LOCATIONS_END>>>, bắt buộc phải giữ nguyên chuỗi địa điểm này, không được xóa hoặc viết lại tên địa danh cốt lõi.

[Các mục có thể xóa (Yên tâm mạnh tay vứt bỏ)]
- Các vấn đề chưa giải quyết: Chỉ cần giữ lại vài mục "Đang khẩn cấp nhất, vẫn đang thúc đẩy hiện tại"; Những vấn đề chưa giải quyết cũ, đã lật sang trang có thể trực tiếp xóa bỏ (Vòng tiếp theo sẽ ghi lại một đợt mới).
- Phục bút dài hạn, bí ẩn chưa hé lộ, lời hứa chưa thực hiện, manh mối lót đường, tuyến ngầm xuyên suốt các tầng —— Có thể dọn dẹp số lượng lớn, không cần giữ nguyên.
- Bầu không khí môi trường, tạo cảm xúc, sinh hoạt vụn vặt, chuyển tiếp kết nối —— Xóa trực tiếp.

[Quy tắc sắt về Định dạng (Hoàn toàn giống với tự động viết hồ sơ, khi nén cũng bắt buộc phải tuân thủ, cấm phá vỡ định dạng hiện có)]:
1. Thay đổi trạng thái quan trọng (states) bắt buộc phải giữ định dạng chia ô cố định, dùng | phân cách các khía cạnh khác nhau, một ô một giá trị, cấm trộn lẫn nhiều khía cạnh vào cùng một giá trị. Mỗi dòng = một đối tượng (Nhân vật chính/Môi trường/Nhân vật nào đó), phân cách bằng dấu xuống dòng:
   - Dòng nhân vật chính: Nhân vật chính: Danh tính [...] | Cơ thể [...] | Tinh thần [...] | Địa chỉ [...] | Tài sản [...] | Vẻ ngoài [...] | Hảo cảm [...] | Ghi chú [...]
   - Dòng môi trường: Môi trường: Bố cục [...] | Nhiệt độ thời tiết [...]
   - Các dòng nhân vật khác: Tên nhân vật: Cơ thể [...] | Địa chỉ [...] | Tài sản [...] | Vẻ ngoài [...] | Hảo cảm [...] | Ghi chú [...]
   Khi nén hãy giữ cho các ô và khía cạnh này không bị mất; Đã thay đổi thì mới cập nhật ô đó, chưa thay đổi thì giữ nguyên hoặc để trống, đừng dùng "Không có" để điền đầy tất cả các ô.
2. Quy tắc sắt về chỉ số Hảo cảm (Bắt buộc phải tuân thủ nghiêm ngặt, khi nén không được phá vỡ):
   - Hảo cảm bắt buộc phải được viết riêng bằng con số (ví dụ "Hảo cảm với nhân vật chính 62" hoặc "Hảo cảm với nhân vật chính -90"), cấm dùng các cách diễn đạt mơ hồ như "Hảo cảm tăng mạnh", "Hảo cảm giảm xuống".
   - Hảo cảm âm bắt buộc phải mang theo dấu trừ (-), ví dụ "Hảo cảm với nhân vật chính -90", tuyệt đối không được viết thành giá trị dương hoặc tuyệt đối; Khi tổng hợp kiểu ghi đè, hảo cảm âm đã có bắt buộc phải giữ nguyên dấu trừ như cũ.
   - Việc nén chỉ là tinh gọn cách diễn đạt, không được tự ý thay đổi bản thân chỉ số hảo cảm; Con số bắt buộc phải tiếp nối liền mạch với trước khi nén.
3. Giữ nguyên ngữ nghĩa kiểu ghi đè và ghi thêm: Tuyến chính/Tuyến phụ là kiểu ghi thêm (Giữ lại toàn bộ tiến triển đã xảy ra); Thay đổi trạng thái quan trọng/Các vấn đề chưa giải quyết là kiểu ghi đè (Giữ lại toàn cảnh mới nhất hiện tại vẫn còn hiệu lực).
4. Nếu cuối dòng trạng thái của nguyên tác có mang [Đánh dấu thời gian] (ví dụ [Ngày thứ 3 Chạng vạng]), bắt buộc phải giữ lại đánh dấu thời gian đó để chú thích thời gian thay đổi gần nhất của trạng thái.

Vui lòng xuất ra nghiêm ngặt theo các phân đoạn dưới đây, mỗi đoạn bắt đầu bằng [Tiêu đề], tiêu đề giữ nguyên, không được thay đổi chữ của tiêu đề:
- [Tuyến chính]... (Mỗi sự kiện vẫn bắt đầu bằng [Thời gian], một sự kiện một dòng)
- [Tuyến phụ]... (Mỗi sự kiện vẫn bắt đầu bằng [Thời gian], một sự kiện một dòng)
- [Thay đổi trạng thái quan trọng]... (Mỗi sự kiện vẫn bắt đầu bằng [Thời gian], một sự kiện một dòng; Và giữ nguyên các dòng trạng thái của từng nhân vật/nhân vật chính/môi trường theo định dạng chia ô ở trên)
- [Các vấn đề chưa giải quyết]... (Mỗi sự kiện vẫn bắt đầu bằng [Thời gian], một sự kiện một dòng)
- Các mục theo dõi tùy chỉnh khác: Xuất ra đoạn [Tiêu đề] nguyên dạng theo tiêu đề gốc.
- [Địa điểm] (Nếu nguyên tác tồn tại thì xuất ra nguyên dạng, dùng <<<LOCATIONS>>>…<<<LOCATIONS_END>>> bọc lại, mỗi dòng một tên địa danh cốt lõi)
Các phân đoạn không có nội dung có thể bỏ qua. Chỉ xuất ra văn bản sau khi nén, không cần bất kỳ lời giải thích nào.
[Quy tắc sắt khi xử lý nội dung nhạy cảm (Bắt buộc tuân thủ nghiêm ngặt, thà xuất ra dài cũng không được làm mất/cắt cụt)]:
- Nếu nguyên tác chứa nội dung bạo lực, tương tác người lớn, sỉ nhục, cưỡng ép, thương tích, máu me, quan hệ bệnh hoạn, thay đổi trạng thái sinh lý/tinh thần v.v., [Bắt buộc phải giữ nguyên vẹn sự kiện đó], không được vì mức độ nội dung mà bỏ qua, cắt xén, làm mờ, khái quát hóa, càng không được chỉ giữ lại một nửa phía sau hoặc chỉ đưa ra tóm tắt của mục đó.
- Cấm "Cắt cụt thành chỉ giữ lại phần đuôi" hoặc "Chỉ xuất ra phần không đau không ngứa" đối với các sự kiện có chứa từ nhạy cảm —— Mỗi sự kiện hoặc là giữ nguyên vẹn (cho phép dùng từ ngữ khách quan trung lập, nhưng không được làm mất sự thật quan trọng), hoặc là nói rõ lý do sự kiện đó bị bỏ qua, tuyệt đối không được làm mất nội dung mà không có cảnh báo.
- Bạn không phải đang sáng tác cốt truyện, chỉ đang thực hiện việc lưu trữ nén khách quan cho các cốt truyện đã xảy ra, do đó không tồn tại rủi ro về mức độ nội dung; Các mục càng nhạy cảm, càng liên quan đến trạng thái/quan hệ của nhiều chủ thể/đe dọa hứa hẹn/cưỡng ép/thân mật, thì càng bắt buộc phải nén và giữ lại một cách chân thực trọn vẹn, đảm bảo việc viết tiếp sau này có thể khớp được.
- Nếu vì bất kỳ lý do gì không thể giữ nguyên vẹn, thà xuất ra dài hơn 2/3 cũng không được tồn tại đầu ra kiểu "Cụt đuôi, mất đầu, chỉ giữ lại phần kết". Vui lòng đếm lại một lượt, đảm bảo mỗi trường xuất ra đều hoàn chỉnh hơn đầu vào, không thiếu sự kiện.`;

  const res = await cdWithTimeout(cdApiComplete([
    { role: 'system', content: (function () { const _jb = (typeof JAILBREAK !== "undefined" && JAILBREAK) ? (Array.isArray(JAILBREAK) ? JAILBREAK.join("\n") : String(JAILBREAK)) : ""; return (_jb ? _jb + "\n\n" : "") + COMPRESS_PROMPT; })() },
    { role: 'user', content: joinText },
  ], s), 180000, 'Nén tự động');

  // ★ DIAG: Đánh chặn dữ liệu thực tế của từng khâu nén, dùng để định vị "Nén hoàn tất nhưng hồ sơ không đổi"
  cdAddLog('info', '[COMPRESS-DIAG] Phản hồi gốc của AI', { hasText: !!(res && res.text), textLen: (res && res.text) ? res.text.length : -1, textHead: (res && res.text) ? String(res.text).slice(0, 200) : '' });

  if (res && res.text && res.text.trim()) {
    const out = cdParseCompressedBlocks(res.text, labels);
    // ★ DIAG: Phân tích kết quả theo từng trường
    cdAddLog('info', '[COMPRESS-DIAG] Kết quả phân tích out', (function () { const o = {}; for (const f of fields) o[labels[f]] = (out[f] && String(out[f]).length) || 0; return o; })());
    let replacedAny = false;
    for (const f of fields) {
      if (out[f] && typeof out[f] === 'string' && out[f].length) {
        cdAddLog('info', `Nén tự động ${labels[f]}: ${String(archive[f] || '').length}→${out[f].length} chữ`);
        archive[f] = out[f];
        replacedAny = true;
      }
    }
    if (!replacedAny) {
      // Có phản hồi nhưng không phân tích ra được trường nào: Báo lỗi rõ ràng, không giả vờ thành công nữa
      throw new Error('Nén thất bại: AI đã trả về nội dung nhưng không thể phân tích theo các tiêu đề như [Tuyến chính], vui lòng kiểm tra định dạng trả về (Xem log COMPRESS-DIAG)');
    }
    cdAddLog('info', '[COMPRESS-DIAG] Điền ngược thành công, đã thay thế ' + replacedAny + ' trường', { mainline: String(archive.mainline || '').length, sideline: String(archive.sideline || '').length, states: String(archive.states || '').length, unresolved: String(archive.unresolved || '').length });
    // Mục theo dõi tùy chỉnh: Nếu AI xuất ra bản gộp theo tiêu đề tùy chỉnh, cố gắng điền ngược (Đơn giản hóa thành: Giữ nguyên giá trị cũ + Gập các mục cũ vượt hạn mức)
  } else {
    // Không có văn bản trả về: Báo lỗi rõ ràng
    throw new Error('Nén thất bại: AI không trả về nội dung (text bị trống), vui lòng kiểm tra xem API AI có khả dụng không');
  }

  // ★ Mục theo dõi cốt truyện tùy chỉnh: Gập các mục cũ vượt hạn mức vào Tuyến chính rồi cắt bỏ (Giữ nguyên cả hai chế độ)
  {
    const cpCustomFields = Array.isArray(s.customFields) ? s.customFields.filter(f => f && f.key && f.label) : [];
    const cpCustomMap = archive.custom && typeof archive.custom === 'object' ? archive.custom : {};
    const MAX_CUSTOM = Math.max(20, s.autoCompressThreshold ? s.autoCompressThreshold * 2 : 60);
    for (const def of cpCustomFields) {
      const arr = Array.isArray(cpCustomMap[def.key]) ? cpCustomMap[def.key] : [];
      if (arr.length <= MAX_CUSTOM) continue;
      const excess = arr.slice(0, arr.length - MAX_CUSTOM);
      const kept = arr.slice(arr.length - MAX_CUSTOM);
      if (!excess.length) continue;
      const t0 = excess[0].time || '';
      const t1 = excess[excess.length - 1].time || '';
      const range = (t0 && t1 && t0 !== t1) ? `${t0}～${t1}` : (t0 || t1);
      const foldedTime = range ? `${def.label} thời kỳ đầu(${range})` : `${def.label} thời kỳ đầu`;
      const foldedDesc = excess.map(it => it.time ? `${it.time}：${it.desc}` : it.desc).join('；');
      if (foldedDesc) {
        const oldMain = archive.mainline || '';
        const append = `\n【${foldedTime}】${foldedDesc}`;
        if (oldMain.length + append.length < 8000 || !oldMain) {
          archive.mainline = oldMain ? oldMain.trimEnd() + append : append.trim();
        }
      }
      cpCustomMap[def.key] = kept;
      cdAddLog('info', `Nén tự động mục theo dõi tùy chỉnh [${def.label}]: ${arr.length}→${kept.length} mục (Các mục cũ đã được gập vào Tuyến chính)`);
    }
  }

  // Ghi lại đường cơ sở (Dùng để phán đoán mức tăng thêm cho lần sau)
  if (isAuto) {
    const mode = s.autoCompressMode || 'count';
    if (mode === 'size') {
      data._lastCompressSize = cdArchiveSize(archive);
    } else {
      data._lastCompressEntryCount = cdCountArchiveEntries(archive);
    }
  }
}

/* ============================== Công cụ vector hóa ============================== */

/**
 * Lấy vector nhúng của văn bản
 * Chỉ đọc từ API nhúng được cấu hình độc lập (vectorEmbedding), không hạ cấp xuống API chính
 */
async function cdGetEmbedding(text) {
  if (!text || !text.trim()) return null;
  const s = cdGetSettings();
  const ve = s.vectorEmbedding;
  // ── Bảo vệ chống quá giờ: Bất kỳ nguồn nhúng nào cũng phải trả về trong vòng maxMs, nếu không sẽ hạ cấp, tuyệt đối không làm treo giao diện ──
  const _withTimeout = (promiseFn, maxMs) => {
    return new Promise((resolve) => {
      let done = false;
      const timer = setTimeout(() => { if (!done) { done = true; resolve(null); } }, maxMs);
      Promise.resolve().then(() => promiseFn()).then((v) => {
        if (!done) { done = true; clearTimeout(timer); resolve(v); }
      }).catch(() => { if (!done) { done = true; clearTimeout(timer); resolve(null); } });
    });
  };
  const T = 5000; // Thời gian chờ tối đa cho một lần nhúng là 5 giây
  if (!ve || !ve.source || ve.source === 'tavern') {
    // Chưa cấu hình API nhúng hoặc chọn theo SillyTavern nhưng không có cấu hình → Thử nhúng ST (Bảo vệ chống quá giờ)
    if (ve?.source === 'tavern' || !ve?.source) {
      try {
        const ctx = SillyTavern.getContext();
        if (ctx && typeof ctx.getEmbedding === 'function') {
          const emb = await _withTimeout(() => ctx.getEmbedding(text), T);
          if (Array.isArray(emb)) return emb;
        }
        if (typeof SillyTavern.getContext === 'function') {
          const stCtx = SillyTavern.getContext();
          if (stCtx?.textgenerationwebui?.is_connected && typeof stCtx.textgenerationwebui.do_embedding === 'function') {
            const emb2 = await _withTimeout(() => stCtx.textgenerationwebui.do_embedding(text), T);
            if (Array.isArray(emb2)) return emb2;
          }
        }
      } catch (e) {}
    }
    return null;
  }
  const source = ve.source;
  try {
    if (source === 'openai') {
      const url = (ve.url || 'https://api.openai.com/v1').replace(/\/+$/, '');
      const key = ve.key;
      if (!key) return null;
      const model = ve.model || 'text-embedding-ada-002';
      const body = { input: text, model };
      const res = await _withTimeout(() => fetch(`${url}/embeddings`, {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${key}`, 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      }), T);
      if (!res) return null;
      if (!res.ok) return null;
      const data = await _withTimeout(() => res.json(), T);
      if (!data) return null;
      return data?.data?.[0]?.embedding || null;
    }
    if (source === 'gemini') {
      const key = ve.key;
      if (!key) return null;
      const body = { model: 'models/embedding-001', content: { parts: [{ text }] } };
      const res = await _withTimeout(() => fetch(`https://generativelanguage.googleapis.com/v1beta/models/embedding-001:embedContent?key=${encodeURIComponent(key)}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      }), T);
      if (!res) return null;
      if (!res.ok) return null;
      const data = await _withTimeout(() => res.json(), T);
      if (!data) return null;
      return data?.embedding?.values || null;
    }
    return null;
  } catch (e) {
    cdLog('cdGetEmbedding thất bại:', e && e.message);
    return null;
  }
}

/** Tính độ tương đồng cosin của hai vector */
function cdCosineSimilarity(a, b) {
  if (!a || !b || a.length !== b.length) return 0;
  let dot = 0, na = 0, nb = 0;
  for (let i = 0; i < a.length; i++) {
    dot += a[i] * b[i];
    na += a[i] * a[i];
    nb += b[i] * b[i];
  }
  const denom = Math.sqrt(na) * Math.sqrt(nb);
  return denom === 0 ? 0 : dot / denom;
}

/**
 * Vector hóa các mục sự kiện trong hồ sơ cốt truyện và lưu vào data.archiveVectors
 * Chỉ xử lý các mục mới thêm (chưa được vector hóa)
 */
async function cdVectorizeArchive(data) {
  const archive = data.archive;
  if (!archive) return;
  if (!Array.isArray(data.archiveVectors)) data.archiveVectors = [];
  
  // Thu thập dấu vân tay văn bản của các vector đã có, dùng để loại bỏ trùng lặp
  const existingTexts = new Set(data.archiveVectors.map(v => v.text?.trim()));
  
  // Trích xuất toàn bộ sự kiện [Thời gian] từ bốn trường
  const entries = [];
  for (const category of ['mainline', 'sideline', 'states', 'unresolved']) {
    const text = archive[category] || '';
    // Cắt theo [Thời gian]
    const parts = text.split(/(?=【)/);
    for (const part of parts) {
      const trimmed = part.trim();
      if (trimmed && !existingTexts.has(trimmed)) {
        entries.push({ text: trimmed, category });
      }
    }
  }
  // ★ Mục theo dõi cốt truyện tùy chỉnh cũng được đưa vào thư viện vector (Mỗi mục độc lập, category dùng tên trường)
  const vecCustomFields = Array.isArray(cdGetSettings().customFields) ? cdGetSettings().customFields : [];
  const vecCustomMap = (archive.custom && typeof archive.custom === 'object') ? archive.custom : {};
  for (const def of vecCustomFields) {
    if (!def || !def.key || !def.label) continue;
    const arr = Array.isArray(vecCustomMap[def.key]) ? vecCustomMap[def.key] : [];
    for (const it of arr) {
      if (!it || !it.desc) continue;
      const t = (it.time ? `【${it.time}】${it.desc}` : it.desc).trim();
      if (t && !existingTexts.has(t)) entries.push({ text: t, category: def.label });
    }
  }
  
  if (entries.length === 0) return;
  
  cdLog('cdVectorizeArchive: Chuẩn bị vector hóa', entries.length, 'sự kiện mới');
  
  // Vector hóa từng mục một (Xử lý song song hàng loạt có thể vượt quá giới hạn token, xử lý nối tiếp)
  for (const entry of entries) {
    const vector = await cdGetEmbedding(entry.text);
    if (vector) {
      data.archiveVectors.push({
        id: 'arc_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8),
        text: entry.text,
        category: entry.category,
        vector: vector,
        time: new Date().toISOString(),
      });
    }
    // Trì hoãn một chút để tránh API giới hạn luồng
    await new Promise(r => setTimeout(r, 100));
  }
  

  cdLog('cdVectorizeArchive: Hoàn tất, tổng cộng', data.archiveVectors.length, 'vector');
}

/**
 * Vector hóa các mục nhật ký nhân vật và lưu vào data.diaryVectors
 * Chỉ xử lý các mục mới thêm (chưa được vector hóa), mỗi mục mang tên nhân vật role dùng để lọc theo nhân vật
 */
async function cdVectorizeDiary(data) {
  const diaries = data.diaries;
  if (!diaries || typeof diaries !== 'object') return;
  if (!Array.isArray(data.diaryVectors)) data.diaryVectors = [];

  // Thu thập dấu vân tay văn bản của các vector đã có, dùng để loại bỏ trùng lặp
  const existingTexts = new Set(data.diaryVectors.map(v => v.text?.trim()));

  const entries = [];
  for (const [name, list] of Object.entries(diaries)) {
    if (!Array.isArray(list)) continue;
    for (const e of list) {
      if (!e || !e.entry || !e.entry.trim()) continue;
      const role = name;
      const dateStr = e.date ? 'Ngày thứ ' + e.date : (e.turn !== undefined ? 'Tầng ' + e.turn : '');
      const text = `[Nhật ký của ${role} · ${dateStr || 'Thời gian không xác định'}]${e.entry.trim()}`;
      const trimmed = text.trim();
      if (trimmed && !existingTexts.has(trimmed)) {
        entries.push({ role, text: trimmed });
      }
    }
  }

  if (entries.length === 0) return;

  cdLog('cdVectorizeDiary: Chuẩn bị vector hóa', entries.length, 'nhật ký mới');

  // Vector hóa từng mục một (Nối tiếp, tránh giới hạn luồng)
  for (const entry of entries) {
    const vector = await cdGetEmbedding(entry.text);
    if (vector) {
      data.diaryVectors.push({
        id: 'dia_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8),
        role: entry.role,
        text: entry.text,
        vector: vector,
        time: new Date().toISOString(),
      });
    }
    await new Promise(r => setTimeout(r, 100));
  }

  cdLog('cdVectorizeDiary: Hoàn tất, tổng cộng', data.diaryVectors.length, 'vector');
}


/**
 * Dùng văn bản truy vấn để tìm N mục giống nhất trong thư viện vector
 * @param {string} queryText - Văn bản truy vấn
 * @param {Array} vectors - Thư viện vector data.archiveVectors
 * @param {number} topK - Số mục trả về
 * @param {number} threshold - Ngưỡng tương đồng
 * @returns {Array} Kết quả sau khi sắp xếp [{ text, category, score }]
 */
async function cdSearchVectors(queryText, vectors, topK = 5, threshold = 0.6) {
  if (!queryText || !Array.isArray(vectors) || vectors.length === 0) return [];
  
  // Hạ cấp xuống khớp từ khóa đơn giản (Khi không có bất kỳ vector nào)
  if (!vectors[0]?.vector) {
    const q = queryText.toLowerCase();
    const keywords = q.split(/\s+/).filter(w => w.length > 1);
    return vectors
      .map(v => {
        const t = (v.text || '').toLowerCase();
        const score = keywords.reduce((sum, kw) => sum + (t.includes(kw) ? 1 : 0), 0) / Math.max(keywords.length, 1);
        return { ...v, score };
      })
      .filter(v => v.score > 0)
      .sort((a, b) => b.score - a.score)
      .slice(0, topK);
  }
  
  // ★ Có vector thực sự: Trước tiên thực hiện nhúng cho văn bản truy vấn, sau đó tính độ tương đồng cosin với các vector ứng viên (Truy hồi nhiều mục, chứ không chỉ lấy mục mới nhất)
  const qVec = await cdGetEmbedding(String(queryText || '').slice(0, 3000)).catch(() => null);
  if (Array.isArray(qVec) && qVec.length) {
    const dim = (vectors[0].vector || []).length;
    if (dim > 0 && qVec.length === dim) {
      // ★ Phương án B: Khi thư viện vector lớn gây giật lag, bật "Truy xuất tốc độ cao" chỉ tính cosin với N mục gần nhất (Mặc định tắt = Truy xuất toàn bộ không bỏ sót ký ức cũ)
      let _vecS = null;
      try { _vecS = (typeof cdGetSettings === 'function') ? cdGetSettings() : null; } catch (_e) {}
      const _fast = !!(_vecS && _vecS.vectorFastMode === true);
      const _FAST_POOL = Math.max(50, parseInt((_vecS && _vecS.vectorFastPool) || 1500, 10) || 1500);
      const pool = (_fast && vectors.length > _FAST_POOL) ? vectors.slice(-_FAST_POOL) : vectors;
      if (_fast && vectors.length > _FAST_POOL && typeof cdLog === 'function') {
        cdLog('cdSearchVectors: Đã bật truy xuất tốc độ cao, chỉ tính cosin cho', _FAST_POOL, 'mục gần nhất (Tổng cộng', vectors.length, 'mục)');
      }
      return pool
        .map(v => {
          const vec = v.vector;
          if (!Array.isArray(vec) || vec.length !== dim) return { ...v, score: 0 };
          return { ...v, score: cdCosineSimilarity(qVec, vec) };
        })
        .filter(v => v.score >= (threshold || 0))
        .sort((a, b) => b.score - a.score)
        .slice(0, topK);
    }
  }
  
  // ★ Nhúng truy vấn thất bại hoặc kích thước không khớp → Hạ cấp xuống khớp từ khóa
  const q = queryText.toLowerCase();
  const keywords = q.split(/\s+/).filter(w => w.length > 1);
  return vectors
    .map(v => {
      const t = (v.text || '').toLowerCase();
      const score = keywords.reduce((sum, kw) => sum + (t.includes(kw) ? 1 : 0), 0) / Math.max(keywords.length, 1);
      return { ...v, score };
    })
    .filter(v => v.score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, topK);
}

/* ============================== Kiểm tra cập nhật ============================== */

/** Kiểm tra xem trên GitHub có phiên bản mới không, nếu có thì thông báo bằng toastr */
async function cdCheckForUpdates(silent = true) {
  try {
    const resp = await fetch(REPO_URL);
    if (!resp.ok) return;
    const data = await resp.json();
    const remoteVer = (data.tag_name || data.name || '').replace(/^v/, '').trim();
    const localVer = PLUGIN_VERSION;
    // ★ So sánh phiên bản ngữ nghĩa: Cắt nhỏ các số để so sánh từng đoạn, tránh việc bị báo nhầm "Có phiên bản mới" khi phiên bản cục bộ cao hơn (ví dụ: Cục bộ 2.9.7 > Từ xa 2.9.6)
    const cmpVer = (a, b) => {
      const pa = String(a || '0').split('.').map(n => parseInt(n, 10) || 0);
      const pb = String(b || '0').split('.').map(n => parseInt(n, 10) || 0);
      const len = Math.max(pa.length, pb.length);
      for (let i = 0; i < len; i++) {
        const x = pa[i] || 0, y = pb[i] || 0;
        if (x !== y) return x > y ? 1 : -1;
      }
      return 0;
    };
    if (remoteVer && cmpVer(remoteVer, localVer) > 0) {
      const msg = `Phát hiện phiên bản mới v${remoteVer} (Hiện tại v${localVer}), vui lòng chạy git pull để cập nhật`;
      toastr.warning(msg, 'Nhật ký nhân vật', { timeOut: 10000, extendedTimeOut: 15000 });
      cdLog('[Cập nhật] ' + msg);
    }
  } catch (e) {
    if (!silent) cdWarn('Kiểm tra cập nhật thất bại', e);
  }
}

/* ============================== Phân tích JSON mạnh mẽ ============================== */

/** Escape các ký tự không hợp lệ như xuống dòng/tab bên trong chuỗi JSON */
function sanitizeJsonString(s) {
  let out = '';
  let inStr3 = false;
  let escaped3 = false;
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (inStr3) {
      if (escaped3) { out += ch; escaped3 = false; continue; }
      if (ch === '\\') { out += ch; escaped3 = true; continue; }
      if (ch === '"') { out += ch; inStr3 = false; continue; }
      if (ch === '\n') { out += '\\n'; continue; }
      if (ch === '\r') { out += '\\r'; continue; }
      if (ch === '\t') { out += '\\t'; continue; }
      out += ch;
    } else {
      if (ch === '"') { inStr3 = true; out += ch; continue; }
      out += ch;
    }
  }
  return out;
}

/** Quét từ startIdx để trích xuất toàn bộ các đối tượng cấp cao nhất { ... } hoàn chỉnh */
function scanObjects(t, startIdx) {
  const results = [];
  let depth = 0;
  let objStart = -1;
  let inStr2 = false;
  let escaped2 = false;
  for (let i = startIdx; i < t.length; i++) {
    const ch = t[i];
    if (inStr2) {
      if (escaped2) { escaped2 = false; continue; }
      if (ch === '\\') { escaped2 = true; continue; }
      if (ch === '"') { inStr2 = false; }
      continue;
    }
    if (ch === '"') { inStr2 = true; continue; }
    if (ch === '{') {
      if (depth === 0) objStart = i;
      depth++;
    } else if (ch === '}') {
      depth--;
      if (depth === 0 && objStart >= 0) {
        try { results.push(JSON.parse(t.slice(objStart, i + 1))); } catch (e) { /* skip bad */ }
        objStart = -1;
      }
    }
  }
  return results;
}

function parseDiaryJson(text) {
  let t = String(text || '').trim();
  t = t.replace(/```json/gi, '').replace(/```/g, '');
  if (!t.includes('"npcs"')) t = '{"npcs":[' + t;
  t = sanitizeJsonString(t);
  try { const obj = JSON.parse(t); if (Array.isArray(obj.npcs) && obj.npcs.length) return obj.npcs; } catch (_) {}
  const key = t.indexOf('"npcs"');
  const arrIdx = t.indexOf('[', key >= 0 ? key : 0);
  const npcs = scanObjects(t, arrIdx >= 0 ? arrIdx + 1 : 0).filter(o => o && o.name);
  if (npcs.length) return npcs;
  throw new Error('Phân tích JSON Nhật ký thất bại, nguyên văn: ' + String(text).slice(0, 150));
}

function parseRelationJson(text) {
  let t = String(text || '').trim();
  t = t.replace(/```json/gi, '').replace(/```/g, '');
  if (!t.includes('"relations"')) t = '{"relations":[' + t;
  t = sanitizeJsonString(t);
  try { const obj = JSON.parse(t); if (Array.isArray(obj.relations)) return obj.relations; } catch (_) {}
  const key = t.indexOf('"relations"');
  const arrIdx = t.indexOf('[', key >= 0 ? key : 0);
  const rels = scanObjects(t, arrIdx >= 0 ? arrIdx + 1 : 0).filter(o => o && o.from && o.to);
  if (rels.length) return rels;
  throw new Error('Phân tích JSON Quan hệ thất bại, nguyên văn: ' + String(text).slice(0, 150));
}// ============================================================
// Nhật ký nhân vật Plugin v2.0.0 — Gộp dữ liệu & Đồng bộ Worldbook
// Đường dẫn: SillyTavern/extensions/character-diary/data.js
// ============================================================
'use strict';

/* ============================== Đọc ghi settings ============================== */
function cdGetSettings() {
  const { extSettings } = _cdGetStCtx();
  if (extSettings) {
    if (!extSettings[PLUGIN_ID]) {
      extSettings[PLUGIN_ID] = Object.assign({}, DEFAULT_SETTINGS);
    } else {
      // Cài đặt cũ bổ sung giá trị mặc định cho các trường mới thêm (Giữ nguyên các giá trị đã lưu)
      extSettings[PLUGIN_ID] = Object.assign({}, DEFAULT_SETTINGS, extSettings[PLUGIN_ID]);
    }

    return extSettings[PLUGIN_ID];
  }
  // dự phòng sang global
  if (typeof extension_settings !== 'undefined') {
    if (!extension_settings[PLUGIN_ID]) extension_settings[PLUGIN_ID] = Object.assign({}, DEFAULT_SETTINGS);
    return extension_settings[PLUGIN_ID];
  }
  // giải pháp cuối cùng: trả về defaults
  cdWarn('extension_settings không khả dụng, trả về cài đặt mặc định');
  return Object.assign({}, DEFAULT_SETTINGS);
}

function cdSaveSettings(patch) {
  Object.assign(cdGetSettings(), patch);
  // Trong ST saveSettingsDebounced là phương thức trên đối tượng ngữ cảnh getContext(), không phải biến toàn cục (Gọi trần sẽ bị ReferenceError)
  try {
    const ctx = SillyTavern.getContext();
    const canCtx = ctx && typeof ctx.saveSettingsDebounced === 'function';
    const canGlob = typeof saveSettingsDebounced === 'function';
    // Đọc lại để xác nhận xem đã thực sự ghi vào đối tượng cài đặt chưa
    const verify = Object.keys(patch || {}).reduce((o, k) => { o[k] = cdGetSettings()[k]; return o; }, {});
    cdAddLog('info', '[Cài đặt] Lưu', { patchKeys: Object.keys(patch || {}), ctx_có_thể_bền_vững: !!canCtx, Toàn_cục_có_thể_bền_vững: !!canGlob, Đọc_lại_sau_khi_lưu: verify });
    if (canCtx) {
      ctx.saveSettingsDebounced();
    } else if (canGlob) {
      saveSettingsDebounced();
    } else {
      cdWarn('saveSettingsDebounced không khả dụng, cài đặt chỉ có hiệu lực trong bộ nhớ');
    }
  } catch (e) {
    cdWarn('cdSaveSettings lưu thất bại', e);
  }
}

/* ============================== Dữ liệu ván này (chat variables) ============================== */
/* ===== Thư viện yêu thích toàn cục (Lưu trữ bền vững xuyên suốt các cuộc trò chuyện) ===== */
const CD_FAV_KEY = 'cdGlobalFavs';
function cdGetGlobalFavs() {
  try {
    const raw = localStorage.getItem(CD_FAV_KEY);
    const arr = raw ? JSON.parse(raw) : [];
    return Array.isArray(arr) ? arr : [];
  } catch (e) { return []; }
}
function cdSaveGlobalFavs(arr) {
  try { localStorage.setItem(CD_FAV_KEY, JSON.stringify(arr)); } catch (e) {}
}
function cdFavKey(name, e) {
  return name + '|' + (e.date || '') + '|' + String(e.entry || '').slice(0, 60);
}
function cdFavSnapshot(name, e) {
  return { __key: cdFavKey(name, e), name: name, date: e.date || '', turn: e.turn || '', mood: e.mood || '', attitude: e.attitude_to_user || '', entry: e.entry || '', secret: e.secret || '', key_events: Array.isArray(e.key_events) ? e.key_events.slice() : [], ts: Date.now() };
}
function cdSyncGlobalFav(name, e, fav) {
  const arr = cdGetGlobalFavs();
  const key = cdFavKey(name, e);
  const i = arr.findIndex(function (x) { return x.__key === key; });
  if (fav) {
    if (i === -1) arr.unshift(cdFavSnapshot(name, e));
  } else {
    if (i !== -1) arr.splice(i, 1);
  }
  cdSaveGlobalFavs(arr);
}
function cdFavMigrate(data) {
  if (!data || !data.diaries) return;
  const arr = cdGetGlobalFavs();
  let changed = false;
  for (const name of Object.keys(data.diaries)) {
    const list = data.diaries[name];
    if (!Array.isArray(list)) continue;
    for (const e of list) {
      if (e && e.fav) {
        const key = cdFavKey(name, e);
        if (!arr.some(function (x) { return x.__key === key; })) {
          arr.push(cdFavSnapshot(name, e));
          changed = true;
        }
      }
    }
  }
  if (changed) cdSaveGlobalFavs(arr);
}
/** ===== Chống mất dữ liệu: Sao lưu độc lập (localStorage, không đi theo cuộc trò chuyện) ===== */
const CD_BACKUP_KEY = 'cd-data-backups';
function cdGetBackups() {
  try { const raw = localStorage.getItem(CD_BACKUP_KEY); const arr = raw ? JSON.parse(raw) : []; return Array.isArray(arr) ? arr : []; } catch (e) { return []; }
}
function cdSaveBackups(arr) { try { localStorage.setItem(CD_BACKUP_KEY, JSON.stringify(arr)); } catch (e) {} }
function cdDiaryTotal(data) {
  let n = 0; const d = (data && data.diaries) || {};
  Object.keys(d).forEach(function(k){ const l=d[k]; if(Array.isArray(l)) n += l.length; });
  return n;
}
function cdPushBackup(data, label) {
  try {
    const arr = cdGetBackups();
    arr.unshift({
      time: Date.now(),
      label: label || 'Sao lưu tự động',
      diaryCount: cdDiaryTotal(data),
      diaries: (data && data.diaries) || {},
      relations: (data && data.relations) || {},
      archive: (data && data.archive) || {},
      liveTableData: (data && data.liveTableData) || [],
      liveTableSnapshots: (data && data.liveTableSnapshots) || [],
      cards: (data && data.cards) || [],
    });
    if (arr.length > 10) arr.splice(10);
    cdSaveBackups(arr);
  } catch (e) {}
}
async function cdGetData() {
  try {
    // ★★ Đọc luồng kép: Ưu tiên chatMetadata, tiếp theo là Chat Variables (Tương thích phân cấp dữ liệu v8/Bản cũ)
    const PLUGIN = PLUGIN_ID;
    const empty = emptyData();
    let stored = null;

    // Luồng ① chatMetadata (Vị trí chuẩn v2.5.x, và tự động di chuyển từ vị trí cấp cao nhất cũ)
    try {
      const ctx = SillyTavern.getContext();
      if (ctx && ctx.chatMetadata) {
        const extStore = (ctx.chatMetadata.extensions && ctx.chatMetadata.extensions[PLUGIN]) || null;
        const legacyStore = ctx.chatMetadata[PLUGIN] || null;
        let s = extStore || legacyStore;
        if (legacyStore && !extStore) {
          if (!ctx.chatMetadata.extensions || typeof ctx.chatMetadata.extensions !== 'object') ctx.chatMetadata.extensions = {};
          ctx.chatMetadata.extensions[PLUGIN] = legacyStore;
          s = legacyStore;
        }
        if (s && typeof s === 'object') { stored = s; }
      }
    } catch (_c) { /* Im lặng khi chatMetadata không khả dụng */ }

    // Luồng ② Chat Variables (Lưu trữ insertOrAssignVariables / getVariables)
    if (!stored) {
      try {
        const cv = (await getVariables({ type: 'chat' })) || {};
        if (cv && cv[PLUGIN] && typeof cv[PLUGIN] === 'object') stored = cv[PLUGIN];
      } catch (_v) { /* Im lặng khi variables không khả dụng */ }
    }

    // Sửa chữa phân mảnh dữ liệu/đường cơ sở (Chỉ thực thi khi đọc được dữ liệu thực)
    if (stored) {
      const result = Object.assign(empty, stored);
      const chat = _cdGetChat();
      if (chat.length > 0) {
        if (result.lastFloor > chat.length - 1) {
          cdLog('cdGetData: Sửa lỗi lastFloor', {old: result.lastFloor, new: chat.length - 1});
          result.lastFloor = chat.length - 1;
          // ★ Phương án Giáp: Sau khi load game/tầng bị thu hẹp thì con trỏ bị vượt lên trước (Cuộc trò chuyện gốc chỉ còn N mục gần nhất), đồng bộ làm trống processedFloors, tránh việc message_id cao còn sót lại khiến cuộc trò chuyện mới "hiển thị đã tóm tắt toàn bộ các tầng" và không tự động tóm tắt nữa.
          if (Array.isArray(result.processedFloors)) result.processedFloors = [];
          try { if (typeof cdLog==='function') cdLog('cdGetData: Căn chỉnh con trỏ (Phương án Giáp)', {chatLen: chat.length, lastFloor: result.lastFloor, Độ_dài_pf: Array.isArray(result.processedFloors)?result.processedFloors.length:0}); } catch(e2) {}
        }
        if ((result._lastDiaryChatLength ?? 0) > chat.length) result._lastDiaryChatLength = chat.length;
        if ((result._baselineChatLength ?? -1) > chat.length) result._baselineChatLength = chat.length;
        if ((result._baselineChatLength ?? -1) < 0 && !result._baselineInitialized) {
          result._baselineChatLength = chat.length;
          result._lastDiaryChatLength = result._lastDiaryChatLength ?? chat.length;
          result._baselineInitialized = true;
        }
      }
      if (typeof cdDiaryTotal === 'function') _cdLastDiaryTotal = cdDiaryTotal(result);
      cdLog('cdGetData: Đọc thành công, diaries=', Object.keys(result.diaries).length, 'lastFloor=', result.lastFloor);
      return result;
    }

    // Không có bất kỳ dữ liệu lịch sử nào: Trả về dữ liệu trống (Không chủ động lưu vào đĩa, tránh việc vứt bỏ dữ liệu ở các tầng lưu trữ khác mà người dùng có thể có)
    cdLog('cdGetData: Không có dữ liệu lịch sử, trả về dữ liệu trống');
    return empty;
  } catch (e) {
    cdWarn('cdGetData thất bại', e);
    return emptyData();
  }
}

async function cdSaveData(data) {
  try {
    // Phát hiện số lượng nhật ký giảm đột ngột (Giữ nguyên logic cũ)
    const _dc = (typeof cdDiaryTotal === 'function') ? cdDiaryTotal(data) : 0;
    if (_cdLastDiaryTotal >= 0 && _dc < _cdLastDiaryTotal) {
      const _gap = _cdLastDiaryTotal - _dc;
      if (typeof cdAddLog === 'function') cdAddLog('warn', '[Bảo vệ dữ liệu] Phát hiện số lượng nhật ký giảm xuống', {Trước_đây: _cdLastDiaryTotal, Hiện_tại: _dc, Giảm: _gap});
      if (typeof toastr !== 'undefined') toastr.warning(`[Nhật ký nhân vật] Phát hiện nhật ký giảm ${_gap} mục. Nếu do lỡ xóa, có thể khôi phục thủ công tại "Quản lý -> Sao lưu/Khôi phục dữ liệu".`);
      _cdLastDiaryTotal = cdDiaryTotal(data);
    }
    const PLUGIN = PLUGIN_ID;
    let saveErr = null;
    let savedVia = [];

    // Luồng ① Ghi chatMetadata + Lưu đĩa
    try {
      const ctx = SillyTavern.getContext();
      if (ctx && ctx.chatMetadata) {
        if (!ctx.chatMetadata.extensions || typeof ctx.chatMetadata.extensions !== 'object') ctx.chatMetadata.extensions = {};
        ctx.chatMetadata.extensions[PLUGIN] = data;
        // Lần lượt thử các phương pháp lưu đĩa khả dụng và await (Ít nhất một phương pháp thực sự ghi đĩa là được)
        const meth = [
          ['saveMetadataDebounced',  () => typeof window !== 'undefined' && window.saveMetadataDebounced && window.saveMetadataDebounced()],
          ['ctx.saveMetadata',       () => ctx.saveMetadata && ctx.saveMetadata()],
          ['window.saveChatConditional', () => typeof window !== 'undefined' && window.saveChatConditional && window.saveChatConditional()],
          ['ctx.saveChat',           () => ctx.saveChat && ctx.saveChat()],
          ['window.saveChat',        () => typeof window !== 'undefined' && window.saveChat && window.saveChat()],
          ['ctx.saveSettingsDebounced', () => typeof ctx !== 'undefined' && ctx.saveSettingsDebounced && ctx.saveSettingsDebounced()],
        ];
        // ★ Sửa lỗi: Không break khi phương pháp đầu tiên không ném lỗi nữa, mà thực thi toàn bộ các phương pháp lưu đĩa khả dụng một lượt,
        //   và ưu tiên các phương pháp thực sự ghi đĩa là saveChat / saveChatConditional, đảm bảo dữ liệu thực sự được lưu bền vững vào file chat.
        //   saveMetadataDebounced là bộ điều phối chống rung, chỉ dựa vào nó có thể sẽ không thực sự ghi xuống đĩa (Thực tế test trên Tauri Tavern bị lỗi này).
        for (const [name, fn] of meth) {
          try {
            const r = fn();
            if (r && typeof r.then === 'function') { await r; }
            savedVia.push(name);
          } catch (e) { cdWarn(name + ' thất bại: ' + (e && e.message)); }
        }
      }
    } catch (e) { cdWarn('Ghi chatMetadata thất bại', e); saveErr = saveErr || e; }

    // ★★ Luồng ② Chat Variables lưu đĩa bắt buộc (Cơ chế ổn định nhất của v8/Bản cũ; Ghi kép đảm bảo mọi phiên bản ST đều có thể đọc lại)
    try {
      if (typeof insertOrAssignVariables === 'function') {
        await insertOrAssignVariables({ [PLUGIN]: data }, { type: 'chat' });
        savedVia.push('insertOrAssignVariables');
      }
    } catch (e) {
      cdWarn('insertOrAssignVariables lưu thất bại', e);
      saveErr = saveErr || e;
    }

    if (typeof cdAddLog === 'function') {
      cdAddLog('info', '[Lưu] Dữ liệu trò chuyện (Luồng kép)', { Phương_pháp: savedVia, diaries: Object.keys(data.diaries || {}).length });
    }
    cdLog('cdSaveData: Lưu hoàn tất Phương_pháp=', savedVia.join(','), 'diaries=', Object.keys(data.diaries || {}).length);
    if (saveErr) {
      cdWarn('cdSaveData tồn tại đường dẫn chưa được lưu đĩa hoàn toàn', saveErr);
    }
  } catch (e) {
    cdWarn("Lưu dữ liệu ván này thất bại", e);
    if (typeof toastr !== 'undefined') toastr.error('Nhật ký nhân vật lưu thất bại: ' + (e && e.message));
  }
}

/* ============================== Công cụ tầng ============================== */
/**
 * Lấy mảng ST chat hiện tại (Nguyên bản).
 * chat là mảng, chỉ số mảng chính là message_id.
 * Cấu trúc đối tượng tin nhắn: { mes, name, is_user, is_system, ... }
 * - Nội dung tin nhắn: m.mes (Không phải m.message)
 * - Tên nhân vật: m.name
 * - Có phải AI không: !m.is_user && !m.is_system
 */
function _cdGetChat() {
  try {
    const ctx = SillyTavern.getContext();
    if (ctx && Array.isArray(ctx.chat)) return ctx.chat;
  } catch (_) {}
  try {
    if (typeof SillyTavern !== 'undefined' && Array.isArray(SillyTavern.chat))
      return SillyTavern.chat;
  } catch (_) {}
  return [];
}

/** Lấy ID tầng lớn nhất của cuộc trò chuyện hiện tại (Chỉ số cuối cùng của mảng) */
function getLastFloorId() {
  const chat = _cdGetChat();
  if (chat.length > 0) return chat.length - 1;
  return -1;
}

/**
 * Lấy tất cả các tầng của AI (Đọc trực tiếp từ mảng nguyên bản của ST chat),
 * Đối tượng trả về được tiêm thêm trường message_id để tương thích với mã nguồn hạ nguồn.
 * Tin nhắn nguyên bản của ST không có trường .role, dùng !is_user && !is_system để xác định tin nhắn của AI.
 */
async function cdGetAiFloors() {
  const chat = _cdGetChat();
  if (!chat.length) return [];
  const result = [];
  for (let i = 0; i < chat.length; i++) {
    const m = chat[i];
    // ★ Tất cả tin nhắn có nội dung đều được tính là tầng (Không phân biệt AI/Người dùng/Hệ thống, tránh việc đánh dấu bị lộn xộn)
    if (m && m.mes && String(m.mes).trim()) {
      result.push({
        message_id: i,       // Tiêm message_id (Chỉ số mảng)
        name: m.name || '',
        mes: m.mes || '',    // Nội dung tin nhắn nguyên bản của ST là .mes
      });
    }
  }
  return result;
}
/** ★ Nguồn dữ liệu quản lý tầng đi theo "Nguồn dữ liệu tóm tắt tự động": Khi summarySource='jsonl' thì dùng toàn bộ tầng jsonl; Nếu không thì dùng mảng chat */
async function cdGetAiFloorsSmart() {
  try {
    const s = cdGetSettings();
    if (s.summarySource === 'jsonl') {
      const res = await cdReadAllFloorsFromJsonl();
      if (res.ok && Array.isArray(res.floors) && res.floors.length) {
        return res.floors.map(function (fl) {
          return { message_id: fl.i, name: fl.name || '', mes: fl.mes || '' };
        });
      }
    }
  } catch (e) {}
  return await cdGetAiFloors();
}

/** Trả về các tầng AI mới thêm sau lần ghi lại trước đó (Dựa trên đường cơ sở chat.length, không bị ảnh hưởng bởi việc tải phân mảnh) */
async function cdGetNewFloors(data) {
  const chat = _cdGetChat();
  let baseline = data._lastDiaryChatLength ?? 0;
  // Khi tải phân mảnh, đặt lại cả đường cơ sở và lastFloor thành chat.length hiện tại
  if (baseline > chat.length) {
    cdLog('cdGetNewFloors: Tải phân mảnh, đặt lại đường cơ sở', {'Đường cơ sở cũ': baseline, 'Đường cơ sở mới': chat.length});
    baseline = chat.length;
    data._lastDiaryChatLength = chat.length;
    // ★ Đồng thời đặt lại lastFloor, tránh trình quản lý tầng hiển thị lỗi
    if (data.lastFloor > chat.length - 1) {
      data.lastFloor = chat.length - 1;
    }
  }
  const floors = [];
  // ★ v2.7.3: Các tầng đã viết bù/tóm tắt thành công (processedFloors) dù có bị quét lại cũng không xử lý lặp lại nữa,
  //   tránh việc "sau khi viết bù tầng ở giữa, lần kích hoạt tự động tiếp theo lại coi tầng cũ là mới thêm" dẫn đến việc lưu trữ bị lặp mục.
  const _pfSet = Array.isArray(data && data.processedFloors) ? data.processedFloors.map(Number) : [];
  for (let i = baseline; i < chat.length; i++) {
    const m = chat[i];
    if (m && m.mes && String(m.mes).trim()) {
      if (_pfSet.indexOf(i) >= 0) continue; // Đã xử lý qua, bỏ qua (Phòng ngừa tóm tắt lặp lại)
      floors.push({ message_id: i, name: m.name || '', mes: m.mes || '' });
    }
  }
  return floors;
}

/* ============================== Gộp: Nhật ký ============================== */
function mergeDiaries(data, npcs, windowFloors, s) {
  const topFloor = windowFloors.length
    ? windowFloors[windowFloors.length - 1].message_id
    : (data.lastFloor ?? -1);

  for (const npc of npcs) {
    if (!npc || !npc.name) continue;
    const name = String(npc.name).trim();
    if (!name) continue;

    // Gộp bí danh
    let mainName = name;
    for (const [m, al] of Object.entries(data.aliases || {})) {
      if ((al || []).includes(name) || m === name) { mainName = m; break; }
    }

    // ★ Danh sách đen nhật ký nhân vật: Tên nằm trong danh sách đen (Khớp hoàn toàn) tuyệt đối không viết nhật ký/lưu ký ức cho chúng (Độ ưu tiên cao nhất, nhân vật trọng tâm cũng không ngoại lệ)
    const _bl = Array.isArray(s && s.diaryBlacklist) ? s.diaryBlacklist.map(String).map(function(x){ return (x||'').trim(); }).filter(Boolean) : [];
    if (_bl.length && (_bl.indexOf(mainName) >= 0 || _bl.indexOf(name) >= 0)) {
      cdLog('mergeDiaries: Nhân vật trong danh sách đen, bỏ qua', {'Nhân vật': name, 'Tên chính': mainName});
      continue;
    }
    // ★ Bắt buộc giữ lại nhân vật trọng tâm: Nhân vật trọng tâm được chỉ định thủ công (Bao gồm cả khớp bí danh) dù bị AI đánh dấu là người qua đường, cũng bắt buộc chuyển thành chính thức và viết nhật ký
    const _isFocus = Array.isArray(data.focusRoles) && data.focusRoles.some(function (f) {
      if (!f || !f.name) return false;
      if (f.name === mainName || f.name === name) return true;
      var al2 = data.aliases ? (data.aliases[mainName] || []) : [];
      return al2.indexOf(f.name) >= 0;
    });

    // ★ Ký ức có chọn lọc (Danh sách trắng): Sau khi bật chỉ ghi nhớ "Nhân vật trọng tâm", các nhân vật khác tuyệt đối bỏ qua (Không ghi lại, không tích lũy cameo)
    const _selective = s && s.selectiveMemory === true;
    if (_selective && !_isFocus) {
      cdLog('mergeDiaries: Đã bật ký ức có chọn lọc, bỏ qua nhân vật không trọng tâm', {'Nhân vật': name, 'Tên chính': mainName});
      continue;
    }

    // Logic chuyển người qua đường thành chính thức
    const isMinor = npc.is_minor === true;
    if (_isFocus) {
      data.promoted[mainName] = true;   // Nhân vật trọng tâm trực tiếp chuyển thành chính thức, không bị lọc bởi is_minor / cameo
    } else if (data.promoted[mainName]) {
      // Đã là nhân vật chính thức
    } else if (!isMinor) {
      data.promoted[mainName] = true;
    } else {
      data.cameo[mainName] = (data.cameo[mainName] || 0) + 1;
      if (data.cameo[mainName] >= (s.cameoThreshold || 3)) {
        data.promoted[mainName] = true;
      } else {
        continue; // Người qua đường, bỏ qua
      }
    }

    // Bổ sung bí danh
    const incomingAliases = Array.isArray(npc.aliases) ? npc.aliases.map(String) : [];
    data.aliases[mainName] = Array.from(new Set([...(data.aliases[mainName] || []), ...incomingAliases]));

    if (!data.diaries[mainName]) data.diaries[mainName] = [];
    // ★ Chống trùng lặp: Lọc trùng lặp theo (message_id + entry), tránh việc cùng một loạt tầng bị ghi đè thêm do chuyển đổi/kích hoạt lặp lại
    const _newEntry = npc.entry || '';
    const _dup = data.diaries[mainName].some(x => x && x.message_id === topFloor && (x.entry || '') === _newEntry);
    if (_dup) {
      cdLog('mergeDiaries: Bỏ qua nhật ký trùng lặp', {'Nhân vật': mainName, 'Tầng': topFloor});
      continue;
    }
    data.diaries[mainName].push({
      turn: npc.turn ?? topFloor,
      date: npc.date || '',
      entry: _newEntry,
      mood: npc.mood || '',
      attitude_to_user: npc.attitude_to_user || '',
      secret: npc.secret || '',
      key_events: Array.isArray(npc.key_events) ? npc.key_events : [],
      relationship_with_others: npc.relationship_with_others || {},
      message_id: topFloor,
    });
  }
  data.lastFloor = Math.max(data.lastFloor ?? -1, topFloor);
  // ★ Ghi lại chat.length hiện tại làm đường cơ sở để phát hiện tầng mới thêm cho lần sau
  const chat = _cdGetChat();
  data._lastDiaryChatLength = chat.length;
  return data;
}

/* ============================== Gộp: Quan hệ ============================== */
function mergeRelations(data, relList) {
  if (!data.relations) data.relations = {};
  for (const r of relList) {
    if (!r || !r.from || !r.to) continue;
    const from = String(r.from).trim();
    const to = String(r.to).trim();
    if (!from || !to || from === to) continue;
    if (!data.relations[from]) data.relations[from] = {};
    data.relations[from][to] = {
      type: r.type || '',
      attitude: ['positive', 'negative', 'neutral'].includes(r.attitude) ? r.attitude : 'neutral',
      note: r.note || '',
    };
  }
  return data;
}


/**
 * Rollback tầng: Kích hoạt khi tầng trò chuyện bị xóa/thu hồi.
 * ★ Tham khảo chế độ "Hồ sơ cốt truyện" (Kiểu ghi thêm, không bị mất khi xóa tầng): Khi tầng bị xóa **không tự động xóa nhật ký**,
 *   tránh việc vô tình xóa/tải phân mảnh dẫn đến mất nhật ký. Thay vào đó chỉ ghi lại thông tin tầng A bị xóa và nhắc nhở, người dùng có thể
 *   xử lý thủ công hoặc tạo lại trong "Quản lý -> Sao lưu/Khôi phục dữ liệu". Khi thực sự muốn hủy bỏ một đoạn cốt truyện nào đó,
 *   người dùng sẽ tự xóa nhật ký tương ứng theo cách thủ công trong giao diện quản lý.
 */
async function cdRollbackFrom(floor) {
  // Chỉ thống kê số lượng nhân vật bị ảnh hưởng làm nhắc nhở chẩn đoán (Không sửa đổi bản thân diaries)
  try {
    const data = await cdGetData();
    const affected = [];
    for (const [npc, list] of Object.entries(data.diaries)) {
      if (!Array.isArray(list)) continue;
      const hit = list.filter(e => (e.message_id ?? -1) >= floor).length;
      if (hit > 0) affected.push({ 'Nhân vật': npc, 'Số mục bị ảnh hưởng': hit });
    }
    cdAddLog('info', '[Rollback tầng] Đã phát hiện xóa tầng, nhật ký đã được giữ lại (Không tự động xóa nữa, tham khảo chế độ hồ sơ cốt truyện)', { floor, 'Nhân vật bị ảnh hưởng': affected });
    if (typeof toastr !== 'undefined' && affected.length) {
      toastr.info(`[Nhật ký nhân vật] Phát hiện tầng ${floor} bị xóa, nhật ký tương ứng đã được giữ lại để phòng ngừa mất mát. Nếu cần hủy bỏ có thể xử lý thủ công tại "Quản lý -> Sao lưu/Khôi phục dữ liệu".`);
    }
  } catch (e) {
    cdWarn('Nhắc nhở rollback tầng thất bại', e);
  }
}
// ============================================================
// Plugin Nhật ký nhân vật v2.0.0 — Động cơ nhật ký (Quy trình cốt lõi)
// Đường dẫn: SillyTavern/extensions/character-diary/engine.js
// ============================================================
'use strict';

/** Khóa Mutex — Ngăn chặn tạo đồng thời dẫn đến hỏng dữ liệu */
let cdBusy = false;
let _cdLastDiaryTotal = -1;   // Bảo vệ dữ liệu: Đường cơ sở tổng số nhật ký của dữ liệu hoàn chỉnh gần nhất
let cdBrowseLoadMore = {};   // Số lượng nhật ký đã hiển thị (Tải lười) của mỗi nhân vật trong giao diện duyệt
let cdBusyLabel = '';   // Tên nhiệm vụ đang chiếm dụng khóa hiện tại
let cdBusyAt = 0;        // Dấu thời gian bắt đầu chiếm dụng khóa
let cdPending = false;  // Khi đang khóa lại nhận được tín hiệu kích hoạt, đánh dấu "Chạy thêm một vòng sau khi hoàn thành"
let _cdLastAutoTriggerAt = 0;    // Chống rung kích hoạt tự động: Dấu thời gian thực sự bắt đầu xử lý của cdOnMessageReceived lần trước
let _cdLastAutoTriggerLen = -1;  // Chống rung kích hoạt tự động: chat.length lúc xử lý lần trước (Xác định xem có phải sự kiện kép của cùng một đợt tin nhắn không)
let _cdDeletingTo = 0;          // Che chắn xóa tầng: Dấu thời gian (Mili giây) trước khi kết thúc quy trình xóa, trong thời gian này ức chế kích hoạt tự động của MESSAGE_RECEIVED/RENDERED để phòng lặp lại

/**
 * Thực thi một lần tạo nhật ký + quan hệ.
 * @param {{ manual?: boolean, silent?: boolean }} opts
 *   manual: true = Người dùng kích hoạt thủ công, dù enabled=false vẫn chạy
 *   silent: true = Không hiện thông báo toastr (Dùng cho kích hoạt tự động)
 */

/* ============================== Tiêm ngữ cảnh nhật ký ============================== */
/** Đọc nhật ký từ chatMetadata, xây dựng trường ngữ cảnh để tiêm vào prompt của AI */

/* ============================== Tiêm ngữ cảnh nhật ký ============================== */
/** Đọc nhật ký từ chatMetadata, dùng setExtensionPrompt để tiêm vào cuộc đối thoại tiếp theo của AI */
/** Tạo văn bản tiêm nhật ký có cấu trúc */
async function cdBuildDiaryInjectionText() {
  try {
    const data = await cdGetData();
    const s = cdGetSettings();
    const diaryNames = Object.keys(data.diaries || {});
    
    const blocks = [];
    
    // ====== Nhật ký nhân vật (Chịu sự kiểm soát của injectDiary; Khi bật diaryCharFilter chỉ tiêm "Nhân vật ra sân")======
    if (s.injectDiary !== false && diaryNames.length) {
      const diaryLines = [];
      // ★ Lọc theo nhân vật ra sân: Bắt các nhân vật ra sân từ cuộc trò chuyện hiện tại, chỉ tiêm nhật ký của những nhân vật này (Chế độ dây chuyền, tránh tiêm toàn bộ)
      let namesToInject = diaryNames;
      if (s.diaryCharFilter) {
        try {
          const chat2 = (typeof _cdGetChat === 'function') ? _cdGetChat() : [];
          // ★ Chỉ lấy "Cửa sổ tầng gần nhất" để xác định nhân vật ra sân (Tránh việc cả cuộc trò chuyện coi tất cả các nhân vật đều là đã ra sân)
          const _win = (chat2 && chat2.length) ? chat2.slice(-(Math.max(2, parseInt(s.diaryCharWindow,10)||16))) : (chat2 || []);
          const sceneTxt = _win
            .map(m => (m && (m.mes || m.message)) ? (m.name || '') + ': ' + (m.mes || m.message) : '')
            .join('\n');
          const capt = cdCaptureCast(sceneTxt, data);
          if (capt && capt.length) namesToInject = capt;
          // ★ Chẩn đoán lúc chạy: Khi tiêm thực sự thì đã bắt được ai, cửa sổ lớn bao nhiêu
          cdAddLog && cdAddLog('info', '[Tiêm·Bắt nhân vật ra sân]', { 'Đã bật': !!s.diaryCharFilter, 'Số tầng cửa sổ': _win.length, 'Đã bắt được': capt||[], 'Sẽ tiêm': namesToInject||[], 'Xem trước scene': sceneTxt.slice(0,300) });
        } catch (e) { if (typeof cdWarn === 'function') cdWarn('Bắt nhân vật ra sân thất bại, lùi về tiêm toàn bộ', e); }
      }
      const charLimit = Math.max(1, parseInt(s.diaryCharLimit, 10) || 1);
      for (const name of namesToInject) {
        const list = data.diaries[name];
        if (!Array.isArray(list) || !list.length) continue;
        // Lấy charLimit bài gần đây; Căn chỉnh "Dây chuyền" cố gắng cho càng nhiều càng tốt
        const slice = list.slice(-charLimit);
        slice.forEach((last, i) => {
          if (!last) return;
          const tag = slice.length > 1 ? ('[' + (i + 1) + '/' + slice.length + '] ') : '';
          const dateStr = last.date ? last.date : (last.turn != null ? 'Tầng ' + last.turn : '');
          const moodStr = last.mood ? ` (Tâm trạng: ${last.mood})` : '';
          const attitudeStr = last.attitude_to_user ? `Thái độ với người dùng: ${last.attitude_to_user}` : '';
          const extras = [moodStr, attitudeStr].filter(Boolean).join(', ');
          diaryLines.push(`- ${name}${tag}(${dateStr}${extras ? ' ' + extras : ''}): ${last.entry}`);
        });
      }
      if (diaryLines.length) {
        blocks.push('[Nhật ký nhân vật]');
        diaryLines.forEach(line => blocks.push(line));
      }
    }
    
    // ====== Mạng lưới quan hệ nhân vật (Chịu sự kiểm soát của injectRelation)======
    if (s.injectRelation !== false) {
      const rels = data.relations || {};
      const relLines = [];
      for (const [from, targets] of Object.entries(rels)) {
        for (const [to, rel] of Object.entries(targets)) {
          const attitudeIcon = rel.attitude === 'positive' ? 'Thân thiện' : rel.attitude === 'negative' ? 'Bài xích' : 'Trung lập';
          const noteStr = rel.note ? ` (${rel.note})` : '';
          relLines.push(`- ${from} → ${to}: ${rel.type || ''}[${attitudeIcon}]${noteStr}`);
        }
      }
      if (relLines.length) {
        blocks.push('[Quan hệ nhân vật]');
        relLines.forEach(line => blocks.push(line));
      }
    }
    
    // ====== Hồ sơ cốt truyện (Chịu sự kiểm soát của injectArchive)======
    if (s.injectArchive !== false) {
      // ★ Chế độ vector: Truy xuất vài mục liên quan nhất từ hồ sơ lịch sử để tiêm, tránh việc tiêm toàn bộ hàng chục nghìn token
      if (s.archiveMode === 'vector' && Array.isArray(data.archiveVectors) && data.archiveVectors.length > 0 && typeof cdSearchVectors === 'function') {
        const chat = _cdGetChat();
        const recent = (Array.isArray(chat) ? chat.slice(-6) : [])
          .map(function (m) { return (m && m.mes) ? m.mes : ''; }).join('\n');
        const topK = s.vectorTopK || 5;
        const threshold = s.vectorThreshold || 0.6;
        let results = await cdSearchVectors(recent || 'Cốt truyện hiện tại', data.archiveVectors, topK, threshold);
        // ★ rerank Sắp xếp lại (Chuỗi liên kết tiêm hồ sơ cốt truyện)
        results = await cdRerankResults(recent || 'Cốt truyện hiện tại', results, s, 'story');
        const vecTxt = results.length > 0 ? results.map(function (r) { return r.text; }).join('\n') : '(Không truy xuất được sự kiện lịch sử liên quan)';
        blocks.push('[Hồ sơ cốt truyện·Truy xuất vector]');
        blocks.push(vecTxt);
      } else {
        const arc = data.archive;
        if (arc) {
          const arcParts = [];
          if (arc.mainline) arcParts.push(`Tuyến chính: ${arc.mainline}`);
          if (arc.sideline) arcParts.push(`Tuyến phụ: ${arc.sideline}`);
          if (arc.states) arcParts.push(`Trạng thái quan trọng: ${arc.states}`);
          if (arc.unresolved) arcParts.push(`Các vấn đề chưa giải quyết: ${arc.unresolved}`);
          // ★ Mỏ neo thời gian hiện tại (Mới nhất kiểu ghi đè)
          if (arc.timeAnchor && String(arc.timeAnchor).trim()) arcParts.push(`Thời gian hiện tại: ${String(arc.timeAnchor).trim()}`);
          if (Array.isArray(arc.locations) && arc.locations.length) { var _locs = []; (function(){ for (var _i=0;_i<arc.locations.length;_i++){var _t=String(arc.locations[_i]).trim(); if(_t&&_locs.indexOf(_t)<0) _locs.push(_t);} _locs=_locs.slice(-3); })(); if (_locs.length) arcParts.push('Địa điểm (Đã đặt chân/Vị trí hiện tại):\n' + _locs.map(function(l){ return '- ' + l; }).join('\n')); }
          // ★ Ghi chép nhiệm vụ (Nhiệm vụ đang hoạt động)
          if (Array.isArray(arc.tasks) && arc.tasks.length) {
            arcParts.push('Ghi chép nhiệm vụ:\n' + arc.tasks.map(function(t){ return '- ' + (t && t.line || ''); }).join('\n'));
          }
  // ★ Tiêm mục theo dõi cốt truyện tùy chỉnh
          const injCustomFields = Array.isArray(s.customFields) ? s.customFields.filter(f => f && f.key && f.label) : [];
          const injCustomMap = (arc.custom && typeof arc.custom === 'object') ? arc.custom : {};
          for (const def of injCustomFields) {
            const arr = Array.isArray(injCustomMap[def.key]) ? injCustomMap[def.key] : [];
            if (!arr.length) continue;
            arcParts.push(`Tùy chỉnh ${def.label}: ${arr.map(it => it.time ? `【${it.time}】${it.desc}` : it.desc).join('\n')}`);
          }
          if (arcParts.length) {
            blocks.push('[Hồ sơ cốt truyện]');
            arcParts.forEach(p => blocks.push(`- ${p}`));
          }
        }
      }
    }
    
    // ====== Bản ghi nhớ của người dùng (Điền thủ công ở giao diện trạng thái, tiêm cho AI khi trò chuyện, độ ưu tiên cao nhất đặt lên đầu)======
    if (s.injectMemo !== false && data.memo && String(data.memo).trim()) {
      blocks.unshift(String(data.memo).trim());
      blocks.unshift('Dưới đây là bản ghi nhớ do người dùng chủ động ghi lại thủ công, bắt buộc phải tuân thủ nghiêm ngặt và thể hiện trong phản hồi:');
      blocks.unshift('[Bản ghi nhớ của người dùng·Độ ưu tiên cao nhất]');
    }

    const base = blocks.join('\n');
    // ── Ghi thêm chỉ thị điền bảng (Bao gồm hiện trạng bảng hiện tại, làm bối cảnh ký ức) ──
    let lt = '';
    try {
      const ltInstr = cdBuildLiveTableInjectText();
      // ★ Khi tắt công tắc điền bảng, cho dù có dữ liệu bảng lịch sử cũng không ghép vào nội dung điền bảng (Tránh việc "Tắt rồi mà vẫn tiêm")
      const _ltOn = s.liveTableEnabled !== false && s.liveTableInject !== false;
      const ltData = _ltOn && Array.isArray(data.liveTableData) && data.liveTableData[0] ? data.liveTableData[0] : null;
      let tableTxt = '';
      const ltLower = (ltData && ltData.lower) || {};
      const hasLower = Object.keys(ltLower).some((k) => ltLower[k]);
      if (ltData && (ltData.location || Object.keys(ltData.chars || {}).length || hasLower)) {
        const tl = [];
        if (ltData.location) tl.push('Địa điểm: ' + ltData.location);
        const chars = ltData.chars || {};
        const _cf = Array.isArray(s.liveCharFields) && s.liveCharFields.length ? s.liveCharFields : ['Trạng thái', 'Trang phục', 'Hảo cảm với người dùng', 'Ghi chú'];
        const _lf = Array.isArray(s.liveLowerFields) && s.liveLowerFields.length ? s.liveLowerFields : ['Những việc đã trải qua', 'Vật phẩm đang sở hữu', 'Nhiệm vụ'];
        Object.keys(chars).forEach((name) => {
          const ch = chars[name] || {};
          tl.push(`Tên nhân vật: ${name}|` + _cf.map((f) => `${f}:${ch[f] || ''}`).join('|'));
        });
        _lf.forEach((k) => {
          if (ltLower[k]) { var _ls = ltLower[k].split('\n').map((l) => l.trim()).filter(Boolean); if (_ls.length) tl.push(k + '\n- ' + _ls.join('\n- ')); }
        });
        // [Tiêm nhiều hơn] Bảng trạng thái tiêm đầy đủ hơn: Mỗi loại (Địa điểm/Dòng nhân vật/Lý lịch) được chia đoạn rõ ràng; Lý lịch giữ lại nhiều dòng, không nén thành một dòng; Kèm theo lời giải thích để AI hiểu đây là trạng thái cốt truyện hiện tại đã được ghi lại
        tableTxt = '[Bảng trạng thái cốt truyện·Hiện tại] (Đây là trạng thái cốt truyện hiện tại đã được plugin ghi lại, để bạn tham khảo hiện trạng của thế giới/nhân vật, khi phản hồi hãy bám sát những trạng thái này để thúc đẩy diễn biến)\n' + tl.join('\n');
      }
      lt = ltInstr ? (ltInstr + (tableTxt ? '\n\n' + tableTxt : '')) : (tableTxt || '');
    } catch (e) {}
    if (lt && s.liveTableEnabled !== false && s.liveTableInject !== false) {
      const prompt = lt ? (lt + '\n\n' + (base || '')) : base;
      cdLog('[Điền bảng] Tiêm bảng điền (Bao gồm hiện trạng bảng) độ dài', { promptLen: String(prompt).length });
      return prompt + (typeof cdForumInjectText === 'function' ? cdForumInjectText() : '');
    }
    return base + (typeof cdForumInjectText === 'function' ? cdForumInjectText() : '');


  } catch (e) {
    cdWarn('cdBuildDiaryInjectionText thất bại', e);
    return '';
  }
}

/** Quản lý trạng thái tiêm */
let _cdInjectionRegistered = false;
// idempotent dedupe injection by eventData.chat ref
const _cdInjectedChatRefs = new WeakSet();
let _cdInjectionKey = 'character-diary-memory';
/** Lưu đệm tin nhắn tiêm được tạo gần nhất (Để CHAT_COMPLETION_PROMPT_READY chèn thủ công theo vị trí) */
let _cdInjectMsg = null;
let _cdInjectMsgRole = 0;

/** Đăng ký tiêm bằng cách sử dụng setExtensionPrompt.
 * Định nghĩa @types chính thức của ST: position chỉ nhận 1 (Chèn vào trò chuyện) hoặc -1 (Không tiêm), vị trí thực tế do depth kiểm soát.
 * Do đó ở đây position trả về cố định là 1, việc "Mở đầu/Giữa cuộc trò chuyện/Cuối" thực sự được giao cho cdResolveInjectDepth thực hiện thông qua depth. */
function cdGetInjectPosition() {
  return 1; // ST @types: 1 = Chèn vào trò chuyện
}

/**
 * Tính toán depth tương ứng dựa trên vị trí tiêm do người dùng chọn (Khi ST "Chèn vào trò chuyện", depth có nghĩa là "Đếm ngược từ cuối lên tin nhắn thứ N", giá trị càng nhỏ càng gần cuối/đang tạo hiện tại)
 * @param {number} chatLen Số lượng tin nhắn trò chuyện hiện tại
 */
function cdResolveInjectDepth(chatLen) {
  const s = cdGetSettings();
  const pos = s.injectPosition || 'after';
  const len = Math.max(1, chatLen || 1);
  if (pos === 'before') return Math.floor(len * 0.98);  // Gần mở đầu (Gần tin nhắn sớm nhất)
  if (pos === 'chat')   return Math.floor(len * 0.5);    // Giữa cuộc trò chuyện
  return 1;                                               // Cuối cuộc trò chuyện: Gần nhất với lượt tạo hiện tại (depth=1 tin nhắn cuối cùng)
}

/** Vai trò tin nhắn tiêm 0=system 1=user 2=assistant → ST @types định nghĩa là number */
function cdGetInjectRole() {
  const s = cdGetSettings();
  const r = (s.injectRole !== undefined) ? s.injectRole : 0;
  if (r === 1) return 1;
  if (r === 2) return 2;
  return 0;
}
/** Độ sâu bên trong tầng tiêm */
function cdGetInjectDepth() {
  const s = cdGetSettings();
  const d = parseInt(s.injectDepth, 10);
  return (isFinite(d) && d >= 0) ? d : 1;
}
async function cdRegisterInjection() {
  try {
    const _s = cdGetSettings();
    // ★ Công tắc chính đã tắt: Xóa rỗng nội dung tiêm, hoàn toàn dừng tiêm
    if (_s.enabled === false) {
      _cdInjectMsg = null;
      _cdInjectMsgRole = 0;
      cdAddLog('info', '[Tiêm] Công tắc chính đã tắt, đã dừng tiêm');
      return;
    }
    const text = await cdBuildDiaryInjectionText();
    // Lưu đệm nội dung tiêm, để CHAT_COMPLETION_PROMPT_READY chèn thủ công theo vị trí trước khi tạo (Kiểm soát vị trí của setExtensionPrompt không có hiệu lực trong phiên bản ST này)
    _cdInjectMsg = text || null;
    _cdInjectMsgRole = cdGetInjectRole();
    cdAddLog('info', '[Tiêm] Nội dung tiêm đã được lưu đệm', { 'Vị trí cài đặt của người dùng': _s.injectPosition, 'Số ký tự': text ? text.length : 0 });
  } catch (e) {
    cdAddLog('warn', '[Tiêm] cdRegisterInjection thất bại: ' + e.message);
  }
}

/**
 * Thử nghiệm tiêm: Kích hoạt thủ công tiêm một lần, và ghi lại thông tin quan trọng liên quan đến tiêm của ST vào bảng nhật ký, giúp người dùng dễ dàng xuất ra để phân tích
 */
async function cdTestInjection() {
  try {
    cdAddLog('info', '========== Bắt đầu thử nghiệm tiêm ==========');
    const ctx = SillyTavern.getContext();

    // 1. Hằng số Vị trí/Vai trò của ST có được phơi bày hay không
    const ept = (typeof extension_prompt_types !== 'undefined' && extension_prompt_types) ? extension_prompt_types : null;
    cdAddLog('info', '[Thử nghiệm tiêm] extension_prompt_types', { 'Có tồn tại không': !!ept, 'Giá trị': ept });

    // 2. setExtensionPrompt có khả dụng không
    cdAddLog('info', '[Thử nghiệm tiêm] setExtensionPrompt', { 'Khả dụng': !!(ctx && typeof ctx.setExtensionPrompt === 'function') });

    // 3. Cài đặt của người dùng (Cơ chế tiêm mới: Chèn thủ công prompt chat theo vị trí trong sự kiện)
    const sRef = cdGetSettings();
    const chatLen = (ctx && ctx.chat && Array.isArray(ctx.chat)) ? ctx.chat.length : 0;
    cdAddLog('info', '[Thử nghiệm tiêm] Cấu hình tiêm', {
      'Cơ chế': 'CHAT_COMPLETION_PROMPT_READY chèn thủ công theo vị trí',
      'Vị trí người dùng': sRef.injectPosition,
      'Số dòng chat': chatLen,
      'Vai trò tin nhắn': sRef.injectRole,
      'Cài đặt độ sâu trong tầng': sRef.injectDepth,
    });

    // 4. Đọc độ dài văn bản tiêm (Xác nhận xem nội dung đã được tạo chưa)
    const text = await cdBuildDiaryInjectionText();
    cdAddLog('info', '[Thử nghiệm tiêm] Văn bản tiêm', { 'Độ dài': text ? text.length : 0, '100 chữ đầu': text ? text.slice(0, 100) : '' });

    // 5. Các prompt mở rộng đã được đăng ký hiện tại của ST (Có thể thấy vị trí/nội dung tiêm thực tế)
    try {
      const ep = ctx && ctx.extensionPrompts;
      if (ep) {
        const arr = (typeof ep.toArray === 'function') ? ep.toArray() : (Array.isArray(ep) ? ep : null);
        if (arr) {
          cdAddLog('info', '[Thử nghiệm tiêm] Prompt mở rộng đã đăng ký của ST', arr.map(function (x) {
            return { key: x && (x.name || x.key || x.id), 'Vị trí': x && x.position, 'Vai trò': x && x.role, 'Độ sâu': x && x.depth };
          }));
        } else {
          cdAddLog('info', '[Thử nghiệm tiêm] extensionPrompts có tồn tại nhưng không thể liệt kê', { 'Loại': typeof ep });
        }
      } else {
        cdAddLog('info', '[Thử nghiệm tiêm] Không tìm thấy ctx.extensionPrompts (Có thể không phơi bày)');
      }
    } catch (e2) {
      cdAddLog('warn', '[Thử nghiệm tiêm] Đọc extensionPrompts thất bại: ' + e2.message);
    }

    // 6. Kích hoạt thực sự một lần tiêm
    await cdRegisterInjection();
    cdAddLog('info', '========== Kết thúc thử nghiệm tiêm ==========');
    window.setTimeout(function () { cdRenderLog(); }, 300);
  } catch (e) {
    cdAddLog('warn', '[Thử nghiệm tiêm] Thử nghiệm tiêm có lỗi: ' + e.message);
  }
}

/**
 * Chẩn đoán mục theo dõi tùy chỉnh: Ghi lại cấu hình, dữ liệu hiện có, tiêm prompt, tình trạng phân tích, giúp định vị vấn đề "mục theo dõi không có tác dụng"
 */
async function cdTestCustomFields() {
  try {
    cdAddLog('info', '========== Bắt đầu chẩn đoán mục theo dõi ==========');
    const s = cdGetSettings();
    const data = await cdGetData();

    // 1. Các mục theo dõi được cấu hình hiện tại
    const cf = Array.isArray(s.customFields) ? s.customFields : [];
    cdAddLog('info', '[Mục theo dõi] Cấu hình hiện tại', {
      'Số lượng': cf.length,
      'Trường': cf.map(f => ({ key: f && f.key, label: f && f.label, desc: f && f.desc })),
    });

    // 2. Dữ liệu hiện có của archive.custom
    const arc = data && data.archive ? data.archive : {};
    const customMap = (arc.custom && typeof arc.custom === 'object') ? arc.custom : {};
    cdAddLog('info', '[Mục theo dõi] Dữ liệu archive.custom', {
      'Số trường': Object.keys(customMap).length,
      'Số dòng mỗi trường': Object.keys(customMap).map(k => ({ key: k, 'Số dòng': Array.isArray(customMap[k]) ? customMap[k].length : 0 })),
      'Ví dụ vài dòng đầu': (()=>{ const o={}; for(const k of Object.keys(customMap)){ const arr=Array.isArray(customMap[k])?customMap[k]:[]; if(arr.length) o[k]=arr.slice(0,2).map(it=>it.time+' '+it.desc).join(' | '); } return o; })(),
    });

    // 3. Tiêm prompt: Thử xây dựng prompt hồ sơ cốt truyện một lần, xem có bao gồm tên trường tùy chỉnh không (Không thực sự gửi yêu cầu API)
    try {
      const fakeFloors = [{ message_id: 1, name: 'Thử nghiệm', mes: '(Dùng tầng gần nhất để kiểm tra tiêm prompt)' }];
      const msgs = await cdBuildArchivePrompt(fakeFloors, data, s);
      const sysTxt = msgs && msgs.length ? (msgs[0] && msgs[0].content) || '' : '';
      const userTxt = msgs && msgs.length > 1 ? (msgs[1] && msgs[1].content) || '' : '';
      const missing = cf.filter(f => f && f.label && sysTxt.indexOf(f.label) < 0).map(f => f.label);
      cdAddLog('info', '[Mục theo dõi] Prompt hồ sơ cốt truyện', {
        sysLen: sysTxt.length,
        userTxtPreview: userTxt.slice(0, 200),
        missingLabels: missing,
      });
    } catch (e3) {
      cdAddLog('warn', '[Mục theo dõi] Xây dựng prompt thất bại: ' + e3.message);
    }

    // 4. Thử nghiệm phân tích: Đưa ra một đầu ra AI giả lập có chứa trường tùy chỉnh, xem có phân tích đúng không
    try {
      const testTxt = 'Tuyến chính:\n【Ngày thứ 1】Đến nơi\n\n' + cf.map(f => `${f.label}:\n【Ngày thứ 1】Nội dung giả lập`).join('\n\n');
      const parsed = parseArchiveJson(testTxt, cf);
      cdAddLog('info', '[Mục theo dõi] Thử nghiệm phân tích', {
        'Trường tùy chỉnh phân tích được': Object.keys(parsed.custom || {}).map(k => `${k}:${(parsed.custom[k]||[]).length} dòng`),
      });
    } catch (e4) {
      cdAddLog('warn', '[Mục theo dõi] Thử nghiệm phân tích thất bại: ' + e4.message);
    }

    cdAddLog('info', '========== Kết thúc chẩn đoán mục theo dõi ==========');
    window.setTimeout(function () { cdRenderLog(); }, 300);
  } catch (e) {
    cdAddLog('warn', '[Mục theo dõi] Chẩn đoán có lỗi: ' + e.message);
  }
}

/**
 * Lưu toàn cục mục theo dõi tùy chỉnh (Cho nút dòng thời gian gọi inline onclick, đáng tin cậy nhất, không phụ thuộc vào ràng buộc sự kiện)
 */
function cdCustomSaveFields() {
  try {
    cdAddLog('info', '[Mục theo dõi] Click nút lưu');
    const curS = cdGetSettings();
    const oldCustom = Array.isArray(curS.customFields) ? curS.customFields : [];
    const ta = document.getElementById('cd-custom-fields-input');
    const raw = (ta && ta.value ? ta.value : '');
    cdAddLog('info', '[Mục theo dõi] Nội dung ô nhập', { 'Độ dài': raw.length, 'Nội dung': raw.slice(0, 200) });
    const lines = raw.split('\n').map(l => l.trim()).filter(Boolean);
    const customFields = [];
    let autoIdx = 1;
    const usedKeys = {};
    for (const line of lines) {
      // ★ Phân tích thẻ [Ghi đè]/[Ghi thêm] ở cuối dòng
      let _mode = 'append';
      let _line = line;
      const _mm = _line.match(/\[Ghi đè\]\s*$/i) || _line.match(/\[overwrite\]\s*$/i);
      if (_mm) { _mode = 'overwrite'; _line = _line.replace(/\[Ghi đè\]|\[overwrite\]\s*$/i, '').trim(); }
      else if (_line.match(/\[Ghi thêm\]\s*$/i) || _line.match(/\[append\]\s*$/i)) { _mode = 'append'; _line = _line.replace(/\[Ghi thêm\]|\[append\]\s*$/i, '').trim(); }
      const m = _line.match(/^(.+?)[：:]\s*(.*)$/);
      const label = (m ? m[1] : _line).trim();
      const desc = (m ? m[2] : '').trim();
      if (!label) continue;
      const existing = oldCustom.find(f => f && f.label === label);
      let key = existing && existing.key ? existing.key : null;
      if (!key) { do { key = 'custom_' + autoIdx++; } while (usedKeys[key]); }
      usedKeys[key] = true;
      customFields.push({ key, label, desc, mode: _mode });
    }
    // ★ Nhật ký: Ghi lại loại của mỗi mục theo dõi (Ghi đè/Ghi thêm)
    cdAddLog('info', '[Mục theo dõi] Loại đã lưu', { 'Số lượng': customFields.length, 'Danh sách': customFields.map(f => f.label + '=' + (f.mode||'append')) });
    cdSaveSettings({ customFields });
    cdAddLog('info', '[Mục theo dõi] Đã ghi vào settings', { 'Số lượng': customFields.length, 'Trường': customFields.map(f => f.label) });
    if (customFields.length) {
      toastr.success(`Đã lưu ${customFields.length} mục theo dõi: Đã tiêm prompt · Đã nối vào phân tích`);
    } else {
      toastr.info('Đã xóa rỗng các mục theo dõi tùy chỉnh (Không tiêm prompt nữa)');
    }
    if (typeof cdRenderArchive === 'function') cdRenderArchive();
  } catch (e) {
    cdAddLog('warn', '[Mục theo dõi] Lưu thất bại: ' + e.message + ' | ' + (e && e.stack ? e.stack.split('\n')[1] : ''));
  }
}
if (typeof window !== 'undefined') window.cdCustomSaveFields = cdCustomSaveFields;
/** ★ Lưu bản ghi nhớ: Đọc giao diện trạng thái #cd-memo-input → data.memo → cdSaveData (Tiêm cho AI khi trò chuyện) */
async function cdSaveMemo() {
  try {
    const ta = document.getElementById('cd-memo-input');
    const raw = (ta && ta.value != null) ? String(ta.value) : '';
    const data = await cdGetData();
    data.memo = raw;
    await cdSaveData(data);
    if (typeof cdAddLog === 'function') cdAddLog('info', '[Bản ghi nhớ] Đã lưu', { 'Độ dài': raw.length });
    if (typeof toastr !== 'undefined') toastr.success(raw ? 'Bản ghi nhớ đã lưu, sẽ tiêm cho AI' : 'Bản ghi nhớ đã bị xóa rỗng');
  } catch (e) {
    if (typeof cdAddLog === 'function') cdAddLog('warn', '[Bản ghi nhớ] Lưu thất bại: ' + (e && e.message));
    if (typeof toastr !== 'undefined') toastr.error('Lưu bản ghi nhớ thất bại: ' + (e && e.message));
  }
}
