function cdBuildLiveTableInjectText() {
  try {
    const s = cdGetSettings();
    if (!s.liveTableEnabled || !s.liveTableInject) return '';
    // Người dùng tùy chỉnh prompt được ưu tiên (Có thể chỉnh sửa tự do)
    const customPrompt = (s.liveTablePrompt || '').trim();
    if (customPrompt) return customPrompt;
    const tag = s.liveTableTag || 'liwe';
    return [
      `[Chỉ thị quan trọng · Điền bảng] Đây là chỉ thị then chốt bắt buộc phải tuân thủ.`,
      `Dựa vào diễn biến vừa rồi, bắt buộc phải dùng một khối gập <details><summary>Bảng thông tin</summary> để bọc ở cuối phản hồi, bên trong xuất ra một thẻ <${tag}>, ghi chép lại nghiêm ngặt theo định dạng sau:`,
      ``,
      `Địa điểm: (Vị trí hiện tại, có thay đổi mới xuất ra)`,
      `Tên nhân vật: Tên cụ thể|${(() => { const f = Array.isArray(s.liveCharFields) && s.liveCharFields.length ? s.liveCharFields : ['Trạng thái', 'Trang phục', 'Hảo cảm với người dùng', 'Ghi chú']; return f.map((x) => x + ':...').join('|'); })()}`,
      `(Mỗi nhân vật xuất hiện một dòng; Các trường con cách nhau bằng |, định dạng là "Trường con:Giá trị"; Trường con của nhân vật đó có thay đổi mới xuất ra dòng đó, cập nhật kiểu ghi đè; Các trường con sau trường Tên nhân vật có thể trực tiếp lược bỏ các mục không thay đổi)`,
      ``,
       ...(() => { const f = Array.isArray(s.liveLowerFields) && s.liveLowerFields.length ? s.liveLowerFields : ['Những việc đã trải qua', 'Vật phẩm đang sở hữu', 'Nhiệm vụ']; return f.map((x) => `${x}: (${x} của {{user}}, có nội dung mới mới xuất ra)`); })()
      ``,
      `Quy tắc:`,
      `1. Trích xuất đúng sự thật từ cốt truyện, không bịa đặt; Các mục không có thay đổi/không liên quan lần này đừng xuất ra.`,
      `2. Dòng nhân vật, địa điểm là "Cập nhật kiểu ghi đè"; Trải nghiệm/Vật phẩm/Nhiệm vụ là "Ghi thêm mục mới".`,
      `3. Những việc đã trải qua bắt buộc phải kèm theo thời gian và địa điểm.`,
      `4. Dùng <details><summary>Bảng thông tin</summary> ... </details> để bọc thẻ &lt;${tag}&gt;, phần thân văn bản chỉ hiển thị thanh gập, không trực tiếp hiển thị nội dung bảng.`,
    ].join('\n');
  } catch (e) {
    cdWarn('Xây dựng tiêm điền bảng thất bại', e);
    return '';
  }
}
/**
 * Callback sự kiện CHAT_COMPLETION_PROMPT_READY: Phương án tiêm dự phòng
 * Fallback khi setExtensionPrompt không khả dụng
 */
async function cdOnBeforeGeneration(eventData) {
  try {
    const data = eventData && typeof eventData === 'object' ? eventData : {};
    const chat = data.chat || [];
    const dryRun = data.dryRun === true || data.dry_run === true;
    if (dryRun || !Array.isArray(chat) || !chat.length) return;
    // idempotent: skip if already injected for this chat ref
    if (typeof _cdInjectedChatRefs.has === 'function' && _cdInjectedChatRefs.has(chat)) { return; }

    // ★ Công tắc chính tắt thì không tiêm
    const _s = cdGetSettings();
    if (_s.enabled === false) return;

    // ★ Gia cố: Xây dựng lại bộ nhớ đệm tiêm trước mỗi lần tạo, đảm bảo "Dữ liệu thay đổi" và "Nội dung tiêm" đồng bộ theo thời gian thực,
    //   tránh việc sau khi thực hiện thao tác xóa/xóa hàng loạt hồ sơ cốt truyện, bộ nhớ đệm cũ _cdInjectMsg vẫn bị tiêm vào lần tạo này.
    try { await cdRefreshInjection(); } catch (e) { cdWarn('Xây dựng lại bộ nhớ đệm tiêm trước khi tạo thất bại (Tiếp tục dùng bộ nhớ đệm cũ)', e); }

    // ---- Tiêm ký ức (Nhật ký/Quan hệ/Hồ sơ/Điền bảng), nếu không có nội dung thì bỏ qua nhưng vẫn tiếp tục tiêm nghi thức ----
    if (_cdInjectMsg) {
      const sysMsg = { role: _cdInjectMsgRole === 1 ? 'user' : (_cdInjectMsgRole === 2 ? 'assistant' : 'system'), content: _cdInjectMsg };
      const s = _s;
      const pos = s.injectPosition || 'after';
      const userDepth = Math.max(1, parseInt(s.injectDepth, 10) || 1);
      let idx;
      if (pos === 'before') {
        idx = 0;
        while (idx < chat.length && chat[idx].role === 'system') idx++;
        chat.splice(idx, 0, sysMsg);
        cdAddLog('info', '[Tiêm] Tiêm mở đầu', { 'Vị trí chèn': idx, 'Số ký tự': _cdInjectMsg.length });
      } else if (pos === 'chat') {
        idx = Math.floor(chat.length / 2);
        chat.splice(idx, 0, sysMsg);
        cdAddLog('info', '[Tiêm] Tiêm giữa cuộc trò chuyện', { 'Vị trí chèn': idx, 'Số ký tự': _cdInjectMsg.length });
      } else {
        idx = Math.max(0, chat.length - userDepth);
        chat.splice(idx, 0, sysMsg);
        cdAddLog('info', '[Tiêm] Tiêm cuối', { 'Vị trí chèn': idx, 'Độ sâu': userDepth, 'Tổng số dòng': chat.length, 'Số ký tự': _cdInjectMsg.length });
      }
    }

    // ---- Tiêm nghi thức (Thư viện module bối cảnh): Các khế ước được bật sẽ được tiêm theo vị trí tương ứng ----
    // Phân nhóm: before / chat / after, bên trong nhóm giữ nguyên thứ tự ban đầu của module
    const _grp = { before: [], chat: [], after: [] };
    const _inj = Array.isArray(_s.ritualInjects) ? _s.ritualInjects : [];
    for (const _m of _inj) {
      if (!_m || !_m.enabled) continue;
      const _txts = (_m && _m.texts) || {};
      let _key = _m.variant;
      if (!_txts[_key]) _key = Object.keys(_txts)[0];
      const _t = _key ? _txts[_key] : '';
      if (!_t) continue;
      const _p = (_m.position || 'before');
      const _grpArr = _grp[_p] || _grp.before;
      _grpArr.push({ name: _m.name || '', content: String(_t) });
    }
    const _role = (function () { const r = _s.injectRole !== undefined ? _s.injectRole : 0; if (r === 1) return 'user'; if (r === 2) return 'assistant'; return 'system'; })();
    const _insertRitual = function (msgs, position) {
      if (!msgs.length) return;
      if (position === 'chat') {
        let i2 = Math.floor(chat.length / 2);
        for (const _g of msgs) { const _msg = { role: _role, name: 'Tiêm nghi thức', content: _g.content }; chat.splice(i2++, 0, _msg); }
        cdAddLog('info', '[Tiêm nghi thức] Tiêm giữa cuộc trò chuyện', { 'Số lượng': msgs.length });
      } else if (position === 'before') {
        let i2 = 0;
        while (i2 < chat.length && chat[i2].role === 'system') i2++;
        // Khi tiêm ký ức ở đầu đã được chèn, sẽ chèn vào trước nó; Ở đây thống nhất chèn vào sau tất cả các system
        for (const _g of msgs) { const _msg = { role: _role, name: 'Tiêm nghi thức', content: _g.content }; chat.splice(i2++, 0, _msg); }
        cdAddLog('info', '[Tiêm nghi thức] Tiêm mở đầu', { 'Số lượng': msgs.length });
      } else {
        const ud = Math.max(1, parseInt(_s.injectDepth, 10) || 1);
        let i2 = Math.max(0, chat.length - ud);
        for (const _g of msgs) { const _msg = { role: _role, name: 'Tiêm nghi thức', content: _g.content }; chat.splice(i2++, 0, _msg); }
        cdAddLog('info', '[Tiêm nghi thức] Tiêm cuối', { 'Số lượng': msgs.length });
      }
    };
    _insertRitual(_grp.before, 'before');
    _insertRitual(_grp.chat, 'chat');
    _insertRitual(_grp.after, 'after');
    // idempotent: mark this chat as injected
    if (typeof _cdInjectedChatRefs.add === 'function') { try { _cdInjectedChatRefs.add(chat); } catch (e) {} }
  } catch (e) {
    cdWarn('cdOnBeforeGeneration thất bại', e);
  }
}

/**
 * Chủ động làm mới nội dung tiêm sau mỗi lần viết xong nhật ký
 * Được gọi sau khi cdRunDiary hoàn thành thành công
 */
