/* ============================== Hệ thống nhật ký ============================== */

/** Tên key lưu trữ nhật ký */
const CD_LOG_KEY = 'character-diary-logs';

/** Thêm một dòng nhật ký
 *  @param {'info'|'warn'|'error'|'api_req'|'api_res'} level
 *  @param {string} message
 *  @param {object} [detail] - Dữ liệu bổ sung tùy chọn (Sẽ được serialize thành JSON)
 */
function cdAddLog(level, message, detail) {
  try {
    const logs = JSON.parse(localStorage.getItem(CD_LOG_KEY) || '[]');
    const entry = {
      id: Date.now() + '-' + Math.random().toString(36).slice(2, 6),
      time: new Date().toLocaleString(),
      level: level,
      message: String(message || ''),
      detail: detail !== undefined ? JSON.stringify(detail, null, 2).slice(0, 8000) : '',
    };
    logs.push(entry);
    // Giữ lại 500 dòng gần nhất
    const trimmed = logs.slice(-500);
    localStorage.setItem(CD_LOG_KEY, JSON.stringify(trimmed));
    // Xuất ra console
    const prefix = '[CD-LOG][' + entry.time + '][' + level + ']';
    if (level === 'error') console.error(prefix, message, detail || '');
    else if (level === 'warn') console.warn(prefix, message, detail || '');
    else console.log(prefix, message, detail || '');
  } catch (e) {
    // Bản thân hệ thống nhật ký thất bại không gây block
    console.warn('[CD] Ghi nhật ký thất bại', e);
  }
}

/** Lấy tất cả nhật ký */
function cdGetLogs() {
  try {
    return JSON.parse(localStorage.getItem(CD_LOG_KEY) || '[]');
  } catch (e) {
    return [];
  }
}

/** Xóa rỗng nhật ký */
function cdClearLogs() {
  localStorage.removeItem(CD_LOG_KEY);
}

/** Render giao diện nhật ký (Bao gồm thống kê token/chi phí) */
function cdRenderLog() {
  const logs = cdGetLogs();
  
  // ★ Tính toán token tích lũy và chi phí
  const pricingModels = { flash: { hit: 0.02, miss: 1.00 }, pro: { hit: 0.025, miss: 3.00 } };
  function calcCost(hit, miss, model) {
    const p = pricingModels[model] || pricingModels.flash;
    return (hit / 1000000 * p.hit) + (miss / 1000000 * p.miss);
  }
  // Trích xuất chi tiết token ở cấp độ api_res từ nhật ký
  // ★ detail khi lưu trữ là chuỗi sau khi JSON.stringify, cần parse trước
  let totalPrompt = 0, totalCompletion = 0, totalTokens = 0;
  let totalHit = 0, totalMiss = 0;
  for (const log of logs) {
    if (log.level !== 'api_res') continue;
    let detailObj = null;
    if (log.detail && typeof log.detail === 'string') {
      try { detailObj = JSON.parse(log.detail); } catch(_) {}
    } else if (typeof log.detail === 'object') {
      detailObj = log.detail;
    }
    if (!detailObj) continue;
    
    // ★ Ưu tiên đọc trường giá trị số gốc (Thống kê chính xác)
    if (typeof detailObj.total_tokens === 'number') {
      totalPrompt += detailObj.prompt_tokens || 0;
      totalCompletion += detailObj.completion_tokens || 0;
      totalTokens += detailObj.total_tokens || 0;
    } else if (detailObj.token_usage || detailObj['Lượng dùng token']) {
      // fallback: Phân tích từ định dạng ↑prompt ↓completion = total
      const parts = (detailObj.token_usage || detailObj['Lượng dùng token']).match(/↑(\d+)\s+↓(\d+)\s+=\s+(\d+)/);
      if (parts) {
        totalPrompt += parseInt(parts[1]) || 0;
        totalCompletion += parseInt(parts[2]) || 0;
        totalTokens += parseInt(parts[3]) || 0;
      }
    }
    
    // ★ Thống kê bộ nhớ đệm
    if (typeof detailObj['Cache hit'] !== 'undefined') {
      totalHit += parseInt(detailObj['Cache hit']) || 0;
      totalMiss += parseInt(detailObj['Cache miss']) || 0;
    }
  }
  // Nếu không có tích lũy token chính xác, dùng fallback dữ liệu bộ nhớ đệm để ước tính
  if (totalTokens === 0 && (totalHit > 0 || totalMiss > 0)) {
    totalTokens = totalHit + totalMiss;
  }
  const flashCost = calcCost(totalHit, totalMiss, 'flash');
  const proCost = calcCost(totalHit, totalMiss, 'pro');
  const sessionCost = calcCost(totalHit, totalMiss, 'flash');
  
  let html;
  // ★ Khu vực nút thử nghiệm
  const testBtnHtml = `<div style="margin-bottom:6px;">
    <button class="cd-btn-secondary" id="cd-btn-test-probe" style="width:100%;min-width:90px;"><i class="fa-regular fa-plug"></i> Thử nghiệm API hiện tại</button>
  </div>
  <details class="cds-collapse" style="margin-bottom:8px;"><summary><i class="fa-regular fa-screwdriver-wrench"></i> Thêm công cụ gỡ lỗi</summary>
    <div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:6px;">
      <button class="cd-btn-secondary" id="cd-btn-test-api" style="flex:1;min-width:90px;"><i class="fa-regular fa-flask"></i> Gỡ lỗi API 3 luồng</button>
      <button class="cd-btn-secondary" id="cd-btn-test-trigger" style="flex:1;min-width:90px;"><i class="fa-regular fa-clock"></i> Kiểm tra kích hoạt tự động</button>
      <button class="cd-btn-primary" id="cd-btn-test-summary" style="flex:1;min-width:90px;"><i class="fa-regular fa-wand-magic-sparkles"></i> Giả lập tóm tắt tự động</button>
      <button class="cd-btn-secondary" id="cd-btn-test-cast" style="flex:1;min-width:90px;"><i class="fa-regular fa-people-group"></i> Chẩn đoán nhân vật ra sân</button>
      <button class="cd-btn-secondary" id="cd-btn-test-inject" style="flex:1;min-width:90px;"><i class="fa-regular fa-magnifying-glass"></i> Thử nghiệm tiêm</button>
      <button class="cd-btn-secondary" id="cd-btn-test-kb" style="flex:1;min-width:90px;"><i class="fa-regular fa-keyboard"></i> Chẩn đoán bàn phím</button>
      <button class="cd-btn-secondary" id="cd-btn-test-custom" style="flex:1;min-width:90px;"><i class="fa-regular fa-layer-group"></i> Chẩn đoán mục theo dõi</button>
      <button class="cd-btn-secondary" id="cd-btn-test-worldbook" style="flex:1;min-width:90px;"><i class="fa-regular fa-book-bookmark"></i> Thử nghiệm Worldbook</button>
      <button class="cd-btn-secondary" id="cd-btn-test-hide" style="flex:1;min-width:90px;"><i class="fa-regular fa-eye-slash"></i> Chẩn đoán ẩn tầng</button>
      <button class="cd-btn-secondary" id="cd-btn-test-progress" style="flex:1;min-width:90px;"><i class="fa-regular fa-chart-line"></i> Chẩn đoán tiến độ/lọc trùng</button>
      <button class="cd-btn-secondary" id="cd-btn-test-modal" style="flex:1;min-width:90px;"><i class="fa-regular fa-window-maximize"></i> Thử nghiệm phân cấp popup</button>
    </div>
  </details>`;

  if (!logs.length) {
    html = testBtnHtml + '<div class="cd-empty"><p>Tạm thời chưa có nhật ký</p><p class="cd-empty-sub">Các thao tác viết nhật ký sẽ được ghi lại ở đây</p></div>';
  } else {
    // ★ Thẻ thống kê chi phí
    const statsHtml = totalTokens > 0 ? `
      <div class="cd-log-stats">
        <div class="cd-log-stat-card">
          <span class="cd-log-stat-label"><i class="fa-regular fa-database"></i> Tổng số Token</span>
          <span class="cd-log-stat-value">${totalTokens.toLocaleString()}</span>
        </div>
        <div class="cd-log-stat-card">
          <span class="cd-log-stat-label" style="color:#4ec9b0;"><i class="fa-regular fa-circle-check"></i> Cache hit</span>
          <span class="cd-log-stat-value">${totalHit.toLocaleString()} <span style="font-size: calc(0.6rem * var(--cd-fs, 1));opacity:0.5;">(${totalTokens > 0 ? (totalHit/totalTokens*100).toFixed(1) : 0}%)</span></span>
        </div>
        <div class="cd-log-stat-card">
          <span class="cd-log-stat-label" style="color:#ce9178;"><i class="fa-regular fa-circle-exclamation"></i> Cache miss</span>
          <span class="cd-log-stat-value">${totalMiss.toLocaleString()} <span style="font-size: calc(0.6rem * var(--cd-fs, 1));opacity:0.5;">(${totalTokens > 0 ? (totalMiss/totalTokens*100).toFixed(1) : 0}%)</span></span>
        </div>
        <div class="cd-log-stat-card">
          <span class="cd-log-stat-label"><i class="fa-regular fa-coins"></i> Chi phí (flash)</span>
          <span class="cd-log-stat-value" style="color:#f59e0b;">¥${flashCost.toFixed(4)}</span>
        </div>
        <div class="cd-log-stat-card">
          <span class="cd-log-stat-label"><i class="fa-regular fa-coins"></i> Chi phí (pro)</span>
          <span class="cd-log-stat-value" style="color:#f59e0b;">¥${proCost.toFixed(4)}</span>
        </div>
      </div>
    ` : '';
    
    const items = logs.slice().reverse().map(entry => {
      const iconMap = { info: 'info-circle', warn: 'triangle-exclamation', error: 'xmark-circle', api_req: 'arrow-up', api_res: 'arrow-down' };
      const colorMap = { info: '#6b5a48', warn: '#f59e0b', error: '#c84632', api_req: '#3b82f6', api_res: '#22c55e' };
      const icon = iconMap[entry.level] || 'info-circle';
      const color = colorMap[entry.level] || '#6b5a48';
      const detailHtml = entry.detail ? `<pre class="cd-log-detail">${escapeHtml(entry.detail)}</pre>` : '';
      return `<div class="cd-log-entry cd-log-${entry.level}">
        <span class="cd-log-icon" style="color:${color}"><i class="fa-regular fa-${icon}"></i></span>
        <span class="cd-log-time">${escapeHtml(entry.time)}</span>
        <span class="cd-log-msg">${escapeHtml(entry.message)}</span>
        ${detailHtml}
      </div>`;
    }).join('');
    html = testBtnHtml + `<div class="cd-log-stats-container">${statsHtml}</div><div class="cd-log-list" style="min-height:200px;">${items}</div>
      <div style="display:flex;gap:6px;margin-top:8px;">
        <button class="cd-btn-secondary" id="cd-btn-clear-log" style="flex:1;">Xóa rỗng nhật ký</button>
        <button class="cd-btn-secondary" id="cd-btn-export-log" style="flex:1;"><i class="fa-regular fa-download"></i> Xuất nhật ký</button>
      </div>`;
  }
  $('#cd-content').html(html);
  // ★ Ràng buộc sự kiện nút thử nghiệm
  $('#cd-btn-test-probe').off('click').on('click', cdTestApiProbe);
  $('#cd-btn-test-api').off('click').on('click', cdTestDiary);
  $('#cd-btn-test-trigger').off('click').on('click', cdCheckAutoTrigger);
  $('#cd-btn-test-cast').off('click').on('click', cdDiagCast);
  $('#cd-btn-test-summary').off('click').on('click', async function () {
    toastr.info('Đã giả lập thủ công một lần kiểm tra tóm tắt tự động, vui lòng xem kết quả ở nhật ký bên dưới');
    cdAddLog('info', '[Giả lập thủ công] Bắt đầu giả lập kiểm tra tóm tắt tự động...');
    try { await cdOnMessageReceived(); } catch (e) {
      cdAddLog('error', '[Giả lập thủ công] Quy trình tóm tắt tự động có lỗi: ' + (e && e.message) + ' | ' + (e && e.stack ? e.stack.slice(0, 200) : ''));
    }
    cdAddLog('info', '[Giả lập thủ công] Kiểm tra kết thúc, nếu phía trên không có "Chuẩn bị gọi cdRunDiary" thì có nghĩa là lần này chưa đạt điều kiện kích hoạt');
    cdRenderLog();
  });
  $('#cd-btn-test-inject').off('click').on('click', cdTestInjection);
  $('#cd-btn-test-custom').off('click').on('click', cdTestCustomFields);
  $('#cd-btn-test-worldbook').off('click').on('click', cdTestWorldbook);
  $('#cd-btn-test-hide').off('click').on('click', cdDiagHideFloors);
  $('#cd-btn-test-progress').off('click').on('click', cdDiagProgress);
  $('#cd-btn-test-modal').off('click').on('click', cdTestDedupeModal);
  // ★ Chẩn đoán bàn phím: In ra tham số phán đoán + Thực hiện nâng lên/khôi phục thủ công (Dựa trên vùng che khuất của bảng điều khiển đang focus)
  $('#cd-btn-test-kb').off('click').on('click', function () {
    if(typeof window._cfKbDiag==='function'){ try{ window._cfKbDiag(); }catch(e){} }
    else {
      var msg='Chẩn đoán bàn phím tạm thời không khả dụng (Cần mở diễn đàn trước, đã khởi tạo tương thích)';
      try{ if(typeof cdAddLog==='function') cdAddLog('info','[Chẩn đoán bàn phím] '+msg); }catch(e){}
      if(typeof toastr!=='undefined'&&toastr.info) toastr.info(msg);
    }
  });
  $('#cd-btn-clear-log')?.off('click').on('click', () => { cdClearLogs(); cdRenderLog(); });
  // ★ Xuất nhật ký
  $('#cd-btn-export-log')?.off('click').on('click', function () {
    const logs = cdGetLogs();
    const text = logs.map(log => {
      const time = log.time || '';
      const level = log.level || '';
      const msg = log.message || '';
      const detail = log.detail ? '\n  ' + log.detail : '';
      return `[${time}][${level}] ${msg}${detail}`;
    }).join('\n\n');
    const blob = new Blob([text], { type: 'text/plain;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `Nhật_ký_nhân_vật_${new Date().toISOString().slice(0, 10)}.txt`;
    a.click();
    URL.revokeObjectURL(url);
    toastr.success('Đã xuất nhật ký');
  });
}

/** Snapshot hoàn tác */
let _cdSnapshot = null;
/** Lượng dùng token của lần gọi API gần nhất */
let _cdLastTokenUsage = null;

/**
 * ★ Thử nghiệm 1: Gỡ lỗi API 3 luồng song song, không lưu dữ liệu, không ảnh hưởng đến nhật ký
 */
async function cdTestDiary() {
  const s = cdGetSettings();
  if (!s.enabled) { toastr.warning('Thử nghiệm cần bật plugin trước'); return; }
  
  cdAddLog('info', '========== Thử nghiệm: Gỡ lỗi API 3 luồng ==========');
  
  const data = await cdGetData();
  const windowFloors = await cdGetNewFloors(data);
  if (!windowFloors.length) {
    cdAddLog('warn', 'Thử nghiệm: Không có dữ liệu tầng');
    toastr.info('Không có dữ liệu tầng để thử nghiệm');
    return;
  }
  
  const testFloors = windowFloors.slice(-(s.maxWindowFloors || 40));
  cdAddLog('info', 'Thử nghiệm: Số tầng ' + testFloors.length, {'Bắt đầu': testFloors[0]?.message_id, 'Kết thúc': testFloors[testFloors.length - 1]?.message_id});
  
  const diaryMsgs   = await cdBuildDiaryPrompt(testFloors, data, s);
const relMsgs     = cdBuildRelationPrompt(testFloors, data, s);
    const archiveMsgs = await cdBuildArchivePrompt(testFloors, data, s);
  
  toastr.info('Đang gửi yêu cầu thử nghiệm...');
  const startAll = Date.now();
  const [diaryRes, relRes, archiveRes] = await Promise.allSettled([
    cdApiComplete(diaryMsgs, s),
    cdApiComplete(relMsgs, s),
    cdApiComplete(archiveMsgs, s),
  ]);
  cdAddLog('info', `Thử nghiệm: Tổng thời gian 3 luồng ${Date.now() - startAll}ms`);
  
  // Kết quả nhật ký
  if (diaryRes.status === 'fulfilled') {
    const detail = {'Độ dài': diaryRes.value.text.length, 'Xem trước': diaryRes.value.text.slice(0, 150)};
    if (diaryRes.value.tokenUsage) {
      const tu = diaryRes.value.tokenUsage;
      detail['Lượng dùng token'] = `↑${tu.prompt} ↓${tu.completion} = ${tu.total}`;
      if (tu.cacheHit !== undefined) { detail['Cache hit'] = tu.cacheHit; detail['Cache miss'] = tu.cacheMiss; }
    }
    cdAddLog('info', 'Thử nghiệm [Nhật ký] API thành công', detail);
    try {
      const npcs = parseDiaryJson(diaryRes.value.text);
      cdAddLog('info', 'Thử nghiệm [Nhật ký] Phân tích thành công', {'Số lượng nhân vật': npcs.length, 'Nhân vật': npcs.map(n => n.name)});
    } catch (e) { cdAddLog('warn', 'Thử nghiệm [Nhật ký] Phân tích thất bại: ' + e.message, {'200 chữ đầu bản gốc': diaryRes.value.text.slice(0, 200)}); }
  } else {
    cdAddLog('error', 'Thử nghiệm [Nhật ký] API thất bại: ' + (diaryRes.reason?.message || ''));
  }
  
  // Kết quả quan hệ
  if (relRes.status === 'fulfilled') {
    const detail = {'Độ dài': relRes.value.text.length, 'Xem trước': relRes.value.text.slice(0, 100)};
    if (relRes.value.tokenUsage) {
      const tu = relRes.value.tokenUsage;
      detail['Lượng dùng token'] = `↑${tu.prompt} ↓${tu.completion} = ${tu.total}`;
      if (tu.cacheHit !== undefined) { detail['Cache hit'] = tu.cacheHit; detail['Cache miss'] = tu.cacheMiss; }
    }
    cdAddLog('info', 'Thử nghiệm [Quan hệ] API thành công', detail);
    try {
      const rels = parseRelationJson(relRes.value.text);
      cdAddLog('info', 'Thử nghiệm [Quan hệ] Phân tích thành công', {'Số lượng quan hệ': rels.length});
    } catch (e) { cdAddLog('warn', 'Thử nghiệm [Quan hệ] Phân tích thất bại: ' + e.message, {'200 chữ đầu bản gốc': relRes.value.text.slice(0, 200)}); }
  } else {
    cdAddLog('error', 'Thử nghiệm [Quan hệ] API thất bại: ' + (relRes.reason?.message || ''));
  }
  
  // Kết quả hồ sơ cốt truyện
  if (archiveRes.status === 'fulfilled') {
    const detail = {'Độ dài': archiveRes.value.text.length, 'Xem trước': archiveRes.value.text.slice(0, 100)};
    if (archiveRes.value.tokenUsage) {
      const tu = archiveRes.value.tokenUsage;
      detail['Lượng dùng token'] = `↑${tu.prompt} ↓${tu.completion} = ${tu.total}`;
      if (tu.cacheHit !== undefined) { detail['Cache hit'] = tu.cacheHit; detail['Cache miss'] = tu.cacheMiss; }
    }
    cdAddLog('info', 'Thử nghiệm [Hồ sơ cốt truyện] API thành công', detail);
    try {
      const customDefs = Array.isArray(s.customFields) ? s.customFields : [];
      const arc = parseArchiveJson(archiveRes.value.text, customDefs);
      // Xem trước phân tích trường tùy chỉnh
      const customPreview = {};
      for (const def of customDefs) {
        if (def && def.key) {
          const arr = (arc.custom && arc.custom[def.key]) || [];
          customPreview[def.label || def.key] = arr.map(it => `${it.time || ''} ${(it.desc || '').slice(0, 40)}`).slice(0, 3);
        }
      }
      if (arc.mainline || arc.sideline || arc.states || arc.unresolved || (arc.items && arc.items.length) || Object.keys(customPreview).length) {
        cdAddLog('info', 'Thử nghiệm [Hồ sơ cốt truyện] Phân tích thành công', {'Tuyến chính': arc.mainline?.slice(0, 80), 'Tuyến phụ': arc.sideline?.slice(0, 80), 'Trạng thái': arc.states?.slice(0, 80), 'Chưa giải quyết': arc.unresolved?.slice(0, 80), 'Vật phẩm': (arc.items || []).map(it => `${it.time || ''} ${(it.desc || '').slice(0, 40)}`).slice(0, 5), 'Tùy chỉnh': customPreview});
      } else {
        cdAddLog('warn', 'Thử nghiệm [Hồ sơ cốt truyện] Phân tích rỗng', {'300 chữ đầu bản gốc': archiveRes.value.text.slice(0, 300)});
      }
    } catch (e) { cdAddLog('warn', 'Thử nghiệm [Hồ sơ cốt truyện] Phân tích thất bại: ' + e.message, {'200 chữ đầu bản gốc': archiveRes.value.text.slice(0, 200)}); }
  } else {
    cdAddLog('error', 'Thử nghiệm [Hồ sơ cốt truyện] API thất bại: ' + (archiveRes.reason?.message || ''));
  }
  
  cdAddLog('info', '========== Kết thúc thử nghiệm ==========');
  toastr.success('Thử nghiệm hoàn tất, vui lòng xem chi tiết ở bảng nhật ký');
  cdSwitchView('log');
}

/**
 * ★ Thử nghiệm kết nối API hiện tại
 * Lấy url/key/model đã điền trong bảng cài đặt hiện tại để gửi trực tiếp một yêu cầu cực ngắn qua fetch, hiển thị mã trạng thái HTTP thực tế và 300 chữ đầu của phần thân phản hồi.
 * Giúp người dùng nhìn qua là xác định được: Là do trình duyệt chặn CORS/Preflight (Failed to fetch), hay là lỗi từ bản thân gateway/key/mô hình.
 */
async function cdTestApiProbe() {
  const s = cdGetSettings();
  let src = window._cdEditSource || s.source || 'openai';
  if (src === 'tavern' || src === 'gemini') {
    const o = s.endpoints?.openai?.url ? 'openai' : s.endpoints?.claude?.url ? 'claude' : s.endpoints?.gemini?.url ? 'gemini' : '';
    if (o) src = o;
  }
  const ep = s.endpoints?.[src] || {};
  const url0 = (ep.url || '').trim();
  const key0 = (ep.key || '').trim();
  const mod0 = (ep.model || '').trim();
  cdAddLog('info', '[Thăm dò API] Bắt đầu thử nghiệm API hiện tại', { 'Nguồn': src, 'Địa chỉ': url0 || '(Trống)', 'Mô hình': mod0 || '(Trống)' });
  if (!url0) { cdAddLog('warn', '[Thăm dò API] Chưa điền địa chỉ API, vui lòng điền vào Nguồn API ở phía trên trước'); return; }
  const base = url0.replace(/\/+$/, '');
  const body = { model: mod0 || '', messages: [{ role: 'user', content: 'ping' }], max_tokens: 5, stream: false };
  const startMs = Date.now();
  try {
    const res = await fetch(base + '/chat/completions', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + key0 },
      body: JSON.stringify(body),
    });
    const dur = Date.now() - startMs;
    const txt = await res.text();
    cdAddLog('info', '[Thăm dò API] Kết nối trực tiếp đã gửi yêu cầu và trả về', {
      'Mã trạng thái': res.status, 'Thời gian tốn (ms)': dur, '200 chữ đầu phần thân phản hồi': txt ? txt.slice(0, 200) : '(Trống)',
      'Kết luận': res.status >= 200 && res.status < 300 ? 'API+Key+Mô hình tất cả đều khả dụng ✔' : 'API có phản hồi nhưng không thành công, vui lòng kiểm tra theo mã trạng thái',
    });
    if (typeof toastr !== 'undefined') {
      if (res.status >= 200 && res.status < 300) toastr.success('Thăm dò API: API khả dụng ✔');
      else toastr.warning('Thăm dò API: API trả về ' + res.status);
    }
  } catch (err) {
    const dur = Date.now() - startMs;
    const msg = String((err && err.message) || err);
    const isCors = /failed to fetch|load failed|networkerror|not allowed|cors|typeerror/i.test(msg);
    cdAddLog(isCors ? 'warn' : 'error', '[Thăm dò API] Kết nối trực tiếp không thành công thường do bị chặn CORS/Preflight, vui lòng bật "Kết nối trực tiếp qua proxy backend" hoặc kiểm tra lại địa chỉ', {
      'Lỗi': msg, 'Thời gian tốn (ms)': dur, 'Kết nối trực tiếp bị chặn': isCors,
      'Đề xuất': isCors ? 'Loại lỗi bị chặn CORS/Preflight này là vấn đề ở phía trình duyệt, không phải lỗi key; Hãy bật "Kết nối trực tiếp qua proxy backend" hoặc chuyển sang dùng gateway có hỗ trợ CORS' : 'Không phải lỗi CORS, vui lòng kiểm tra địa chỉ/key/mạng',
    });
    if (typeof toastr !== 'undefined') toastr.warning(isCors ? 'Thăm dò API: Trình duyệt kết nối trực tiếp bị chặn CORS/Preflight, vui lòng qua proxy backend' : 'Thăm dò API: Yêu cầu có lỗi, xem nhật ký');
  }
}

/**
 * ★ Thử nghiệm 2: Kiểm tra trạng thái kích hoạt tự động
 * Xem số tầng AI hiện tại, còn cách lần kích hoạt tự động tiếp theo bao nhiêu tầng
 */
async function cdCheckAutoTrigger() {
  const s = cdGetSettings();
  if (!s.enabled) { toastr.warning('Plugin chưa được bật'); return; }
  if (s.autoSummary === false) { toastr.warning('Tóm tắt tự động đã tắt'); return; }
  
  const data = await cdGetData();
  const chat = _cdGetChat();
  const currentLen = chat.length;
  const baseline = data._baselineChatLength ?? -1;
  const interval = s.interval || 5;
  
  // Logic giống với cdOnMessageReceived
  const validBaseline = (baseline >= currentLen) ? 0 : Math.max(0, baseline);
  let aiCount = 0;
  for (let i = validBaseline; i < currentLen; i++) {
    const m = chat[i];
    if (m && m.mes && String(m.mes).trim()) aiCount++;
  }
  
  cdAddLog('info', '========== Kiểm tra kích hoạt tự động ==========');
  cdAddLog('info', `chat.length: ${currentLen}, Đường cơ sở: ${baseline}, Đường cơ sở hợp lệ: ${validBaseline}`);
  cdAddLog('info', `Tầng mới thêm sau đường cơ sở: ${aiCount}/${interval}`);
  
  const sample = chat.slice(0, 5).map((m, i) => ({idx: i, is_user: m.is_user, is_system: m.is_system, name: m.name, mes_preview: (m.mes||'').slice(0,30)}));
  cdAddLog('info', '5 mẫu chat đầu tiên', sample);
  
  if (aiCount >= interval) {
    cdAddLog('info', `✓ Đã thỏa mãn điều kiện kích hoạt (${aiCount} >= ${interval})`);
    toastr.success(`Đã thỏa mãn điều kiện kích hoạt, gửi tin nhắn nữa sẽ tự động viết nhật ký`);
  } else {
    const need = interval - aiCount;
    cdAddLog('info', `Cần thêm ${need} tầng nữa mới kích hoạt tóm tắt tự động`);
    toastr.info(`Cần thêm ${need} tầng nữa để kích hoạt tóm tắt tự động (Hiện tại ${aiCount}/${interval})`);
  }
  
  cdAddLog('info', '========== Kết thúc kiểm tra ==========');
  cdSwitchView('log');
}

/**
 * ★ Ẩn các tầng cũ đã tóm tắt, chỉ giữ lại N tầng mới nhất hiển thị (Người dùng + AI đều tính là tầng).
 * Phương án B: Gọi lệnh /hide gốc của ST (TauriTavern render biểu tượng bóng ma nguyên bản, có thể /unhide để khôi phục, AI bỏ qua).
 * Số tầng hiển thị được giữ lại: keepCount (autoHideKeep, N tầng mới nhất).
 */
/** ========== Ẩn tầng·Phương án B (Gọi lệnh /hide gốc, TauriTavern render biểu tượng bóng ma nguyên bản, có thể /unhide để khôi phục)========== */
/** Gộp mảng chỉ số tăng dần thành các khoảng liên tục [[start,end],...] (Dành cho lệnh /hide N-N gốc sử dụng hàng loạt) */
function cdCoalesceRanges(sortedIdx) {
  const out = [];
  if (!Array.isArray(sortedIdx) || !sortedIdx.length) return out;
  const arr = sortedIdx.slice().sort(function (a, b) { return a - b; });
  let s = arr[0], e = arr[0];
  for (let i = 1; i < arr.length; i++) {
    if (arr[i] === e + 1) { e = arr[i]; continue; }
    out.push([s, e]); s = arr[i]; e = arr[i];
  }
  out.push([s, e]);
  return out;
}
/** Xác định xem một tin nhắn có phải là tầng "bị HCDiary ẩn" hay không (Dùng cờ riêng extra.cd_hidden để phân biệt, tránh nhầm lẫn với tin nhắn hệ thống gốc) */
