    const chat = ctx.chat;
    // Thu thập chỉ số tầng "bị HCDiary ẩn" (is_system+cd_hidden hoặc is_hidden)
    const hideSet = {};
    for (let i = 0; i < chat.length; i++) { const m = chat[i]; if (m && cdIsHCHidden(m)) hideSet[i] = true; }
    if (!Object.keys(hideSet).length) return;
