function cdTgApplyReplace(text, n) {
  text = String(text || '');
  const u = (n && n.userRep) || (n && n.userName) || 'user';
  const c = (n && n.chatRep) || (n && n.chatName) || 'chat';
  text = text.replace(/{{user}}|<user>|\{user\}/gi, u);
  text = text.replace(/{{chat}}|<chat>|\{chat\}/gi, c);
  return text;
}
