    _box.style.cssText='position:fixed;left:0;top:0;width:100%;height:100%;z-index:2147483647;background:rgba(20,24,28,.45);display:flex;align-items:center;justify-content:center;padding:20px;box-sizing:border-box;';
    var _card=document.createElement('div');
    _card.style.cssText='width:min(330px,92vw);background:#fff;border:1px solid #dde5e2;border-radius:16px;box-shadow:0 18px 50px rgba(0,0,0,.30);padding:15px;display:flex;flex-direction:column;gap:9px;box-sizing:border-box;color:#2a3a33;';
    var _title=document.createElement('div');
    _title.style.cssText='font-size:12px;font-weight:800;color:#2f5d50;display:flex;align-items:center;gap:6px;margin-bottom:1px;'; _title.textContent='Đăng bài';
    var _lbl1=document.createElement('div'); _lbl1.style.cssText='font-size:9px;font-weight:700;color:#8b9590;margin-top:1px;'; _lbl1.textContent='Tiêu đề';
    var _ipt1=document.createElement('input'); _ipt1.type='text'; _ipt1.placeholder='Tiêu đề (Tùy chọn)';
    _ipt1.style.cssText='width:100%;border:1px solid #dde5e2;border-radius:9px;background:#fafcfb;color:#2a3a33;font-size:11px;padding:7px 9px;outline:none;box-sizing:border-box;';
    var _lbl2=document.createElement('div'); _lbl2.style.cssText='font-size:9px;font-weight:700;color:#8b9590;margin-top:1px;'; _lbl2.textContent='Nội dung';
    var _ipt2=document.createElement('textarea'); _ipt2.placeholder='Nói gì đó...';
    _ipt2.style.cssText='width:100%;min-height:74px;border:1px solid #dde5e2;border-radius:9px;background:#fafcfb;color:#2a3a33;font-size:11px;padding:7px 9px;outline:none;box-sizing:border-box;resize:vertical;line-height:1.6;';
    // Từ hộp nhập liệu dưới cùng mang vào nội dung đã có
    try{ var _np0=R.querySelector('#newPost'); if(_np0 && _np0.value && _np0.value.trim()) _ipt2.value=_np0.value; }catch(_e){}
    var _row=document.createElement('div'); _row.style.cssText='display:flex;align-items:center;gap:8px;font-size:9.5px;color:#5a7d72;font-weight:600;';
    var _imgCb=document.createElement('input'); _imgCb.type='checkbox'; _imgCb.id='cd-dyn-edit-img'; _imgCb.style.cssText='accent-color:#2f8a7a;';
    var _imgLb=document.createElement('label'); _imgLb.textContent='Kèm ảnh'; _imgLb.style.cssText='display:flex;align-items:center;gap:4px;cursor:pointer;';
    _imgLb.insertBefore(_imgCb, _imgLb.firstChild);
    var _pubCb=document.createElement('input'); _pubCb.type='checkbox'; _pubCb.checked=!!isPublic; _pubCb.id='cd-dyn-edit-pub'; _pubCb.style.cssText='accent-color:#2f8a7a;margin-left:8px;';
    var _pubLb=document.createElement('label'); _pubLb.textContent = isPublic?'Công khai':'Riêng tư'; _pubLb.style.cssText='display:flex;align-items:center;gap:4px;cursor:pointer;';
    _pubLb.insertBefore(_pubCb, _pubLb.firstChild);
    _row.appendChild(_imgLb); _row.appendChild(_pubLb);
    // ---- Chọn ảnh thật từ album (Lối vào dấu cộng): Chọn ảnh -> Xem trước -> Khi đăng dùng làm ảnh kèm bài (imgKey) ----
    var _pickArea=document.createElement('div');
    _pickArea.style.cssText='display:flex;align-items:center;gap:8px;';
    var _pickBtn=document.createElement('button'); _pickBtn.type='button';
    _pickBtn.style.cssText='display:inline-flex;align-items:center;gap:5px;padding:6px 11px;border:1px solid #bcd0da;background:#eef5f8;color:#3f6d84;border-radius:9px;font-size:10px;font-weight:700;cursor:pointer;';
    _pickBtn.innerHTML='<svg viewBox="0 0 24 24" style="width:12px;height:12px;fill:none;stroke:currentColor;stroke-width:2;" aria-hidden="true"><path d="M12 5v14M5 12h14"/></svg>Chọn ảnh từ album';
    var _pickFile=document.createElement('input'); _pickFile.type='file'; _pickFile.accept='image/*'; _pickFile.style.display='none';
    var _pickPrev=document.createElement('div');
    _pickPrev.style.cssText='display:none;align-items:center;gap:7px;flex:1;min-width:0;';
    var _pickImg=document.createElement('img');
    _pickImg.style.cssText='width:38px;height:38px;object-fit:cover;border-radius:8px;border:1px solid #c8d6cf;flex-shrink:0;';
    var _pickTxt=document.createElement('span'); _pickTxt.style.cssText='font-size:9px;color:#4a8571;flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;'; _pickTxt.textContent='Đã chọn ảnh album';
    var _pickClear=document.createElement('button'); _pickClear.type='button';
    _pickClear.style.cssText='flex-shrink:0;padding:3px 9px;color:#c84632;border:1px solid #e0b8ae;background:#fdf0ec;border-radius:7px;font-size:9px;font-weight:700;cursor:pointer;'; _pickClear.textContent='Hủy';
    _pickPrev.appendChild(_pickImg); _pickPrev.appendChild(_pickTxt); _pickPrev.appendChild(_pickClear);
    _pickArea.appendChild(_pickBtn); _pickArea.appendChild(_pickFile); _pickArea.appendChild(_pickPrev);
    _card.appendChild(_pickArea);
    _pickBtn.addEventListener('click',function(){ try{ _pickFile.click(); }catch(_e){ try{ if(typeof toastr==='function') toastr.error('Không thể mở bộ chọn album'); }catch(_e2){} } });
    _pickFile.addEventListener('change',function(){
      var f=(_pickFile.files&&_pickFile.files[0]); if(!f) return;
      try{
        var _fr=new FileReader();
        _fr.onload=function(){
          var _dataUrl=String(_fr.result||'');
          var _key='plc_'+Date.now()+'_'+Math.floor(Math.random()*1e6);
          try{ cdForumImgAdd({ key:_key, dataUrl:_dataUrl, title:'Chọn ảnh đăng bài', author:'', text:'', time:Date.now() }); }catch(_e){}
          _editPickKey=_key;               // Cùng một biến, doPublish sẽ lấy nó làm imgKey của bài đăng
          _pickImg.src=_dataUrl; _pickBtn.style.display='none'; _pickPrev.style.display='flex';
          try{ if(typeof toastr==='function') toastr.success('Đã chọn ảnh album'); }catch(_e){}
        };
        _fr.onerror=function(){ try{ if(typeof toastr==='function') toastr.error('Đọc ảnh thất bại'); }catch(_e){} };
        _fr.readAsDataURL(f);
      }catch(e){ try{ if(typeof toastr==='function') toastr.error('Chọn ảnh thất bại'); }catch(_e2){} }
      _pickFile.value='';
    });
    _pickClear.addEventListener('click',function(){ _editPickKey=''; _pickPrev.style.display='none'; _pickBtn.style.display='inline-flex'; });
    var _btns=document.createElement('div'); _btns.style.cssText='display:flex;justify-content:flex-end;gap:8px;margin-top:3px;';
    var _cancel=document.createElement('button'); _cancel.textContent='Hủy';
    _cancel.style.cssText='border:1px solid #dde5e2;background:#f5f8f6;color:#5a6a63;font-size:10px;font-weight:700;border-radius:8px;padding:7px 14px;cursor:pointer;';
    var _send=document.createElement('button'); _send.textContent='Đăng';
    _send.style.cssText='border:none;background:linear-gradient(135deg,#2f8a7a,#1f6a5c);color:#fff;font-size:10px;font-weight:700;border-radius:8px;padding:7px 18px;cursor:pointer;';
    _btns.appendChild(_cancel); _btns.appendChild(_send);
    _card.appendChild(_title); _card.appendChild(_lbl1); _card.appendChild(_ipt1); _card.appendChild(_lbl2); _card.appendChild(_ipt2); _card.appendChild(_row); _card.appendChild(_btns);
    _box.appendChild(_card);
    try{ _mount.appendChild(_box); }catch(_ae){ try{ if(typeof cdAddLog==='function') cdAddLog('error','[Diễn đàn][Chẩn đoán đăng bài] Gắn lớp động thất bại '+(_ae&&_ae.message)); }catch(_e2){} }
    _cfDynEditor=_box;
    try{ if(typeof cdAddLog==='function') cdAddLog('info','[Diễn đàn][Chẩn đoán đăng bài] Lớp động đã được gắn, mount='+(_mount&&_mount.id||_mount&&_mount.nodeName)); }catch(_e){}
    _ipt2.focus();
    _cancel.onclick=function(){ _editPickKey=''; try{ if(_box.parentNode) _box.parentNode.removeChild(_box); }catch(_e){} _cfDynEditor=null; };
    _box.onmousedown=function(e){ if(e.target===_box){ _editPickKey=''; try{ if(_box.parentNode) _box.parentNode.removeChild(_box); }catch(_e2){} _cfDynEditor=null; } };
