  if(npInp) npInp.addEventListener('focus',function(){ try{ if(typeof cdAddLog==='function') cdAddLog('info','[Diễn đàn][Chẩn đoán đăng bài] Kích hoạt newPost focus, gọi openEditor'); }catch(_e){} openEditor(); });
