/* ------------------------------------------------------------
 * Tự động tạo (Mỗi N tin nhắn tự động tạo bài đăng)
 * Kết nối vào MESSAGE_RECEIVED khi khởi tạo; chỉ chạy khi diễn đàn được enabled.
 * ------------------------------------------------------------ */
var _cfAutoCount = 0;
var _cfAutoWired = false;
function cdForumAutoWire(){
  if(_cfAutoWired) return;
  _cfAutoWired = true;
  try{
    var ctx = SillyTavern.getContext();
    var es = ctx && ctx.eventSource ? ctx.eventSource : (typeof eventSource !== 'undefined' ? eventSource : null);
    var et = ctx && ctx.event_types ? ctx.event_types : (typeof event_types !== 'undefined' ? event_types : null);
    if(!es || !et || !et.MESSAGE_RECEIVED) return;
    es.on(et.MESSAGE_RECEIVED, function(){
      var s = cdGetSettings();
      if(!(s && s.forum && s.forum.enabled !== false)) return;
      var cfg = cdForumCfg();
      // Công tắc tổng tự động đăng bài (thanh gập "Tự động đăng bài"): Nếu tắt thì không đếm, không kích hoạt
      if(cfg && cfg.autoGen === false) return;
      var every = cfg.autoEvery || 5;
      _cfAutoCount++;
      if(_cfAutoCount >= every){
        _cfAutoCount = 0;
        cdForumAutoGenerate();
      }
    });
  }catch(e){ cdWarn('[Diễn đàn] Kết nối tự động tạo thất bại', e); }
}
async function cdForumAutoGenerate(){
  try{
    if(!cdForumApiReady()) return;
    var s = cdGetSettings();
    if(!(s && s.forum && s.forum.enabled !== false)) return;
    var worlds = cdForumGetWorlds();
    var _st=cdForumCfg(); _st=(_st&&_st.selTypes&&_st.selTypes.length)?_st.selTypes.slice():null;
    var newPosts = await cdForumGeneratePosts(worlds, _st, 1, (cdForumCfg().customPrompt||''), !!(cdForumCfg().erotica));
    if(newPosts && newPosts.length){
      var POSTS = cdForumGetPosts();
      var added=[];
      for(var k=newPosts.length-1;k>=0;k--){
        var p=newPosts[k];
        if(!Array.isArray(p.replies)) p.replies=[];
        var rr=cdForumCfg().repCount||6;
        // Không bù template người qua đường cố định —— phản hồi do AI tạo
        POSTS.unshift(p); added.push(p.title);
      }
      _cfPostsCache=POSTS; cdForumPersist();
      try{ if(typeof cdForumCheckAt==='function') cdForumCheckAt(newPosts); }catch(_e2){}
      try{ toastr.success('[Diễn đàn] Tự động tạo bài đăng: ' + (added.join(', ')||'vài bài')); }catch(e){}
    }
  }catch(e){ cdWarn('[Diễn đàn] Thực thi tự động tạo thất bại', e); }
}

