        out.push({ name: nick, av: (nick || '?')[0], grad: _phGrad(nick), tag: (mnote || 'Thêm thủ công'), diaryCount: 0, aff: 0, latest: '', diaryTexts: [], medium: 'normal', mediumNote: 'Có điện thoại, gõ phím bình thường', onlineRate: 1, status: 'Online', statusRate: 1, _manual: true });
